# ---- C17 摆位必入画（model-adapters §5.0.1 人物账连续）----
# ★内部 ID 前缀兼容（2026-10-12 修复）：包内 12 个规范文件（model-adapters / seedance-render-engine /
#   acting-direction / production-ledger-handbook 等）的示例长期写成 `@CHR-老周` /
#   `@SCN-地下拳房` 编号式，而镜行正文按惯例用简称「老周」。原正则把 `CHR-老周` 整体捕获，
#   与镜行简称永远匹配不上 → C17 摆位必入画 / C17b 关系镜 / C17c 背景锚点 / C17d 跨段漂移 /
#   C19c 首镜主体优先 **五条判据对编号式稿件全体误报**（实测 历史示例稿 连报 4 条）。
#   前缀列为非捕获组，group(1) 恒为裸人名；`@老周` 纯净式不受影响。
#   ⚠️ 注意：`asset-delivery-modes.md` 红线 11 明令「接线单不写内部 ID」——本兼容只为让机检
#   不误伤存量示例，**不构成对编号式写法的认可**，新稿仍应写 `@人名`。
ZW_PERSON_RE = re.compile(r"@(?:(?:CHR|SCN|PRP|ITM|PROP|ENV|OBJ)-)?([^\s@（）()【】，、；;：:]+)")
C17_EXIT_WORDS = ("离画", "退场", "离场", "出画", "未入镜", "不入镜")

# ★站位人物宽松兜底解析（2026-10-11 新增 · 与 C7c 元检查配套）：
# 病根：规范格式是 `@人名（画面右 · …）`，但实跑稿常写成 `A（画面右 · …）`（漏 `@`）——
# 此时 ZW_PERSON_RE 解析为空，C17 摆位必入画 / C17b 关系镜 / C17c 背景锚点 /
# C17d 跨段站位漂移 / C19c 首镜主体优先 **五条判据整体静默失效**，脚本却照打 PASSED。
# 兜底：按 `、；;` 切 token，剥掉【站位声明】前缀后要求「名（」紧邻——宽松，但不会把
# 「位移：C 自身后门边…（画面左后）」这类从句误认成人名（名后若跟 `：` 或长串即失配）。
_ZW_LOOSE_HEAD = re.compile(r"^(?![@【])([^\s（(【】：:]{1,14})\s*[（(]")


def _zw_people_loose(block):
    """宽松解析站位声明人物名（仅在 `@` 式解析为空时兜底调用）。"""
    out = []
    for tok in re.split(r"[、；;]", block or ""):
        t = re.sub(r"^\s*【站位声明】\s*[：:]\s*", "", tok.strip())
        m = _ZW_LOOSE_HEAD.match(t)
        if m:
            name = m.group(1).strip()
            if name and name not in out:
                out.append(name)
    return out

