# 正解：首镜锚定句只由**一个具名主体**统摄，身体部位一律以「她的/其+部位」从属出现。
MULTI_SUBJ_RE = re.compile(r"同框|同在画面|一同入画|同时入画|与[^。；，]{1,8}同(处|在|入)")
