# ---- C22 打戏节奏与渲染负载护栏（sd-combat-engine/references/combat-rhythm-and-load-guardrails.md）----
# 病根档案（勿删）：稿机检 PASSED/0 error/0 warning，出片仍"呆滞·像小孩打架"。逐帧复盘四条病根：
#   ① 一镜塞多动作。铁律26 第7条「每2秒主动作≤3」与铁律0 第1步「一镜一主任务，不贪多」**规则不缺**，
#      但二者从未被抬进打戏引擎第5步自检闸口，而交付走的是总控七段式链 → **A 引擎的硬约束在 B 链失效**。
#      实测 V2 稿四镜主任务数 = 1/2/4/3，镜头3 一次塞了「捅入+角力+拽倒+滚地互殴」。
#   ② 单镜匀速。铁律45 ④速度节奏交替是"禁止连续5镜不变"的**下限型**判据，
#      没有"一镜内部必须有速度层次"的概念 → 全片匀速它查不出。铁律26 九要素**零项是"时间拍"**。
#      实测「蓄力/预备」命中 0 次。
#   ③ 缺全身景别。铁律45 ③只要求景别"交替"，未要求"必须含全身档" → 中近景→近景→特写→大远景，
#      全片无全身入画的中景 → 看不见重心与位移幅度，只剩"撞来撞去"的读感。
#   ④ "模型 3 秒可靠渲染 2~3 个动作单元"这条硬约束**全包 115 份库零命中** → 上限无根。
# ★ 与 C21 的分工：C21 管激烈度（下限型·不许躺平）；C22 管负载与节奏（**含上限型·不许过载**）。
#   C1~C26 全部 C 码中仅 C14（OS/VO 配额）带上限语义，**打戏域零条上限型判据**
#   → 稿子越密 C21 越易满足，护栏方向上反向鼓励内卷。C22a/C22b 即补此缺。
COMBAT_IAU_RE = re.compile(
    r"撩斩|斩中|劈中|劈碎|劈开|挑刺|刺中|捅入|横扫|竖劈|剪斩|扫腿|扫堂|踢中|踹中|"
    r"顶中|肘击|膝顶|点中|拍中|砸中|撞中|撞碎|扑击|砸在|撞在|劈在|"
    r"揪住|扼住|勒住|擒住|"
    r"格挡|架住|架开|格开|磕开|硬接|硬扛|对撞|交击|兵器相击|拳掌相交")
# 「抓住」只在带宾语时算一次独立动作（否则「两人角力」的日常叙述会误计）
# ⚠️ 构建期踩坑三：初版写作 `抓住(?=脚踝|…)` 零宽前瞻，**假设宾语紧邻**，
#    而实际镜行常夹人名（实测「一爪抓住剑修脚踝」「抓住剑修手腕」全部漏计 → IAU 计 0）。
#    正法：宾语与人名之间允许 0~6 字任意实词。
COMBAT_IAU_GRAB_RE = re.compile(
    r"抓住[\u4e00-\u9fa5@]{0,6}?(?:脚踝|手腕|剑刃|剑身|兵器|骨爪|衣领|后颈|喉|肩|臂)")
# C22b 一镜多任务：动作类型分类（铁律0 第1步六选一任务的细分）
COMBAT_TACTIC_RE = re.compile(r"剑气|剑罡|法术|法阵|符|咒|法相|剑意|刀光|掌风")
COMBAT_TACTIC_TYPES = {
    "兵器": re.compile(r"撩斩|斩中|劈中|劈碎|劈开|挑刺|刺中|捅入|横扫|竖劈|剪斩|扫腿|扫堂|兵器相击|刀光"),
    "拳脚": re.compile(r"踢中|踹中|顶中|肘击|膝顶|点中|拍中|砸中|拳掌相交"),
    "投技/擒拿": re.compile(r"抓住[\u4e00-\u9fa5@]{0,6}?(?:脚踝|手腕|剑刃|剑身|衣领|后颈|喉|肩|臂)|"
                          r"揪住|扼住|勒住|擒住"),
    "撞碎/破防": re.compile(r"撞中|撞碎|撞在|砸在|劈在|硬接|硬扛|对撞|交击"),
    "法术/特效": COMBAT_TACTIC_RE,
}
# 镜内速度四拍（§2.1）——按拍分类，**逐镜判定**
COMBAT_BEAT_RE = {
    "起": re.compile(r"沉肩|压低重心|碾碎|绷紧|屏息|蓄力|蓄势|预备|屈膝|后仰|重心下压|攒"),
    "爆": re.compile(r"暴起|骤然|猛地|瞬间|陡然|疾掠|扑上|冲出|甩出|弹射|暴涌"),
    # ★2026-10-16 补「停顿」（「停顿」子串覆盖文档规范措辞「Hit-Stop 微停顿」，camera-specs-15rules.md §二）：
    #   原表无「停顿」→ 为规避 C18g 把镜行头改写成「固定」的执行者会立刻被 C22c 报"缺「顿」"——
    #   同一稿同一镜被两门夹杀、**执行者无合规写法**（粉丝排查报告核验属实 · 已复现）。
    "顿": re.compile(r"顿住|时停|顿帧|定格|凝固|压在|静止|停顿"),
    "收": re.compile(r"卸力|稳住|侧滑|滑退|收势|滑步|落地缓冲|后撤|站定|单膝|卸掉冲势"),
}
# 全身入画档（能同时看见重心与双脚）vs 贴脸档（只能看见接触点）
COMBAT_FULL_SIZE = ("中全景", "中景", "全景", "大远景")
COMBAT_TIGHT_SIZE = ("特写", "近景", "中近景")
COMBAT_TIGHT_MAX_RUN = 2          # 贴脸档连续上限
# ★ 结构标注剥离：只剥离 ≤6 字的纯结构标签，**不得连坐含实写正文的括号块**
#   （构建期实测：贪婪写法 `（[^）]*(?:拍|帧)[^）]*）` 会把
#    「（命中瞬间画面顿住两帧，命中点炸开一圈冲击波）」整块吃掉 → 镜头4 明明写了顿帧却误报缺失。）
COMBAT_STRUCT_TAGS = frozenset((
    "起手拍，慢", "爆发拍，快", "顿帧", "收势拍，慢", "转折",
    "起手拍", "爆发拍", "收势拍", "假动作", "战术变化",
))
# ★ 让行条款（2026-10-12 用户裁定 · 勿删）：C21/C22 是 **WARN 参考**，不是一票否决——
#   判据原型取自「现代近身肉搏」单样本，不外推为全戏型法规；打戏档（R1/R2/R3）领域规则
#   以打戏引擎本档为准。现场景按豁免表放行（R1 枪战/狙击/暗杀/追车/儿童向、近景机枪对招段，
#   R3 大场面档/术法对轰·远程档，群战乱斗）。豁免表唯一权威 =
#   sd-combat-engine/references/combat-rhythm-and-load-guardrails.md §七（+ combat-intensity-guardrails.md §六）。
#   ⛔ 禁止为消除 C21/C22 告警而把打戏改呆（拆招式序列 / 近景对招拉远景 / 每镜硬塞慢动作）。
COMBAT_EGRESS = ("〔参考·打戏档可豁免：R1 枪战/狙击/暗杀/追车/儿童向 · R3 大场面/术法对轰 · 群战乱斗 "
                 "按 combat-rhythm-and-load-guardrails.md §七 放行，非一票否决〕")


def _strip_struct_annot(s):
    """剔除纯结构标注（给人看的标签），保留含实写正文的括号块。

    ⚠️ 构建期踩坑二：单纯用「≤6 字且不含逗号」当标签，会把
    `（咬牙·闷哼）` 这类**台词语气说明**误删——它虽短，但属正文。
    正法：白名单命中才剥；非白名单一律保留（宁可漏剥，不可误删正文造成假阴性）。
    """
    def _rep(m):
        inner = m.group(0)[1:-1].strip()
        return "" if inner in COMBAT_STRUCT_TAGS else m.group(0)
    return re.sub(r"（([^）]*)）", _rep, s)


def _combat_iau(pic):
    """统计一个镜行的独立动作单元（IAU）数：同一次接触的多写只算 1 个。

    ⚠️ 构建期踩坑：「抓住脚踝」既在主表里、又被宾语规则二次计数，
    set 去重后计数反而错乱（实测「一爪抓住剑修脚踝」计 0 个）。
    正法：主表命中即计 1，不再叠加宾语规则；宾语正则只用于主表未覆盖的裸「抓住」。
    """
    _hits = set(COMBAT_IAU_RE.findall(pic))
    _n = len(_hits)
    # 主表未命中任何带宾语的「抓住」时，才用宾语规则补 1
    if not any(h.startswith("抓住") for h in _hits) and COMBAT_IAU_GRAB_RE.search(pic):
        _n += 1
    return _n


def _combat_tactic_types(pic):
    """该镜行覆盖了几类动作技术（一镜多任务判定用）。"""
    return [k for k, rx in COMBAT_TACTIC_TYPES.items() if rx.search(pic)]


def _iau_limit(dur_s):
    """按镜长给 IAU 上限（§1.2）。3s 定为 2——超 2 个保质率骤降。"""
    if dur_s <= 2:
        return 2
    if dur_s <= 3.5:
        return 2
    if dur_s <= 4.5:
        return 3
    if dur_s <= 6:
        return 3
    return 4



def _combat_on(text, mode="auto"):
    """C21 触发门：打戏稿才跑本组（文戏稿零误报是底线）。"""
    if mode == "on":
        return True
    if mode == "off":
        return False
    return len(COMBAT_SIGNAL_RE.findall(text)) >= COMBAT_SIGNAL_MIN


def _pic_only(line):
    """剥掉「声音：」之后的音效段——音效里的"撞击声/交击声"会把接触判据带偏。"""
    si = line.find("声音：")
    return line[:si] if si >= 0 else line


# C21 专用区间解析：**必须兼容打戏稿的整数秒格式**（`0-3秒` / `3-6秒`）。
# 注：2026-10-14 ◑15 已将 N-N秒（带守卫+紧写判别）并入总控 TIME_RE；C21 保留本解析器以兼容散行打戏草稿。
COMBAT_RANGE_RE = re.compile(
    r"(\d{1,2}):(\d{2})(?:[.:](\d{1,2}))?\s*[-~～→]\s*(\d{1,2}):(\d{2})(?:[.:](\d{1,2}))?"
    r"|(\d+(?:\.\d+)?)\s*s\s*[-~～→]\s*(\d+(?:\.\d+)?)\s*s"
    r"|(\d+(?:\.\d+)?)\s*[-~～→]\s*(\d+(?:\.\d+)?)\s*[秒sS]", re.I)


def _combat_ranges(text):
    """返回 [(start_s, end_s, line_no, 画面段)]，按行聚合（一行 = 一个时间区间）。

    两道过滤（防误判）：
    ① **只认镜行**：行首（剥掉列表符后）必须是数字时码，或行内含 `[镜头N]`——
       说明文字行（如「三轮攻守：0-6 秒…」）会被误聚合成一整段，必须排除；
    ② **重复拷贝去重**：稿件常同时含「分镜稿 + 投喂稿」两份同一时间轴，
       完全相同的 (起, 止, 画面段) 只保留一份，防连续计数被翻倍稀释。
    """
    out, seen = [], set()
    for i, line in enumerate(text.splitlines(), 1):
        probe = re.sub(r"^[\s\-*>•]+", "", line)
        if not (re.match(r"\d", probe) or SHOT_TAG_RE.search(line)):
            continue
        rs = []
        for m in COMBAT_RANGE_RE.finditer(line):
            if m.group(1) is not None:
                s = int(m.group(1)) * 60 + int(m.group(2)) + _frac_to_sec(m.group(3))
                e = int(m.group(4)) * 60 + int(m.group(5)) + _frac_to_sec(m.group(6))
            elif m.group(7) is not None:
                s, e = float(m.group(7)), float(m.group(8))
            else:
                s, e = float(m.group(9)), float(m.group(10))
            rs.append((round(s, 2), round(e, 2)))
        if not rs:
            continue
        seg = _pic_only(line)
        key = (min(x[0] for x in rs), max(x[1] for x in rs), seg.strip())
        if key in seen:
            continue
        seen.add(key)
        out.append((key[0], key[1], i, seg))
    return out


def _union_len(spans):
    """区间并集时长——稿件常同时含「分镜稿 + 投喂稿」两份时间轴（同一段时间被写两遍），
    直接 sum 会把片长算成 2~3 倍。取并集才是真实片长。"""
    if not spans:
        return 0.0
    spans = sorted(spans)
    total, cs, ce = 0.0, spans[0][0], spans[0][1]
    for s, e in spans[1:]:
        if s <= ce:
            ce = max(ce, e)
        else:
            total += ce - cs
            cs, ce = s, e
    return total + (ce - cs)


def parse_time_ranges(text):
    """返回 [(start_s, end_s, line_no)]，兼容 MM:SS(.ff) / Xs-Ys / N-N秒 三形态。

    ⚠️ 三形态与 TIME_RE 的分组一一对应（1-6 / 7-8 / 9-10）——加形态必须同步这里，
    否则落到 `else` 分支做 `float(None)` 直接崩（2026-10-14 补 N-N秒 时同批处理）。
    """
    out = []
    for i, line in enumerate(text.splitlines(), 1):
        for m in TIME_RE.finditer(line):
            if m.group(1) is not None:
                s = int(m.group(1)) * 60 + int(m.group(2)) + _frac_to_sec(m.group(3))
                e = int(m.group(4)) * 60 + int(m.group(5)) + _frac_to_sec(m.group(6))
            elif m.group(7) is not None:
                s, e = float(m.group(7)), float(m.group(8))
            else:
                s, e = float(m.group(9)), float(m.group(10))
            out.append((round(s, 2), round(e, 2), i))
    return out


# ---- C23 画风锁机检（references/style-bible/director-to-prompt-protocol.md §六）----
# 来源：审计工作区原型 c23_check.py（自检三轮 loop 定稿），判据与实现保持一致。
# 触发门 = --c23 on 强制 / off 关闭 / 默认 auto（稿内存在【STYLE/【PERFORMANCE 块或
#          --style-source 登记来源即启用——I 锁未启用的旧稿不追溯，零误报）。

def _c23_on(text, mode="auto", style_source=None):
    """C23 触发门：画风锁已启用（段8/9 存在或来源已登记）才跑本组。"""
    if mode == "on":
        return True
    if mode == "off":
        return False
    return bool(re.search(r"(?m)^【STYLE", text)) or \
        bool(re.search(r"(?m)^【PERFORMANCE", text)) or bool(style_source)


# 区间声明解析（段8/9 的 [lo, hi] 量化区间）
C23_NUM_RANGE  = re.compile(r"\[\s*\d+\s*[:：]\s*(\d+(?:\.\d+)?)\s*,\s*\d+\s*[:：]\s*(\d+(?:\.\d+)?)\s*\]")  # 光比 [1:6, 1:10]
C23_MM_RANGE   = re.compile(r"\[\s*(\d+)\s*mm\s*,\s*(\d+)\s*mm\s*\]")    # 镜头 [21mm, 28mm]
C23_FPS_RANGE  = re.compile(r"\[\s*(\d+)\s*fps\s*,\s*(\d+)\s*fps\s*\]")  # 帧率
C23_K_RANGE    = re.compile(r"\[\s*(\d+)\s*K\s*,\s*(\d+)\s*K\s*\]")      # 色温
C23_PCT_RANGE  = re.compile(r"\[\s*(\d+)%\s*,\s*(\d+)%\s*\]")
C23_ENUM_RANGE = re.compile(r"\[\s*(低|中|高)\s*,\s*(低|中|高)\s*\]")
C23_ENUM_MAP   = {"低": 1, "中": 2, "高": 3}

# ★时码必须兼容小数秒（`0s-2.5s [镜头1]`）——整数秒正则会把 2.5 秒镜行全部漏掉，
#   C23b/c 静默失效、且"对抗测试全拦下"实为空稿假象（自检第 1 轮抓到的坑）。
# ★并兼容三种时码（与 §八口径对齐）：`0s-3s`（含小数秒）/ `0-3秒`（打戏三引擎整数秒）/ `00:00-00:04`（七段式），
#   否则打戏分镜稿在画风锁下解析出 0 镜，C23b/c/f 全线静默失效。
# ★镜号括号放宽（2026-10-11）：半角 `[镜头1]` / 全角 `【镜头1】` / 混写 `【镜头1]` 均可，
#   否则 LLM 输出全角镜号时画风锁的 C23b/c/f 解析出 0 镜 → 三项判据静默失效。
C23_SHOT_LINE  = re.compile(
    r"(?m)^\s*(?:"
    r"(?:\d+(?:\.\d+)?(?:s|秒)?|\d{1,2}:\d{2})\s*[-~～→]\s*(?:\d+(?:\.\d+)?(?:s|秒)?|\d{1,2}:\d{2})\s*[\[【]?\s*(镜头\s*\d+)\s*[\]】]?"
    r"|[\[【]?\s*(镜头\s*\d+)\s*[\]】]?\s*[,，]?\s*(?:\d+(?:\.\d+)?(?:s|秒)?|\d{1,2}:\d{2})\s*[-~～→]\s*(?:\d+(?:\.\d+)?(?:s|秒)?|\d{1,2}:\d{2})"
    r")(.*)$")
C23_SHOT_LIGHT = re.compile(r"光比约?\s*1\s*[:：]\s*(\d+(?:\.\d+)?)")
C23_SHOT_LENS  = re.compile(r"(\d+)\s*mm")
C23_SHOT_FPS   = re.compile(r"(\d+)\s*fps")

