# ★C23e 打斗信号词必须限定在「画面动作层」——否则声音描述（金属劈砍声）与
#   强制禁止项（禁一镜内连续堆叠多个独立动作）会被误判为含打斗
#   （自检第 3 轮抓到的假阳性；按行回看排除语境，固定窗口会漏跨行段）。
C23_COMBAT_SIG = re.compile(r"(打斗|打戏|武打|武侠|格斗|对决|对峙|交手|过招|拆招|斗法|"
                            r"厮杀|混战|交战|挥剑|出剑|劈砍|格挡|刺穿|兵刃相向|剑锋|刀锋|"
                            r"[出直挥]拳|[一记重]脚|[挥甩抽]手|出手|打退|逼退|摔跤|"
                            r"搏斗|攻击动作|卸力|后仰|侧滑|闪避|突进|跃起|腾空|翻滚|"
                            r"一爪|一掌|一记|硬接|借力|借势|卸甲|兵器|刀光|剑光)")
C23_NEG_COMBAT = re.compile(r"(无|不|没有|非|免)\s*(?:任何|本片|该片|本段|该段)?\s*"
                            r"(打斗|打戏|武打|格斗|动作戏|打斗戏|战斗场面)")
C23_EXCLUDE_CTX = re.compile(r"(声音[:：]|音效|强制禁止项|禁止项|严禁|不得|不可|禁[止用]|"
                             r"避免|不要|负面示例|反例)")


def _c23_has_combat(txt):
    """判定稿子是否含打斗：命中行含排除引导（声音/禁止项）则跳过，
    紧邻上一行是排除引导（跨行段）也跳过，否定式（无打斗）不计。"""
    lines = txt.splitlines()
    guide = [bool(re.search(r"(强制禁止项|禁止项|严禁|不得|不可|负面示例|反例|声音[:：]|音效)", ln))
             for ln in lines]
    for i, ln in enumerate(lines):
        if C23_EXCLUDE_CTX.search(ln):
            continue
        if i > 0 and guide[i - 1]:
            continue
        for m in C23_COMBAT_SIG.finditer(ln):
            if C23_NEG_COMBAT.search(ln[max(0, m.start() - 6): m.end() + 2]):
                continue
            return True
    return False


# C23f 单镜超载数据（B1/B2 铁律的机检化 · 10 秒实拍复盘：镜2 丢主角 / 镜3 动作糊成残影）
C23_PERSON_TOKEN = re.compile(r"(主角|对手|反派|男主|女主|角色|人物|两人|三人|二人|众人|群演|"
                              r"侍卫|护卫|弟子|长老|师父|敌人|双方)")
C23_FULL_BODY = re.compile(r"(全身|中全景|全景|站位|铠甲|持剑|举剑|握刀|立姿|背影)")
# ★B1 只在「人物引入镜」生效——打戏互动镜天然双人（剑锋擦肩、气浪、后仰），
#   若只按"同镜≥2人物"判会把所有打戏镜头全误报；实拍病根是「一镜同时建立两个人物」。
C23_INTRO_SEM = re.compile(r"(入画|出场|登场|亮相|建立|交接|对峙|并立|同框.*(站|立)|初次)")
# ★互动语义：写了"谁对谁做了什么"=有意设计的双人镜头，B1 不适用
C23_INTERACT_SEM = re.compile(r"(擦过|掠过|划过|斩向|劈向|刺向|砍向|挥向|推向|撞上|撞击|"
                              r"迎上|扑向|冲向|逼近|后仰|侧身后仰|交手|过招|接触点|"
                              r"反作用力|同时被|一同被|两人|双方|互相|互搏)")
# ★单人声明：显式声明即放行
C23_SOLO_DECL = re.compile(r"(单人入画|单人|不出现第二个人物|仅一人|只有一人|独自)")
# B2 动作意图：位移/换位/环境崩裂也算「一件事」——不只数打击单元（原 C22a 漏过的病）
C23_ACTION_INTENT = re.compile(
    r"(劈砍|斩|刺|砍|挥剑|出剑|格挡|反击|回身|转身|拧身|错步|换位|位移|"
    r"跃起|腾空|落地|翻滚|闪避|突进|后撤|撞击|崩裂|碎裂|崩开|爆开|"
    r"掀起|卷起|扑面|扩散)")
C23_B2_LIMIT = 2   # 单镜动作意图上限（1 个完整动作 + 最多 1 个反馈）


def _c23_decls(block_text):
    """从段8/9 文本抽取所有 [lo, hi] 区间声明 → {label: [(lo, hi), ...]}"""
    decls = {}
    for m in C23_NUM_RANGE.finditer(block_text):
        a, b = float(m.group(1)), float(m.group(2))
        decls.setdefault("光比", []).append((min(a, b), max(a, b)))
    for m in C23_MM_RANGE.finditer(block_text):
        decls.setdefault("镜头", []).append((int(m.group(1)), int(m.group(2))))
    for m in C23_FPS_RANGE.finditer(block_text):
        decls.setdefault("帧率", []).append((int(m.group(1)), int(m.group(2))))
    for m in C23_K_RANGE.finditer(block_text):
        decls.setdefault("色温", []).append((int(m.group(1)), int(m.group(2))))
    for m in C23_PCT_RANGE.finditer(block_text):
        decls.setdefault("百分比", []).append((int(m.group(1)), int(m.group(2))))
    for m in C23_ENUM_RANGE.finditer(block_text):
        lo, hi = m.group(1), m.group(2)
        decls.setdefault("枚举", []).append((C23_ENUM_MAP[lo], C23_ENUM_MAP[hi], lo, hi))
    return decls


def _c23_check(text, style_source=None):
    """C23 全套机检。返回 (issues, warns)：
    issues = C23a/C23b/C23d1/C23d2/C23e/C23f 硬违反；warns = C23c 与疑似 B1。"""
    issues, warns = [], []

    # ---- 段定位与 C23a ----
    # ★行首锚定：段标记必须独占一行（【STYLE｜…）——文档/说明文字里行中出现的
    #   「【STYLE」字面量不算（冒烟测试抓到：示例稿头部说明把段定位带偏）
    _m8 = re.search(r"(?m)^【STYLE", text)
    _m9 = re.search(r"(?m)^【PERFORMANCE", text)
    has_s8 = bool(_m8)
    has_s9 = bool(_m9)
    if not has_s8:
        issues.append("C23a 缺段8【STYLE｜视觉风格 · 全片锁死】——I 画风锁未落地（选卡/默认卡后由系统生成）")
    if not has_s9:
        issues.append("C23a 缺段9【PERFORMANCE｜表演与动作 · 全片锁死】")

    def _block(tag):
        m = re.search(r"(?m)^" + re.escape(tag), text)
        if not m:
            return ""
        i = m.start()
        j = text.find("\n【", i + 1)
        return text[i: j if j > 0 else len(text)]

    style_block = _block("【STYLE")
    perf_block = _block("【PERFORMANCE")

    decls = _c23_decls(style_block + "\n" + perf_block)
    for k in ("光比", "镜头"):
        if has_s8 and k not in decls:
            issues.append(f"C23a 段8 缺少可解析的「{k}」区间声明（如 光比 [1:6, 1:10] / 镜头 [21mm, 28mm]）")
    for bad in ["适度的光比", "较强的反差", "适中的饱和度", "合适的景深"]:
        if bad in style_block:
            issues.append(f"C23a 段8 出现不可解析的模糊表述「{bad}」——槽位必须写量化区间")

    # ---- C23d1 三方名（★只扫交付正文：剔除 Markdown 标题/引用/表格等元数据区）----
    # 病根（2026-10-11）：此前 `if name in text` 裸扫全文，官方示例的「# 成稿示例 · 王家卫 15 秒」
    # 标题与「> 风格来源：F 锁 · 徐克」引用块被判成交付层 → 两个官方示例双双假 FAIL C23d1。
    _d1_text = _strip_md_meta(text)
    for name in C23_NAMES:
        if name in _d1_text:
            issues.append(f"C23d1 交付层出现三方名「{name}」——选项层名字不进交付层，只写参数组")
    for m in C23_STUDIO_HINT.finditer(_d1_text):
        issues.append(f"C23d1 疑似工作室名：…{_d1_text[max(0, m.start() - 8): m.end() + 4].strip()}…")

    # ---- 镜块切分（兼容小数秒时码）----
    shot_blocks, cur = [], None
    for ln in text.splitlines():
        m = C23_SHOT_LINE.match(ln)
        if m:
            if cur:
                shot_blocks.append(cur)
            _sid = m.group(1) or m.group(2) or "镜头"
            cur = {"id": _sid, "text": m.group(3)}
        elif cur is not None and ln.strip() and not ln.startswith("【"):
            cur["text"] += " " + ln.strip()
    if cur:
        shot_blocks.append(cur)

    # ---- C23b 区间越界 + C23c 特效超支 ----
    for sb in shot_blocks:
        t = sb["text"]
        for m in C23_SHOT_LIGHT.finditer(t):
            val = float(m.group(1))
            for (lo, hi) in decls.get("光比", []):
                if not (lo <= val <= hi):
                    issues.append(f"C23b {sb['id']} 光比 1:{val:g} 越界，段8 区间为 [1:{lo:g}, 1:{hi:g}]"
                                  "——镜头取值必须落在段8 笼子内")
        for m in C23_SHOT_LENS.finditer(t):
            val = int(m.group(1))
            for (lo, hi) in decls.get("镜头", []):
                if not (lo <= val <= hi):
                    issues.append(f"C23b {sb['id']} 镜头 {val}mm 越界，段8 区间为 [{lo}mm, {hi}mm]")
        for m in C23_SHOT_FPS.finditer(t):
            val = int(m.group(1))
            for (lo, hi) in decls.get("帧率", []):
                if not (lo <= val <= hi):
                    issues.append(f"C23b {sb['id']} 帧率 {val}fps 越界，段9 区间为 [{lo}fps, {hi}fps]")
        hit = sorted({w for w in C23_VFX_WORDS if w in t})
        if len(hit) > 3:
            warns.append(f"C23c {sb['id']} 并列视觉特效类 {len(hit)} 项 > 3：{'/'.join(hit)}"
                         "——渲染负载超支，砍到 3 类以内")

    # ---- C23d② 转译丢失 ----
    if style_source:
        dims = ["成像底层", "形体骨相", "影调区间", "色彩区间", "空气介质",
                "光学区间", "材质响应", "特效语言", "禁项"]
        hit_dims = [d for d in dims if d in style_block]
        has_range = bool(_c23_decls(style_block).get("光比") or _c23_decls(style_block).get("镜头"))
        n = len({w for w in C23_PARAM_HINTS if w in style_block})
        if len(hit_dims) < 4 or not has_range or n < 5:
            issues.append(f"C23d2 转译丢失：STYLE_BIBLE 记了来源「{style_source}」，但段8 未落到成组参数组"
                          f"（参数维度 {len(hit_dims)}/9 · 含数值区间={has_range} · 特征词 {n}）"
                          "——只写「电影感画风」不算转译，须按 director-param-library.md 落 11 槽位")

    # ---- C23e 题材越界 ----
    if style_source and style_source in C23_STYLE_ABILITY:
        fight, fx = C23_STYLE_ABILITY[style_source]
        if _c23_has_combat(text) and fight <= 0:
            issues.append(f"C23e 题材越界：稿含打斗信号，但来源风格「{style_source}」打斗承载 ★{fight}"
                          "——硬写拍不出来，应换 T1/T7/T8 系风格（style-fit-and-combat-matrix.md）")
        if re.search(r"(特效强度\s*[=:：]?\s*高|高密度特效|粒子密度高|满屏特效)", text) and fx <= 1:
            issues.append(f"C23e 题材越界：稿声明高强度特效，但来源风格「{style_source}」特效承载 ★{fx}"
                          "——其参数组明确禁该类表现")

    # ---- C23f 单镜超载（B1/B2）----
    for sb in shot_blocks:
        t = sb["text"]
        persons = len(C23_PERSON_TOKEN.findall(t))
        full = bool(C23_FULL_BODY.search(t))
        solo = bool(C23_SOLO_DECL.search(t))
        interact = bool(C23_INTERACT_SEM.search(t))
        if persons >= 2 and full and not solo and not interact and C23_INTRO_SEM.search(t):
            issues.append(f"C23f {sb['id']} B1 违反：同一镜内建立 {persons} 个人物"
                          "（入画/交接语义 + 全身或兵器描述）——一镜一个全身人物，交接动作拆两镜"
                          "（实拍病根：模型丢角色，只渲染信息量大的那个）")
        elif persons >= 2 and full and not solo and not interact:
            warns.append(f"C23f {sb['id']} 疑似 B1：同镜 {persons} 个人物 + 全身/兵器描述，"
                         "但未写互动关系或单人声明（信息量超载，请显式处理）")
        acts = sorted({m.group(0) for m in C23_ACTION_INTENT.finditer(t)})
        if len(acts) > C23_B2_LIMIT:
            issues.append(f"C23f {sb['id']} B2 违反：单镜动作意图 {len(acts)} 项 > {C23_B2_LIMIT}："
                          f"{'/'.join(acts)}——一镜一击（位移/换位/崩裂一并计入），其余下沉到相邻镜")

    return issues, warns


def _split_segments(text):
    """按【画幅风格】行把稿件切分为「段」（七段式一段一组）。

    返回 [(段名, 段首行的全文行号, 段文本), ...]；稿内无【画幅风格】行则整篇视为一段。
    为什么要切：真实投喂稿是「提示词组 × N 组」（3 分钟剧 ≈14 段），旧版 C17 系列只取全文
    第一个【站位声明】——段1 若是单人段，段2 之后的"B 就不见了"全部漏检（2026-10-10 修正）。
    """
    lines = text.splitlines()
    idxs = [i for i, l in enumerate(lines) if l.strip().startswith("【画幅风格】")]
    if not idxs:
        return [("全文", 1, text)]
    segs = []
    for k, start in enumerate(idxs):
        end = idxs[k + 1] if k + 1 < len(idxs) else len(lines)
        segs.append((f"段{k + 1}", start + 1, "\n".join(lines[start:end])))
    return segs


def _feed_body(text):
    """取「投喂正文」——交付文档常是「说明性散文（项目锁定/分镜总览/自检点检表）+ ``` 围栏内的
    投喂块」混排；含围栏时只取围栏内容，否则整篇视为正文。
    防 C12/C12b 这类「正文纪律」检查被文档自身的说明文字误伤
    （实测：示范稿表头「段缝两侧强制换机位」、「无 palette 默认化」被当成投喂正文违规）。"""
    blocks = re.findall(r"```[^\n]*\n([\s\S]*?)```", text)
    if not blocks:
        return text, False
    return "\n".join(blocks), True


def _cam_families(s):
    """返回文本中出现的运镜族集合（长词优先，避免「滑动变焦」被同时算成「变焦」）。"""
    fams, masked = set(), s
    for w in sorted(CAM_FAMILIES, key=len, reverse=True):
        if w in masked:
            fams.add(CAM_FAMILIES[w])
            masked = masked.replace(w, "\u3000" * len(w))
    return fams


def _shot_head(line):
    """取镜行头「[镜头N] 景别 · 视角 · 运镜。」——运镜只认头部，避免把画面段里的
    动作动词（推开/拉开门/固定身体）误判成运镜。

    ★镜号识别放宽（2026-10-11）：半角 `[镜头1]` / 全角 `【镜头1】` / 无括号 `镜头1` 均可。
    ★打戏镜号前置兼容（2026-10-14）：`[镜头1] 0-3秒，中景·平视·跟拍，@剑修 冲向…` 剥除紧随镜号的时码，
      若以逗号分隔镜行头与动作主体（`@` 或动作句），则在进入动作主体前截断，防动作动词被误判为运镜。
    """
    m = SHOT_TAG_RE.search(line)
    if not m:
        return ""
    rest = line[m.end():].lstrip(" 	,，")
    # 若镜号在时码前（如 `[镜头1] 0-3秒，中景·平视…`），先剥掉前导时码
    tm = TIME_RE.match(rest)
    if tm:
        rest = rest[tm.end():].lstrip(" 	,，")
    # ★P11 修（2026-10-24 · 冒号形态镜行的头部污染）：
    #   V7 现行镜行用「：」分隔头部与正文 —— `[镜头1] 中景 · 35mm · 平视 · 固定：画面主体：@苏念 目光跟随对方`。
    #   旧版只按句号 `。` 切头，正文第一分句被整段吞进头部，于是正文里的
    #   「跟随 / 静止 / 定住 / 推近」被 `_cam_families()` 当成第二种运镜 →
    #   C18h「一镜多运镜」误报（实测：fams 从 {'固定'} 变成 {'固定','跟'}）。
    #   冒号截断必须**先于**句号截断，且只在冒号不在行首时生效。
    _colon = re.search(r"[：:]", rest)
    if _colon and _colon.start() > 0:
        rest = rest[:_colon.start()]
    head = rest.split("。", 1)[0]
    # 若逗号分隔且未用句号结头（如 `中景·平视，@剑修 冲向…`），只取含景别/视角/运镜的前导分句
    if "，" in head or "," in head:
        parts = re.split(r"[，,]", head)
        if "·" in parts[0]:
            head = parts[0]
        else:
            kept = [parts[0]]
            for pt in parts[1:]:
                if "@" in pt or len(pt.strip()) > 6 or not (COMBAT_SIZE_RE.search(pt) or COMBAT_ANGLE_RE.search(pt) or _cam_families(pt)):
                    break
                kept.append(pt)
            head = "，".join(kept)
    return head


def validate(text, model="2.5", mode="new", combat="auto", c23="auto",
             style_source=None, aspect=None, plugin="auto", state_data=None):
    issues, warns = [], []
    # ---- Markdown 元数据剥离（2026-10-12 修复 · 根治「官方示范稿过不了自家机检」）----
    # 病根：2026-10-11 已发现「# 标题 / > 引用 / | 表格」等说明性文字被当成投喂正文扫描，
    #   导致官方示例 两份历史示例稿 双双假 FAIL——但当时只给
    #   「交付层零人名」单条判据打了 _strip_md_meta 补丁，**未推广到其余全文扫描型判据**。
    #   2026-10-12 同根因复发：历史示例稿 的小标题
    #   「（单参考图绑定 · 无首尾帧）」触发 C8 假 FAIL（首尾帧禁词出现在说明文字里）。
    #   修法：入口统一剥离，一次根治所有全文扫描型判据（C6/C8/C12/C17/C19/C26…）。
    #   保留：C4 篇级字数按**原始整份文件** len() 计（该判据口径即"文件级兜底"）。
    _raw_len = len(text)
    _raw_text_for_c30 = text
    text = _strip_md_meta(text)
    # ---- C1/C2/C3 时间轴（逐段 · 2026-10-10 修正「单段假设」）----
    # 病根：旧实现按整份文件算一条时间轴——「投喂提示词组 × N 组」的交付稿（每段各从 00:00
    # 起手、各 ≤15s）会被判成「C3 重叠(15.0 vs 0.0)」＋「C2 镜头数 16 > 段长÷3s 上限 5」，
    # 一份完全合规的 N 段稿必然 FAIL。段才是投喂单元，时间轴必须逐段判。
    _segments_time = _split_segments(text)
    tr = []
    _no_axis = True
    # 对话段行号范围（全文级共享 · 2026-10-13 用户裁定的「对话段全面豁免」）：
    #   正反打的标准形态 = 固定机位 + 切镜换嘴（粉丝稿实测全程固定、靠切）。
    #   故 C2 镜头数/单镜下限、C13 镜长雷同、C18j/k 固定镜与运镜覆盖，
    #   在对话段内**全部豁免**（用户裁定原文：「对话段全面豁免」）。
    _dlg_line_ranges = []
    for _sn, _sb, _st in _segments_time:
        _st_lines_p = _st.splitlines()
        _trp = parse_time_ranges(_st)
        if not _trp:
            continue
        _head_p = "\n".join(_st_lines_p[max(0, _ln - 1)] for _s, _e, _ln in _trp[:12])
        _d_p = (any(w in _head_p for w in ("对话", "对白", "文戏", "谈判", "争执", "争吵", "商议", "聊"))
                and not any(w in _head_p for w in ("空镜", "打斗", "战斗", "武戏", "转场", "蒙太奇",
                                                    "独白", "宣判", "静场", "留白", "氛围段", "长镜段", "情绪积累")))
        if not _d_p:
            _cnt_p = sum(1 for _s, _e, _ln in _trp
                         if 0 <= _ln - 1 < len(_st_lines_p)
                         and "台词：" in _st_lines_p[_ln - 1]
                         and "无" not in _st_lines_p[_ln - 1].split("台词：")[1][:3])
            _d_p = _cnt_p >= 2
        if _d_p:
            _dlg_line_ranges.append((_sb, _sb + len(_st_lines_p)))

    def _in_dlg(ln):
        return any(a <= ln < b for a, b in _dlg_line_ranges)

    for _sn, _sb, _st in _segments_time:
        _tr_seg = parse_time_ranges(_st)
        for _s, _e, _ln in _tr_seg:
            tr.append((_s, _e, _sb + _ln - 1))
        if not _tr_seg:
            continue
        _no_axis = False
        _d = round(max((e for _s, e, _l in _tr_seg), default=0), 2)
        if _d > LIMITS[model] + 0.01:
            issues.append(f"C1 [{_sn}] 段时长 {_d}s 超 {model} 上限 {LIMITS[model]}s")
        # C1b 分段粒度（2.5 专属）：默认 25~30s 吃满上限，禁碎段
        if model == "2.5":
            # ★P6.3 豁免：衔接段/过渡段/过场段/空镜段——用户明确的「段间过渡」产物，
            #   本来就是几秒的短段（4~8s），拿「25~30s 吃满上限」去卡它等于禁止做过渡。
            #   识别位：段标题与段缝说明区（段首 240 字）。
            _is_link_seg = bool(re.search(r"衔接段|过渡段|过场段|空镜段", _st))
            if _d < 12 and not _is_link_seg:
                warns.append(f"C1b [{_sn}] 段时长 {_d}s < 12s 下限（2.5 建议 25~30s 吃满上限，过短会显著增加段数与段缝；若这是刻意的段间过渡段，请在段标题或段缝说明里写明「衔接段/过渡段」即豁免）")
            elif 15 < _d < 25 and not _is_link_seg:
                warns.append(f"C1b [{_sn}] 段时长 {_d}s 落在碎段区（2.5 默认 25~30s；16~24s 既吃不到长镜头红利又比 15s 更碎，除非打戏快节奏/单段信息量小，否则合并到 ≥25s）")
        _n = len(_tr_seg)
        # C2 镜头数上限 —— 对话段例外（2026-10-13 用户实测反馈）：
        #   旧上限「段长÷3s」是为「长镜头/漫剧美学」设的，**会把正反打彻底锁死**——
        #   15s 段最多 5 镜，而回合制正反打至少需 6~8 镜（粉丝稿 30s/8 镜 = 3.75s 平均，
        #   真·正反打实测 2s 一切）。这正是用户批的「非常呆傻地去执行台词量控制」。
        #   对话段（含「对话/对白/文戏/谈判/争执/争吵/商议/聊」或无此类词但有 ≥2 条台词）
        #   → 上限放宽到 段长÷2s；单镜 ≥2s（C2 下限同步放宽到 2s）。空镜/打斗段不变。
        _st_lines = _st.splitlines()
        _is_dlg = _in_dlg(_sb)
        _is_cmb_seg = _combat_on(_st, combat)
        _div = 2 if (_is_dlg or _is_cmb_seg) else 3
        _cap = -(-int(_d + 0.5) // _div) or 1
        if _n > _cap:
            issues.append(f"C2 [{_sn}] 镜头数 {_n} > 段长÷{_div}s 上限 {_cap}"
                          + ("（对话段按 ÷2s 放宽以支持正反打 / 打戏段按 ÷2s 支持 2~3s 黄金颗粒度细切）" if (_is_dlg or _is_cmb_seg) else ""))
        for _s, _e, _l in _tr_seg:
            _g = _sb + _l - 1
            if _e <= _s:
                issues.append(f"C3 第{_g}行 时间码倒挂 {_s}->{_e}")
            elif _e - _s < (2 if (_is_dlg or _is_cmb_seg) else 3):
                warns.append(f"C2 第{_g}行 单镜 {round(_e - _s, 2)}s <{2 if (_is_dlg or _is_cmb_seg) else 3}s（碎切风险）")
            elif _e - _s > 6:
                warns.append(f"C10 第{_g}行 单镜 {round(_e - _s, 2)}s >6s（talking head 风险：单镜预算 3~5s，长台词按 dialogue-doctor 拆 2~3 镜正反打/反应镜头）")
        for (_s1, _e1, _l1), (_s2, _e2, _l2) in zip(_tr_seg, _tr_seg[1:]):
            if abs(_e1 - _s2) > 0.05:
                _kind = "重叠" if _s2 < _e1 else "断档"
                warns.append(f"C3 第{_sb + _l1 - 1}->{_sb + _l2 - 1}行 {_kind}({_e1} vs {_s2})")
        if mode == "new" and _tr_seg[0][0] > 0.05:
            issues.append(
                f"C3 [{_sn}] 段首时码必须为 00:00（本段从 {_tr_seg[0][0]:.1f}s 起手）——"
                "2.5 每段是一次独立生成，累计时码会让平台按整条时间轴理解、C1 也会把段长算成累计值"
                "（误报「段超 30s」，真病因是时码未归零）。改法：每段一律从 00:00 起，段号靠标题区分。")
    if _no_axis:
        warns.append("C1-C3 未识别到时间轴（如为纯文生视频短片可忽略）")
    dur = round(max((e for _s, e, _ in tr), default=0), 2)
    # 投喂正文（含 ``` 围栏时只取围栏内，排除交付文档的说明性散文）
    _feed, _has_fence = _feed_body(text)

    # C4 字符预算（篇级兜底 · 多段文件按段判——一个段 = 一个投喂单元）
    if len(_segments_time) > 1:
        for _sn, _sb, _st in _segments_time:
            if len(_st) > MAX_CHARS:
                issues.append(f"C4 [{_sn}] {len(_st)} 字符 > 预算 {MAX_CHARS}（多段文件按段判；"
                              f"段级红线 2.0 ≤3000 字 / 2.5 ≤4000 字见 gate_check.py 闸门3。按 seedance-render-engine 压缩顺序裁删）")
    elif len(text) > MAX_CHARS:
        issues.append(f"C4 共 {_raw_len} 字符 > 预算 {MAX_CHARS}（篇级兜底·按整份文件 len() 计；段级字数见 gate_check.py 闸门3。按 seedance-render-engine 压缩顺序裁删）")

    # C5 版本语法
    if model == "2.0":
        if "[SFX" in text.upper():
            issues.append("C5 Seedance 2.0 无官方声音字符标记（音效/台词以文字写入镜行、默认由模型生成）")
        for w in ("顿挫", "微停顿", "咬住"):
            if w in text:
                issues.append(f"C5 2.0 禁顿挫词「{w}」（会渲染成真停顿）")
    elif "[SFX" not in text.upper() and "【音效】" not in text:
        # ★审计补丁P1 修：标准七段式稿件用独立【音效】栏承载音效（平台并不要求写成 [SFX:] 行内标记），
        #   旧版见不到 [SFX 就报，属假告警；两栏任一在位即通过。
        warns.append("C5 2.5 建议用 [SFX:] 原生音效标记，或用独立【音效】栏承载")

    # C6 画幅回填
    # ★段名独立成行兼容（2026-10-12 修复）：原正则要求画幅值与【画幅风格】同在一行，
    #   但 历史示例稿 用「段名独立成行、内容下一行」写法
    #   （`【画幅风格】\n16:9 横屏, …`）——该稿自称"可直接整组复制投喂"，用户照抄即 C6 FAIL。
    #   `[^【\n]` 保证不跨到下一个段名（不会把【场景资产】里的画幅词误算作本段回填）。
    if not re.search(r"aspect_ratio\s*=", text) and not re.search(
            r"【画幅风格】\s*(?:\n\s*)?[^【\n]{0,100}?(16:9|9:16|21:9|1:1)", text):
        issues.append("C6 缺画幅回填（体内 aspect_ratio= 或【画幅风格】段内写 16:9/9:16/21:9）")

    # C6b 画幅一致性（aspect-ratio-adaptation.md §三 强约束清单 · 2026-10-10 新增）
    # 病根：C6 只查"有没有写 aspect_ratio"，不查"写的是不是同一个"——实测稿子一边写
    # 「16:9 横屏」一边写 aspect_ratio=9:16 + 竖屏构图词，PASSED 零告警。锁定值必须全流程一致。
    _RATIO_KEYS = ("2.35:1", "2.39:1", "21:9", "16:9", "9:16", "4:3", "1:1")
    _ar_field = [re.sub(r"\s", "", a).replace("：", ":") for a in
                 re.findall(r"aspect_ratio\s*[:=]\s*([0-9]+\s*[:：]\s*[0-9]+)", text)]
    _ar_read = []
    for _m in re.finditer(r"(?:【画幅风格】|【画幅】)[^\n]{0,80}", text):
        for _k in _RATIO_KEYS:
            if _k in _m.group(0):
                _ar_read.append(_k)
                break
    _ar_uniq = sorted(set(_ar_field))
    if len(_ar_uniq) > 1:
        issues.append(f"C6b 画幅字段自相矛盾：稿内 aspect_ratio= 出现多种取值 {_ar_uniq}——"
                      "画幅一经锁定，全流程（每条提示词/每个时间轴/每个 API 载荷）回填同一值，"
                      "禁止混用（aspect-ratio-adaptation.md §〇·4）")
    elif _ar_uniq and _ar_read:
        _read_uniq = sorted(set(_ar_read))
        if _ar_uniq[0] not in _read_uniq:
            issues.append(f"C6b 画幅不一致：【画幅风格】写明「{'/'.join(_read_uniq)}」，"
                          f"但 aspect_ratio={_ar_uniq[0]}——文字比例与 API 参数不符，"
                          "模型按参数出图、观感按文字预期，必错位（§三 强约束清单）")
    if aspect:
        _ar_lock = _ar_uniq[0] if _ar_uniq else (_ar_read[0] if _ar_read else "")
        if _ar_lock and aspect.replace("：", ":") != _ar_lock:
            issues.append(f"C6b 画幅与任务锁不符：--aspect {aspect}，稿内锁定值 {_ar_lock}——"
                          "画幅锁定后不得被模板/示例带偏（aspect-ratio-adaptation.md §〇·2）")
    _ar_lock2 = _ar_uniq[0] if _ar_uniq else (_ar_read[0] if _ar_read else "")
    if _ar_lock2 in ("16:9", "21:9"):
        _port = [w for w in ("垂直安全区", "竖向安全区", "上下叠压", "上下对峙", "纵向落差")
                 if w in text]
        if _port:
            warns.append(f"C6b 画幅口径越界：锁定 {_ar_lock2} 横屏，正文却出现竖屏构图词 {_port}——"
                         "横屏禁「垂直安全区/上下叠压」写法，构图按横屏套版"
                         "（aspect-ratio-adaptation.md §一 / §三·1）")
    elif _ar_lock2 == "9:16":
        _land = [w for w in ("三分线左右站位", "左右对峙", "横向位移", "左右推进", "水平展开")
                 if w in text]
        if _land:
            warns.append(f"C6b 画幅口径越界：锁定 9:16 竖屏，正文却出现横屏构图词 {_land}——"
                         "竖屏禁横向展开写法，构图按竖屏套版（aspect-ratio-adaptation.md §一）")

    # C7 七段式核心栏（段7【强制禁止项】可由前置变体【强制禁止项｜前置】等价满足；多段稿逐段核查）
    _has_global_ban = bool(BAN_FRONT_TAG.search(text))
    missing = [seg for seg in SEVEN_SEGMENTS
               if seg not in text and not (seg == "【强制禁止项】" and _has_global_ban)]
    if missing:
        issues.append(f"C7 七段式缺栏 {missing}（V7.3.0 主格式唯一命名 · 域命名沿革，段序见 model-adapters §5；"
                      f"段7 亦可用前置【强制禁止项｜前置】等价满足——禁项单点，二选一）")
    elif len(_segments_time) > 1:
        for _sn7, _sb7, _st7 in _segments_time:
            _m7 = [seg for seg in SEVEN_SEGMENTS
                   if seg not in _st7 and not (seg == "【强制禁止项】" and (_has_global_ban or BAN_FRONT_TAG.search(_st7)))]
            if _m7:
                issues.append(f"C7 [{_sn7}] 七段式缺栏 {_m7}（多段稿每段均须具备完整七段式核心栏，段7 可由全文前置【强制禁止项｜前置】等价满足）")

    # C24 禁项单点纪律（逐段 · 2026-10-10 修正多段误报）
    #   口径：**每个投喂单元（段）只允许一处禁项块**。旧实现按全稿计数 → 多段同文件
    #   （每段各有一个段7【强制禁止项】）必然误报「禁项重复 N 处」，一份合规的 N 段稿必然 FAIL。
    #   a 段内 ≥2 处（段7 + 前置 / 段7 + 「补充」变体）→ FAIL（双写=模型读到两份规则，后一份近似噪声）
    #   b 全稿 0 处 → FAIL（连前置变体也没有；与 C7 缺栏互补——C7 管结构命名，C24 管禁项存在性）
    #   c 前置块（稿件最前的【强制禁止项｜前置】）与任一 段7 并存 → FAIL（调在前面，后面就不要）
    def _ban_count(blob):
        return (blob.count("【强制禁止项】") + len(BAN_FRONT_TAG.findall(blob))
                + len([m for m in BAN_BLOCK_ANY.finditer(blob) if m.group("odd") is not None]))
    ban_std = text.count("【强制禁止项】")
    ban_front = len(BAN_FRONT_TAG.findall(text))
    ban_odd = len([m for m in BAN_BLOCK_ANY.finditer(text) if m.group("odd") is not None])
    ban_total = ban_std + ban_front + ban_odd
    _pre_blob = text.split("【画幅风格】", 1)[0] if "【画幅风格】" in text else ""
    _pre_n = _ban_count(_pre_blob)
    _seg_ban = [(n, _ban_count(t)) for n, _b, t in _segments_time]
    _dups = [f"{n}×{c}" for n, c in _seg_ban if c > 1]
    if ban_total == 0:
        issues.append("C24b 缺禁项块——段7【强制禁止项】或前置【强制禁止项｜前置】必须二选一（禁项单点纪律）")
    elif _dups:
        issues.append(f"C24a 禁项重复（段内 {', '.join(_dups)}）——每个投喂单元（段）只保留一处禁项块："
                      "段7【强制禁止项】或前置【强制禁止项｜前置】二选一；双写=模型读到两份规则，"
                      "后一份近似噪声（V7.3.6 · 规则命名沿革）")
    elif _pre_n >= 1 and any(c >= 1 for _n, c in _seg_ban):
        issues.append(f"C24a 禁项重复（前置禁项块 ×{_pre_n} 与段7 并存）——禁项单点纪律："
                      "调在前面，后面就不要（V7.3.6 · 规则命名沿革）")
    elif _pre_n > 1:
        issues.append(f"C24a 禁项重复（前置禁项块出现 {_pre_n} 份）——全稿只保留一处（V7.3.6 · 规则命名沿革）")

    # ★P6.2 新增 C24c：镜行内嵌禁项（禁项已在段7 写过，镜行里不该再重复一遍）。
    #   用户实测反馈（2026-10-23）：「你在后面放了禁止项了，前面的那里面就不要放了」。
    #   病根：段7 已有禁项，镜行里又写「（禁转移给他人）」「（禁横穿教室）」——同一禁令出现两次，
    #   模型会把镜行里的那一句当**画面描述**读（画一个"禁止"的状态），既占字数又抢正面描述的权重。
    #   规则权威：model-adapters.md「禁项单点纪律：调在前面，后面就不要」。
    _c24c = []
    for ln_i, line in enumerate(text.splitlines(), 1):
        if not TIME_RE.search(line) or "【强制禁止项" in line:
            continue
        _snd = line.find("声音：")
        _pic = line[:_snd] if _snd >= 0 else line
        _hits = re.findall(r"禁[^\s，。；、）]{1,12}", _pic)
        if _hits:
            _c24c.append(f"第{ln_i}行（{'、'.join(_hits[:2])}）")
    if _c24c:
        warns.append(
            "C24c 镜行内嵌禁项：" + "；".join(_c24c[:6]) +
            "——段7【强制禁止项】已写过禁令，镜行里不要再重复。镜行只写**正面的画面结果**"
            "（「已坐直、双手收回桌上」而不是「（禁转移给他人）」）：重复的禁项会被模型当成画面内容读，"
            "既抢正面描述的权重又白占字数。要禁的写进段7 一次，镜行只留怎么做")

    # ★P6.2 新增 C24d：禁项条目超限（权威口径「极简四项 · 禁再加长清单」）。
    #   病根：禁项长期只加不删，实测积累到 16~22 条（379 字）——长清单里每一条都在稀释真正的致命伤，
    #   模型读到的是一锅平均权重。口径：四项基础（字幕/水印/背景音乐/旁白）+ 最多 2 条该段特有致命伤。
    _c24d = []
    for ln_i, line in enumerate(text.splitlines(), 1):
        if not line.lstrip().startswith("【强制禁止项】"):
            continue
        _items = [x for x in re.split(r"[；;]", line) if "禁" in x]
        _cnt = len(re.findall(r"禁[^、；。]{0,14}", line))
        if _cnt > 6:
            _c24d.append(f"第{ln_i}行（约 {_cnt} 条）")
    if _c24d:
        warns.append(
            "C24d 禁项条目超限：" + "；".join(_c24d) +
            "——权威口径是**极简四项**（画面：禁字幕、禁水印（含 Logo）；音频：禁背景音乐、禁旁白），"
            "最多再加 2 条该段特有致命伤，共 ≤6 条（model-adapters.md「禁项极简 · 禁再加长清单」）。"
            "长清单的害处：每条都在稀释真正的致命伤，模型读到一锅平均权重；"
            "能靠正面描述写死的（服装状态/姿态/位移）一律正面写死，不要塞进禁项")

    # ---- C25 表演层（acting-direction.md · 2026-10-09 新增）----
    #   a 画面段抽象神态词 → WARN（神态须是看得见的肌肉动作）
    #   b 群演同步反应词   → WARN（反应成「波」不成「排」）
    for ln_i, line in enumerate(text.splitlines(), 1):
        if not TIME_RE.search(line):
            continue
        _snd = line.find("声音：")
        _dlg = line.find("台词：")
        _cuts = [x for x in (_snd, _dlg) if x >= 0]
        _pic = line[:min(_cuts)] if _cuts else line
        _face = [w for w in C25_BLAND_FACE if w in _pic]
        if _face:
            warns.append(f"C25a 第{ln_i}行 画面段出现抽象神态词 {sorted(set(_face))}——"
                         "神态须落到看得见的肌肉动作（acting-direction.md §七 + FACS 层），禁结果词")
        _sync = [w for w in C25_SYNC_CROWD if w in _pic]
        if _sync:
            warns.append(f"C25b 第{ln_i}行 群演反应同步词 {sorted(set(_sync))}——"
                         "群体反应须成「波」不成「排」，错开先后与强度（acting-direction.md §十一）")
        # ---- C25c AIGC 假表演词（shot-economy-and-acting.md §六·补 假表演规避清单）----
        _fake = [w for w in C25_FAKE_ACTING if w in _pic]
        if _fake:
            warns.append(f"C25c 第{ln_i}行 AIGC 假表演词 {sorted(set(_fake))}——"
                         "出现即视为该镜行需重写；改为具体可见的肌肉动作与呼吸，"
                         "不靠负面词压制（shot-economy-and-acting.md §六·补）")
        # ---- C25d 特写过载法则（ACTING SKILL.md §12 #14 Close-up overload：镜头越紧，动得越少）----
        if CU_SHOT_RE.search(_shot_head(_pic) or _pic[:24]):
            _cu_ov = re.findall(r"挥臂|跨步|奔跑|狂奔|跳跃|转身离开|咆哮大吼|五官扭曲|疯狂大笑|手舞足蹈|大幅挥手", _pic)
            if _cu_ov:
                warns.append(
                    f"C25d 第{ln_i}行 特写动作过载（Close-up overload）：特写/大特写镜内写了大幅动作或夸张表情「{'、'.join(sorted(set(_cu_ov)))}」——"
                    "违反《ACTING SYSTEM》铁律14「The tighter the shot, the less movement（镜头越紧，动得越少）」！特写内大幅肢体或五官用力会导致AI人脸五官瞬间崩塌变形，特写只准写眼神微移、呼吸与细微肌肉收紧（acting-direction.md §十二·14）"
                )
        # ---- C25e 单镜连续三步掏取过程链穿模拦截（ACTING SKILL.md §10 States, not transitions：拍状态不拍过程）----
        if re.search(r"(?:伸手进|探手进|手伸入|从怀里摸)[^。；]{0,14}(?:摸索|掏出|取出|拿出)[^。；]{0,14}(?:展开|打开|翻开|递出)", _pic):
            warns.append(
                f"C25e 第{ln_i}行 单镜长过程链穿模高危（States, not transitions）：同一镜内连写「伸手进怀/包→摸索掏出→展开/打开」三步连续转换过程——"
                "违反《ACTING SYSTEM》铁律10「视频模型拍不好过渡过程，拍得好当下状态」！单镜内既掏又展必引发手部多指与道具凭空穿模，请改为状态直写（如「右手已捏着半展的信笺」）或拆分为两镜（acting-direction.md §十）"
            )
        # ---- C18f 景别与表演幅度绑定（short-drama-camera-system.md §一）----
        # 景别只能写它装得下的东西：特写不装胸部以下；近景不装全身/完整站位。
        if CU_SHOT_RE.search(_pic):
            _low = LOWER_BODY_RE.search(_pic)
            # 发力链豁免：命中词紧前 4 字是发力动词 → 这是动作链，不是构图越界
            if _low and LOWER_BODY_ACTION.search(_pic[max(0, _low.start() - 4):_low.start()]):
                _low = None
            if _low:
                warns.append(f"C18f 第{ln_i}行 特写承载胸部以下身体「{_low.group(0)}」——"
                             "特写只能写眼皮/眨眼/眼焦/唇线/喉咙/下颌/鼻息；胸部以下、完整腿脚、"
                             "复杂空间关系超出景别容纳范围，模型会直接生成错误画面"
                             "（short-drama-camera-system.md §一 景别与表演幅度绑定）")
        elif re.search(r"近景", _pic):
            _fb = FULL_BODY_RE.search(_pic)
            if _fb:
                warns.append(f"C18f 第{ln_i}行 近景/中近景承载「{_fb.group(0)}」——"
                             "近景不装完整站位与全身；需展示手脚或多人完整站位时改中景/全景或拆镜"
                             "（short-drama-camera-system.md §一 景别与表演幅度绑定）")
        # ---- C20e 过肩镜头几何·左右前景判定（short-drama-camera-system.md §三）----
        # 左右前景写反 → 模型把肩膀挡在错的位置、前后景人物颠倒。
        _ots = OTS_RE.search(_pic)
        if _ots:
            _kind, _side = _ots.group(1), _ots.group(2)
            _expect = OTS_SIDE_MAP[(_kind, _side)]
            _fg = OTS_FG_RE.search(_pic)
            if not _fg:
                warns.append(f"C20e 第{ln_i}行 过肩未写左右前景——过肩必须同时写清摄影机在被越角色"
                             "背后还是前侧、越过哪一侧肩，并落到画面左右前景"
                             "（short-drama-camera-system.md §三 过肩镜头几何）")
            elif _fg.group(1) != _expect:
                warns.append(f"C20e 第{ln_i}行 过肩左右前景写反：「{_kind}过{_side}肩」应落画面"
                             f"{_expect}前景，稿内写「画面{_fg.group(1)}前景」——左右前景写反会让"
                             "模型把肩膀挡在错的位置、前后景人物颠倒（short-drama-camera-system.md §三）")

    # C8 2.0 首尾帧禁用
    fl = re.findall(r"首帧\s*[:：]|尾帧\s*[:：]|参考图绑定|Start\s*Frame|End\s*Frame", text, re.I)
    if fl:
        if model == "2.0":
            issues.append(f"C8 Seedance 2.0 全面禁用首尾帧：出现 {sorted(set(fl))}（2.0 参考图仅锁定形象）")
        else:
            issues.append(f"C8 首尾帧仅限 2.5「参考模式②」：出现 {sorted(set(fl))}——若走默认全能参考模式则删去；确用模式②需标注 mode=first_last_frame")

    # C9 平台高危词
    hits = [w for w in GORE_WORDS if w in text]
    if hits:
        issues.append(f"C9 正文出现平台高危词 {hits}——按 platform-safety-compliance-guide 全类目替代表在成句时直接改写（2.0 提及即召唤，禁靠否定式压制）")

    # C11 接续状态残留拦截（2026-10-09 语义反转：原「必带」作废，改为「出现即 FAIL」）
    #   废止理由：段尾栏位在逐镜渲染时读不到、对段内站位零作用、与 D 锁③ 空镜过渡相冲。
    #   替代：段末末 1 秒整秒定格（前置 0.5 秒收束窗）写进末镜行内；跨段对齐走段缝画面锁（segment-splicing.md §二 §三）。
    for _m in re.finditer(r"【接续状态】", text):
        _ln = text[: _m.start()].count("\n") + 1
        issues.append(
            "C11 第%d行 出现已废止的【接续状态】栏（2026-10-09 废止，残留即 FAIL）——"
            "段末末 1 秒整秒定格（前置 0.5 秒收束窗）改写进末镜行内，跨段对齐走段缝画面锁" % _ln)

    # C12 否定式硬删除 / 工作流规则词混入
    # 判据收窄两点（否则正常台词/表演描写会被误报，WARN 一多就没人看了）：
    #   ① 只在"指令性正文"上判——台词字段（角色对白）与【强制禁止项】/【音效】（负面词合法通道）内的否定句跳过；
    #   ② 否定词必须搭配"存在性对象"（人物/家具/背景…）才算删除指令；
    #      「睫毛没有颤动」「跟他没有半点关系」是描写与对白，不是"把东西删掉"。
    _neg_obj = (r"(人物|角色|路人|群演|演员|家具|道具|背景|场景|物体|动物|车辆|"
                r"观众|杂物|陈设|装饰|文字|字幕|水印|logo|LOGO)")
    _neg_pat = re.compile(r"(没有|不要出现|禁止出现)([\u4e00-\u9fa5]{0,4})" + _neg_obj)
    for ln in _feed.splitlines():
        probe = re.sub(r"台词：.*$", "", ln)
        probe = re.sub(r"【强制禁止项】.*$", "", probe)
        probe = re.sub(r"【音效】.*$", "", probe)
        for m in _neg_pat.finditer(probe):
            if not re.search(r"负面|排除|禁止角色变形|无水印|无字幕", probe[max(0, m.start() - 40):m.end() + 40]):
                warns.append(f"C12 正文疑似否定式硬删除「{m.group(0)}」——硬删除应整句移除，负面仅走【强制禁止项】负面词")
    # ★审计补丁P1 修：镜行头（）用途标签内的段缝/转场标注属**法定版式**
    #   （标准写法「（段尾断句收尾，下段直接切特写换机位硬切）」），与正文裸写规则词不同。
    #   先把镜行头的括注剥掉再扫，避免把合规版式判成违规。
    _feed_probe = "\n".join(
        re.sub(r"（[^（）]*?(?:换机位|硬切|切景别|转场|J-?cut|L-?cut|声先画后|音桥)[^（）]*?）", "", _ln)
        for _ln in _feed.splitlines())
    workflow = re.findall(r"末态继承|拼接节点|换机位|同机位硬接|可变数据|每段重写|每段更新", _feed_probe)
    if workflow:
        warns.append(f"C12 工作流规则名词混入投喂正文 {sorted(set(workflow))}——投喂正文只写「画面长什么样」，规则由执行者应用（末态继承/换机位等不进稿）")
    # C12 转场术语（2026-10-13 体检修复 A1）：文档三处声称拦、机检词表曾未覆盖 → 补机检兜底。
    #   术语只在分镜层标注（段缝两侧逐对标接缝式别），投喂稿转译成「画面怎么接」。
    #   抽帧豁免（2026-10-13 交叉 Gemini 修法合入）：「12fps 抽帧」「抽帧感」是 C23 法定风格参数
    #   写法（王家卫 step-printing 语法，历史示例稿 A 成稿在用），前置 Nfps 或后接「感」即放行。
    trans = []
    for _m in C12_TRANSITION_RE.finditer(_feed_probe):
        if _m.group(0) == "抽帧":
            _pre = _feed[max(0, _m.start() - 12):_m.start()]
            _suf = _feed[_m.end():min(len(_feed), _m.end() + 2)]
            if re.search(r"\d+\s*fps\s*$", _pre, re.I) or _suf.startswith("感"):
                continue
        trans.append(_m.group(0))
    trans = sorted(set(trans))
    if trans:
        warns.append(f"C12 转场术语裸写进投喂正文 {trans}——术语只在分镜层标注（段缝两侧逐对标接缝式别），"
                     "投喂稿转译成「画面怎么接」的可执行描述（如 J-cut 声先画后 →「下一场的声音先于画面 0.5~1s "
                     "进入，画面还停在上一场」）；规则权威 creative-transition-library.md §1.3")

    # C14 画外声（OS/VO）——规程见 vo-os-weaving.md
    os_shots = vo_shots = 0
    vo_os_chars = 0
    for ln_i, line in enumerate(text.splitlines(), 1):
        # 只统计【时间轴分镜】的镜行：OS/VO 是"在某镜里发声"的行为，
        # 【强制禁止项】/【音效】里出现"画外音/旁白"等字样不是使用，计入会误报配额。
        if not TIME_RE.search(line):
            continue
        is_os, is_vo = bool(OS_PAT.search(line)), bool(VO_PAT.search(line))
        if not (is_os or is_vo):
            continue
        os_shots += is_os
        vo_shots += is_vo
        snd_idx = line.find("声音：")
        dlg_idx = line.find("台词：")
        pic_seg = line[:snd_idx] if snd_idx >= 0 else line[:dlg_idx] if dlg_idx >= 0 else line
        snd_seg = line[snd_idx:] if snd_idx >= 0 else ""
        dlg_seg = line[dlg_idx:] if dlg_idx >= 0 else ""
        # ① 声画分离红线：OS 镜行画面段含开口词
        if is_os and MOUTH_PAT.search(pic_seg):
            issues.append(f"C14 第{ln_i}行 OS 声画分离红线：画面段出现开口词——独白发声时角色必须闭口，"
                          "改闭口神态微特写承载（嘴唇紧闭/瞳孔/手指，见 vo-os-weaving.md 纪律 2）")
        # ② OS/VO 写进台词字段（台词字段只装画内开口对白）
        if dlg_seg and (is_os and OS_PAT.search(dlg_seg) or is_vo and VO_PAT.search(dlg_seg)):
            issues.append(f"C14 第{ln_i}行 OS/VO 写进了台词字段——画外声一律走「声音：」段并标注画外身份，台词字段写\"台词：无。\"")
        # ③ OS/VO 使用 {} 台词字符（锁口型必穿帮）
        if snd_seg and re.search(r"\{[^}]*\}", snd_seg):
            issues.append(f"C14 第{ln_i}行 OS/VO 使用 {{}} 台词字符——{{}} 是锁口型对白通道，画外声禁用；走声音段文字标注（见 vo-os-weaving.md §二）")
        # 配额统计（中文字符）
        seg = snd_seg if snd_seg else pic_seg
        vo_os_chars += len(re.findall(r"[\u4e00-\u9fa5]", seg))
        # VO/OS 是配额制调味料，三项篇幅卡口按段独立核算（防多段稿全篇累加误报）
        _c14_segs = _segments_time if _segments_time else [("全文", 1, text)]
        for _sn14, _sb14, _st14 in _c14_segs:
            _os14 = _vo14 = _ch14 = 0
            _tr14 = parse_time_ranges(_st14)
            _dur14 = round(max((e for _s, e, _l in _tr14), default=0), 2) if _tr14 else dur
            for _l14 in _st14.splitlines():
                if not TIME_RE.search(_l14):
                    continue
                _io, _iv = bool(OS_PAT.search(_l14)), bool(VO_PAT.search(_l14))
                if not (_io or _iv):
                    continue
                _os14 += _io
                _vo14 += _iv
                _si14 = _l14.find("声音：")
                _di14 = _l14.find("台词：")
                _ps14 = _l14[:_si14] if _si14 >= 0 else _l14[:_di14] if _di14 >= 0 else _l14
                _ss14 = _l14[_si14:] if _si14 >= 0 else ""
                _seg14 = _ss14 if _ss14 else _ps14
                _ch14 += len(re.findall(r"[\u4e00-\u9fa5]", _seg14))
            _pfx14 = f"[{_sn14}] " if len(_c14_segs) > 1 else ""
            if _os14 > OS_MAX_SHOTS:
                warns.append(f"C14 {_pfx14}段内 OS 内心独白 {_os14} 镜 > 上限 {OS_MAX_SHOTS}——独白是配额制工具，超量即广播剧化（vo-os-weaving.md 纪律 1）")
            if _vo14 > VO_MAX_SHOTS:
                warns.append(f"C14 {_pfx14}段内 VO 旁白 {_vo14} 镜 > 上限 {VO_MAX_SHOTS}——旁白一点定调即可，多则听书化")
            _bdg14 = VO_OS_QUOTA * max(1, round(_dur14 / 15)) if _dur14 else VO_OS_QUOTA
            if _ch14 > _bdg14 + VO_OS_QUOTA_SLACK:
                warns.append(f"C14 {_pfx14}段内 VO+OS 总字数≈{_ch14} 字 > 折算上限 {_bdg14} 字（60~80 字/分钟钢性卡口，容差线 +{VO_OS_QUOTA_SLACK}）——删到只剩点题句")
    # C13 镜长雷同（节奏呼吸 · quality-gate-review P1 反例）
    # 对话段豁免（2026-10-13 用户裁定「对话段全面豁免」）：回合制正反打的镜长本就
    #   高度整齐（2s 一切是标准形态），C13 会把这种整齐误判成「机械等分」。
    if len(tr) >= 4:
        from collections import Counter
        _tr_nd = [(s, e, ln) for s, e, ln in tr if not _in_dlg(ln)]
        durs = [round(e - s, 2) for s, e, _ in _tr_nd]
        if len(durs) >= 4:
            cnt = Counter(durs)
            top_dur, top_n = cnt.most_common(1)[0]
            ratio = top_n / len(durs)
            if ratio >= 0.7:
                warns.append(f"C13 镜长雷同：{top_n}/{len(durs)} 镜均为 {top_dur}s（占比 {ratio:.0%}）——节奏缺乏快慢呼吸；镜长应按台词字数÷语速(3.5~6字/s，判定按最快档6)+情绪节拍倒推，禁机械等分（quality-gate-review P1「时长全篇雷同」反例）")

    # C15 拉伸凑时（法则 17：总时长同样由内容倒推，禁拉伸凑满剧本标注时长）
    lines_all = text.splitlines()
    has_dialogue = bool(DIALOGUE_RE.search(text))
    if tr:
        for s, e, ln in tr:
            line = lines_all[ln - 1] if 0 < ln <= len(lines_all) else ""
            d = round(e - s, 2)
            _c15_max = NO_DIALOG_SHOT_MAX if (not has_dialogue and len(line) < 85) else 6.0
            if d > _c15_max and NO_LINE_RE.search(line) \
                    and not OS_PAT.search(line) and not VO_PAT.search(line):
                warns.append(f"C15 第{ln}行 无台词镜 {d}s >{NO_DIALOG_SHOT_MAX}s——镜长必须由内容倒推，"
                             "禁止把氛围/过渡镜拉长凑满剧本标注的【本集时长】（一句≤40字动作行合理节拍≤6s）；"
                             "总时长允许比剧本标注短至 -25%，宁短勿拉")
        if not has_dialogue and dur > PURE_AMBIENT_SEG_MAX:
            # ★打戏稿豁免（2026-10-12 修复）：动作段全程"台词：无"是**常态而非病症**——
            #   历史示例稿（官方完整示例）四镜全无台词，
            #   却因本判据误报"纯氛围段拉伸凑时"。C15 治的是文戏"拿氛围镜凑时长"，
            #   对打戏/动作段不适用；与 C21/C22 同属「打戏档按豁免表放行」族（combat-rhythm-and-load-guardrails.md §七）。
            if not _combat_on(text, combat):
                warns.append(f"C15 全段 {dur}s 无任何台词（纯氛围段）>{PURE_AMBIENT_SEG_MAX}s——若非 D 锁③空镜过渡（1~2s）"
                             "或蓄意留白的爆点镜，即为拉伸凑时；压缩节拍或与钩子台词合并同段")

    # C16 对白语气（model-adapters §5.2 官方对白三要素之三 HOW THEY SOUND）
    # 只扫【时间轴分镜】的镜行；只统计"有台词"的镜行（"台词：无。"不参与语气判定）。
    _dlg = []
    for ln_i, line in enumerate(text.splitlines(), 1):
        if not TIME_RE.search(line):
            continue
        di = line.find("台词：")
        if di < 0:
            continue
        if NO_LINE_RE.match(line, di):
            continue
        _dlg.append((ln_i, line, di))
    if _dlg:
        miss = []
        for ln_i, line, di in _dlg:
            si = line.find("声音：")
            pic = line[:si] if 0 <= si < di else line[:di]
            hit = [w for w in TONE_STRONG if w in pic]
            for w in TONE_SOFT:
                k = pic.find(w)
                if k >= 0 and not TONE_FACE_CTX.search(pic[max(0, k - 8):k]):
                    hit.append(w)
            if hit:
                warns.append(f"C16a 第{ln_i}行 语气错位：画面段出现声音词 {sorted(set(hit))}——"
                             "声音词会被模型当视觉信息渲染（画出一张冷笑的脸），应移入台词语气位 "
                             "`台词：【角色（语气）：“…”】`（model-adapters §5.2）")
            tm = TONE_TAG_RE.search(line[di:])
            if tm is None:
                miss.append(ln_i)
            else:
                v = [w for w in TONE_VAGUE if w in tm.group(1)]
                if v:
                    warns.append(f"C16c 第{ln_i}行 语气位含空泛结果词 {v}——按四维改写"
                                 "（情绪色/力度/音质/节奏），如「压着怒·低语」而非「愤怒」")
                # C16d 道具动作与语气冲突：闲适把玩 × 宣判/强情绪语气
                am = IDLE_PROP_RE.search(pic)
                tw = [w for w in TONE_SEVERE if w in tm.group(1)]
                if am and tw:
                    warns.append(f"C16d 第{ln_i}行 道具动作与语气冲突：「{am.group(0)}」×语气「{tw[0]}」——"
                                 "闲适把玩配不上宣判/强情绪时刻（实测出戏：正俯视宣判台词还在把玩玉佩）。"
                                 "换成贴合语气的动作：攥紧/捏住/垂手握着（model-adapters §5.0.3）")
        if len(miss) / len(_dlg) > TONE_MISS_RATIO:
            warns.append(f"C16b 语气缺失：{len(miss)}/{len(_dlg)} 条台词未带语气位"
                         f"（缺失率 {len(miss)/len(_dlg):.0%} > 阈值 {TONE_MISS_RATIO:.0%}）——"
                         "台词应写 `台词：【角色（语气）：“…”】`；2.0/2.5 同规格必写，"
                         "缺语气会让声音与表情一并扁平（官方点名 tone_qualifiers）")

    # C17 摆位必入画（model-adapters §5.0.1 人物账连续）· 2026-10-10 逐段化
    # 单场景连续段里人物凭空消失/重现 = 跨段衔接最典型穿帮。单人站位段不触发（无跨段风险）。
    # 旧实现只取全文第一个【站位声明】——段1 若是单人段，段2 之后的「B 不见了」全部漏检；
    # 真实投喂稿是「提示词组 × N 组」（3 分钟剧 ≈14 段），故改为按【画幅风格】切段**逐段自查**。
    # 站位块 = 【站位声明】行 + 其后连续非【段行（兼容"独占一行、@人名在下一行"的排版）。
    lines_all = text.splitlines()
    seg_zw = []            # [(段名, 段首行号, 段内行, 站位块, 站位人物, 镜行, 台词镜行)]
    for _seg_name, _seg_base, _seg_text in _split_segments(text):
        _lines = _seg_text.splitlines()
        _zw_i = next((i for i, l in enumerate(_lines) if l.strip().startswith("【站位声明】")), None)
        _zw_block, _zw_people = "", []
        if _zw_i is not None:
            _zw_block = _lines[_zw_i]
            _j = _zw_i + 1
            while _j < len(_lines) and not _lines[_j].strip().startswith("【"):
                _zw_block += _lines[_j]
                _j += 1
            _zw_people = ZW_PERSON_RE.findall(_zw_block) or _zw_people_loose(_zw_block)
        _shots = [(_seg_base + n, l) for n, l in enumerate(_lines) if TIME_RE.search(l)]
        _dlgs = [(n, l, l.find("台词：")) for n, l in _shots
                 if l.find("台词：") >= 0 and not NO_LINE_RE.match(l, l.find("台词："))]
        seg_zw.append((_seg_name, _seg_base, _lines, _zw_block, _zw_people, _shots, _dlgs))
        # ---- C17 摆位必入画（本段自查）----
        if len(_zw_people) >= 2:
            _shot_blob = "".join(l for _n, l in _shots)
            _ctx = _zw_block + "".join(
                l for l in _lines if "@CHR-" in l or l.strip().startswith("【站位声明】"))
            _gone = []
            for p in _zw_people:
                if p in _shot_blob:
                    continue
                _exempt = False
                for m in re.finditer(re.escape(p), _ctx):
                    if any(w in _ctx[m.end():m.end() + 24] for w in C17_EXIT_WORDS):
                        _exempt = True
                        break
                if not _exempt:
                    _gone.append(p)
            if _gone:
                warns.append(
                    f"C17 [{_seg_name}] 摆位必入画：站位声明摆了位、但本段镜行一次都未带到的人物："
                    + "、".join(_gone)
                    + "——人物凭空消失，跨段衔接必穿帮（model-adapters §5.0.1）。"
                      "给该人物至少一个镜头（正拍/焦外身影/全景群像/反应镜头均算），"
                      "或在站位行写明「离画/退场·去向」；重新入画的段要写明入画方式")

    # C17d 跨段站位漂移（法则 20·③「相邻段没写移动的人位置不得改变」· 2026-10-10 新增）
    # 承载层此前为空：站位声明单段写对了，但下一段悄悄把人挪到另一边——观众直接读出错乱。
    # 判据：相邻段同名人物 的 画面位置 / 背景锚 发生改变、且后一段【位移】未声明 → WARN。
    _ZW_FIELD_RE = re.compile(r"@([\u4e00-\u9fa5A-Za-z0-9_\-]+)\s*[（(]([^）)]*)[）)]")
    _POS_ORDER = ("画面左后", "画面右后", "画面中后", "画面左前", "画面右前",
                  "画面左", "画面右", "画面中", "画面前", "画面后")

    def _zw_fields(block):
        _out = {}
        for _m in _ZW_FIELD_RE.finditer(block):
            _nm, _inner = _m.group(1), _m.group(2)
            _pos = next((p for p in _POS_ORDER if p in _inner), "")
            _anc = ""
            _am = re.search(r"(?:身后|背后|侧后|后方|背靠)(?:为|是|：)?\s*([^，,；;）)〕\]·]{1,20})", _inner)
            if _am:
                _anc = _am.group(1).strip().strip("*").strip()
            _out[_nm] = (_pos, _anc)
        return _out

    def _seg_scns(lines_list):
        return set(re.findall(r"@SCN-[^\s（(，,；;：:【】]+", "\n".join(lines_list)))

    for (_n1, _b1, _l1, _blk1, _p1, _s1, _d1), (_n2, _b2, _l2, _blk2, _p2, _s2, _d2) \
            in zip(seg_zw, seg_zw[1:]):
        _sc1, _sc2 = _seg_scns(_l1), _seg_scns(_l2)
        if _sc1 and _sc2 and _sc1 != _sc2:
            continue
        _f1, _f2 = _zw_fields(_blk1), _zw_fields(_blk2)
        _sm = re.search(r"位移[:：]([^\n]*)", _blk2)
        _shift = _sm.group(1) if _sm else ""
        _drift = []
        for _nm in _f2:
            if _nm not in _f1:
                continue
            (_p1v, _a1v), (_p2v, _a2v) = _f1[_nm], _f2[_nm]
            if _p1v and _p2v and _p1v != _p2v and _nm not in _shift:
                _drift.append(f"{_nm} 画面位置 {_p1v}→{_p2v}")
            elif _a1v and _a2v and _a1v != _a2v and _nm not in _shift:
                _drift.append(f"{_nm} 背景锚 {_a1v}→{_a2v}")
        if _drift:
            warns.append(f"C17d 跨段站位漂移（{_n1}→{_n2}）：" + "；".join(_drift)
                         + "——相邻段未写移动的人物，画面位置与背景锚不得改变"
                           "（法则 20·③ / segment-splicing.md §三 段缝末态继承）。"
                           "确需挪人，就在该段【站位声明】的「位移：」行写明「起点→终点」")

    # C17f 单一方位权威：镜行禁重复段首已摆位角色的绝对画面左右（2026-10-15 用户实测裁定）
    # 病根：段首【站位声明】已锁某人"画面左"，某镜行又写"画面右/画面右后"＝给模型喂一对矛盾的
    #   左右指令，实测致人物"东一个西一个、突然出现在身后"。规则已改为"镜行只写位移增量 + 依托物，
    #   禁重复绝对画面左右"（model-adapters §5.0 单一方位权威）；本条把"镜行是否又写了段首角色的
    #   画面左右"变成可告警——堵住旧规下矛盾声明无声存活的缺口（此前 C17/C20 无一条校验此项）。
    # 保守判据（宁漏勿误）：段首【站位声明】里明确给了画面方位的角色，其名字在某镜行内 ~14 字窗口内
    #   又出现 _POS_ORDER 画面方位词 → WARN。只认"画面左/右"全词（避开"左侧招牌/右后方打光"等光源方向），
    #   只查段首已摆位角色（新入画者首次给方位不拦）。
    for (_nm_seg, _b_seg, _l_seg, _blk_seg, _p_seg, _s_seg, _d_seg) in seg_zw:
        _declared = {k: v for k, v in _zw_fields(_blk_seg).items() if v[0]}
        if not _declared:
            continue
        _restate = []
        for _ln_no, _ln in _s_seg:
            for _c, (_cp, _ca) in _declared.items():
                for _cm in re.finditer(re.escape(_c), _ln):
                    _win = _ln[_cm.end():_cm.end() + 14]
                    _hit = next((p for p in _POS_ORDER if p in _win), "")
                    if _hit:
                        _restate.append(f"镜{_ln_no}「{_c}」又写{_hit}（段首已锁{_cp}）")
                        break
        if _restate:
            warns.append(
                f"C17f [{_nm_seg}] 单一方位权威：镜行重复声明了段首已摆位角色的绝对画面左右——"
                + "；".join(_restate[:4]) + ("…" if len(_restate) > 4 else "")
                + "。段首【站位声明】是本段唯一方位权威；镜行只写位移增量（向前半步）+ 依托物"
                  "（背靠卷帘门），禁重复画面左右——双重发位会让人物「东一个西一个、突然出现在身后」"
                  "（model-adapters §5.0）。确需越轴/大幅移动，在段首【站位声明】的「位移：」行写明「起点→终点」")

    # C18o 时段光影基准在段（2026-10-15 · model-adapters §5.0.5b · 治"AI 光不知从哪打"）
    # 病根：七段式原本镜行无光影位 → AI 光路随机、画面发灰。§5.0.5b 要求【场景资产】立时段光影基准、
    #   镜行只写增量/特写眼神光。本条保守兜底：整段既无时段光影基准、镜行也无任何光影词 → WARN。
    #   保守判据（宁漏勿误）：段内出现任一处光影信号即放行（"时段光影："或镜行主光/轮廓/眼神/冷暖等词）。
    _LIGHT_SIG = re.compile(
        r"时段光影|主光|侧光|逆光|顶光|底光|轮廓光|眼神光|边缘光|背光|光向|光质|硬光|柔光|散射"
        r"|冷暖|暖金|冷蓝|暖黄|色温|天光|霓虹|钨丝|丁达尔|光斑|光影|补色|打光|布光|月光|烛光|日光")
    for (_nm_seg, _b_seg, _l_seg, _blk_seg, _p_seg, _s_seg, _d_seg) in seg_zw:
        if not _LIGHT_SIG.search("".join(_l_seg) + _blk_seg):
            warns.append(
                f"C18o [{_nm_seg}] 时段光影基准缺失：整段既无【场景资产】时段光影、镜行也无任何光影词——"
                "AI 会随机打光、画面发灰（model-adapters §5.0.5b）。请在【场景资产】补「时段光影：主光方向·光质·"
                "光色冷暖·天空/时段·暗部补色」，镜行只写增量/特写眼神光；反光道具不写光效、禁写光比 X:1 参数")

    # C17e 人数变化未交代（法则 20·②b「新面孔首现要交代」· 2026-10-13 新增 · 用户实测反馈）
    # 病根：段1 场上只有两人对峙 → 段2 开场直接四人围桌，另两人凭空出现、零交代——
    #       观众读作「跳了一段」（用户原话「段一到段二没有任何逻辑的过渡，它得有一个过渡吧」）。
    #       此前 C17/C17b/C17c/C17d 全是「同一个人的位置/景别接不接得上」，**没有一条管「人数变化」**。
    # 判据：相邻两段【核心人物】名单比对——后段出现前段没有的**新具名人物**，且后段全文无
    #       ①画内入画 / ②画外先声 / ③空镜转场 / ④末镜行句尾过渡 任一过渡类词 → WARN，点到人名。
    # 豁免：`（在场）`静默人物（无台词无反应）——走软口径，不单独要求入画镜；段间时间跳天然误报，人工复核。
    # ⚠️ 误报代价低于漏报：本判据是 WARN 参考级，判「段缝合法」以 segment-splicing.md §四·补二 是否落地为准。
    C17E_ENTRANCE_WORDS = ("入画", "走进", "走进来", "进来", "进门", "跨门槛", "迈进", "推门",
                           "自门外", "从门外", "从外", "从里屋", "从走廊", "从侧门", "走出",
                           "折返", "返回", "落座前", "已被扶", "扶着", "声先入", "传来", "空镜",
                           "转场", "淡入", "叠化", "已在场", "开场前", "先已")
    _CORE_FIELD_RE = re.compile(r"【核心人物】([^【]*)")

    def _core_people(block):
        """解析【核心人物】名单 → {人名: 是否（在场）}"""
        _m = _CORE_FIELD_RE.search(block or "")
        if not _m:
            return {}
        _out = {}
        for _ln in _m.group(1).splitlines():
            _pm = re.search(r"@(?:(?:CHR|SCN|PRP|ITM|PROP|ENV|OBJ)-)?([^\s@（）()【】，、；;：:]+)", _ln)
            if _pm:
                _out[_pm.group(1)] = ("（在场）" in _ln or "(在场)" in _ln)
        return _out

    for (_n1, _b1, _l1, _blk1, _p1, _s1, _d1), (_n2, _b2, _l2, _blk2, _p2, _s2, _d2) \
            in zip(seg_zw, seg_zw[1:]):
        # ⚠️ _blk1/_blk2 是【站位声明】块；本判据要的是【核心人物】名单 → 从整段行 _l2 抽。
        #    _l1/_l2 是**行列表**，必须用 "\n".join 保留换行——"".join 会把多行糊成一行，
        #    导致 _core_people 只解析到名单里第一个 `@人名`（实测 C17e 因此静默不触发）。
        _sc1, _sc2 = _seg_scns(_l1), _seg_scns(_l2)
        if _sc1 and _sc2 and _sc1 != _sc2:
            continue
        _c1, _c2 = _core_people("\n".join(_l1)), _core_people("\n".join(_l2))
        if not _c1 or not _c2:
            continue
        _new = [p for p in _c2 if p not in _c1]
        # 豁免：`（在场）`静默人物走软口径，不单独要求入画镜（除非该段对白/动作里确有它）
        _new = [p for p in _new if not _c2[p]]
        if not _new:
            continue
        _blob2 = "".join(_l2)
        if any(w in _blob2 for w in C17E_ENTRANCE_WORDS):
            continue
        warns.append(f"C17e 人数变化未交代（{_n1}→{_n2}）：本段新增人物 "
                     + "、".join(_new)
                     + " 在前一段不存在，且本段全文无任何进出场交代"
                       "（①画内入画 / ②画外先声 / ③空镜转场 / ④末镜行句尾过渡）"
                       "——观众读作「跳了一段」（法则 20·②b / segment-splicing.md §四·补二）。"
                       "补法：前 1~2 秒写「自画面外走入画框 / 从里屋跨门槛进来 / 声先入」等")

    # C27 对话戏节奏与台词密度下限（2026-10-13 新增 · 用户实测反馈）
    # 病根：包内此前**只有上限、没有下限**——§一 语速档、§一·补二 密度表、闸门2、闸门3 全在防"超载"。
    #       结果：描述是"必须写"、台词是"可以少写" → 被牺牲的必然是台词；且切镜按"内容块"切而非
    #       "回合"切 → 出现"一个人说完另一个人说"的站桩式对话（用户原话「缺乏快速的正反打」）。
    # 实证：粉丝稿《白凰学院捉鬼师》30s/8镜 = 3.75s 一切、每切换嘴、单次发言 6~18 字；
    #       本方稿段2 15s/4镜 = 每镜恒 1 人开口 → 节奏呆。
    # 判据（**只对对话段生效**，非对话段一律跳过、绝不误报）：
    #   C27a 段落类型信号缺失（无"对话/空镜/打斗"任一可识别标记）→ 不报（无法判定，交给人工）
    #   C27b 对话段台词密度 < 2.0 字·秒⁻¹（15s 段 < 30 字）→ WARN
    #   C27c 对话段开口次数 < 6 次/15s（按段长等比折算，下限 3）→ WARN
    #   C27d 同一说话人连续占据 ≥2 个完整镜行开口 → WARN（站桩式对话）
    #        ※P8（2026-10-24）：镜内出现 ≥2 个不同说话人 = 已换嘴，豁免并打断连排
    # 豁免（**2026-10-13 用户补充「灵活、服务剧情」后扩写**）：
    #   ① 空镜段 / 转场段 / 打斗段 —— 不设下限；
    #   ② **该慢的戏** —— 静场 / 宣判 / 留白 / 氛围 / 长镜 等**显式标注**的段落，三条全跳过。
    #      用户原话：「我**也不知道你为了切而切**，像有一些剧情就**不适合这种来回的切**，
    #      **灵活懂吗？是服务剧情的**」。机检不能把"该慢的戏"误判成"站桩式对话"。
    #   ③ **空镜带声** —— 空镜段若带台词（公园空镜传来人声→切到两人对话），
    #      **合法且常用**（声桥过渡）；机检按"跳过"处理（不误伤纯空镜），
    #      但**不代表违规**——不产 FAIL，由人判断。
    C27_DIALOGUE_MARK = ("对话", "对白", "文戏", "谈判", "争执", "争吵", "商议", "聊")
    # "不判"标记：空镜/打斗/转场（不设下限）+ 该慢的戏（静场/宣判/留白/氛围）
    C27_NO_DIALOGUE_MARK = ("空镜", "打斗", "战斗", "武戏", "动作段", "转场", "蒙太奇",
                            "独白", "宣判", "静场", "留白", "氛围段", "长镜段", "情绪积累")

    def _c27_seg_type(lines):
        """判段落类型 → 'dialogue' / 'none'（不适用）。保守：分不清就返回 None（不报）。"""
        _head = "\n".join(lines[:12])
        # 先看显式声明（段首/镜行头里的类型词）
        if any(w in _head for w in C27_NO_DIALOGUE_MARK):
            return "none"
        if any(w in _head for w in C27_DIALOGUE_MARK):
            return "dialogue"
        # 无显式声明时只统计真实时间轴镜行（排除段9 PERFORMANCE「台词：语速…」误计），且须 ≥4 条台词才判为高频快切对话段
        _n = sum(1 for l in lines if TIME_RE.search(l) and "台词：" in l and "无" not in l.split("台词：")[1][:3])
        return "dialogue" if _n >= 4 else None

    def _c27_shot_span(line):
        """从镜行取 [起, 止] 秒（兼容 MM:SS / Xs-Ys / N-N秒 三形态，与 parse_time_ranges 同源）。"""
        _trs = parse_time_ranges(line)
        if not _trs:
            return None
        return _trs[0][0], _trs[0][1]

    _c27_seen, _c27_ran = 0, 0
    for (_n, _b, _l, _blk, _ppl, _shots, _dlgs) in seg_zw:
        if not _shots:
            continue
        _c27_seen += 1
        _styp = _c27_seg_type(_l)
        if _styp != "dialogue":
            continue
        # 段长：末镜止 - 首镜起（先算 _spans 再计 _c27_ran，防时码解析失败却虚增 _c27_ran 绕过 C27x）
        _spans = [s for s in (_c27_shot_span(l) for _x, l in _shots) if s]
        if not _spans:
            continue
        _c27_ran += 1
        _seg_len = max(s[1] for s in _spans) - min(s[0] for s in _spans)
        if _seg_len <= 0:
            continue
        # C27b 台词密度下限（2.0 字·秒⁻¹）
        _chars = 0
        _open_cnt = 0
        _speakers = []            # 按镜行顺序记录的开口者（用于 C27c/C27d）
        for _ln_no, _ln, _pos in _dlgs:
            _seg_txt = _ln[_pos + len("台词："):]
            for _q in re.findall(r"[\"“]([^\"”]*)[\"”]", _seg_txt):
                if not _q.strip():
                    continue
                _chars += len(re.sub(r"[\s，。！？、；：…—\"'（）()《》【】\[\],.!?;:]+", "", _q))
                _open_cnt += 1
            # ★P8 修（2026-10-24 · 网友实跑反馈 P-03 核验后修正）：
            #   判据原文是「同一说话人连续占据 ≥2 个完整**镜行**」，旧实现「一个镜行只记第一个
            #   【】括注里的人名」→ **镜内换嘴（一镜两人对答）被记成同一人独占**。
            #   实测：连续两镜都写 `台词：【甲（冷）："…"】【乙（急）："…"】`（V7 允许、正反打
            #   高频写法）→ 误报「甲 连续 ≥2 镜独占开口」。真写了一半的稿子被判站桩，
            #   用户会以为自己写得差（网友原话：改成「每镜只留一人开口 + 严格交替」仍报）。
            #   现改为：本镜行内出现 **≥2 个不同说话人 = 已换嘴**，记为 __MULTI__，
            #   既不进独占连排统计，还**打断连排**（换嘴就是换嘴，不管换在第几镜）。
            _ln_sps = []
            for _br in re.findall(r"【([^】]*)】", _seg_txt):
                # 名字只取括注**开头**，避免把引号内台词里的「某某（…）」当成第二个说话人
                _msp = re.match(r"\s*@?\s*([^\s@（(【，,、:：]{1,8})\s*[（(]", _br)
                if _msp and _msp.group(1) not in _ln_sps:
                    _ln_sps.append(_msp.group(1))
            if not _ln_sps:
                # 无【】格式的旧稿：退化为「名字（」扫描，按出现顺序去重
                for _msp in re.finditer(r"@?([^\s@（(【，,、:：]{1,8})\s*[（(]", _seg_txt):
                    if _msp.group(1) not in _ln_sps:
                        _ln_sps.append(_msp.group(1))
            if len(_ln_sps) >= 2:
                _speakers.append("__MULTI__")
            elif _ln_sps:
                _speakers.append(_ln_sps[0])
            else:
                _speakers.append("?")
        _need_chars = int(_seg_len * 2.0)
        if _chars < _need_chars:
            warns.append(f"C27b 对话段台词密度不足（{_n}）：{_seg_len:.0f} 秒仅 {_chars} 字"
                         f"（下限 {_need_chars} 字 ≈2.0 字·秒⁻¹）——台词量太少会被观众读作"
                         "「技术说明书」。补法：① OS 补位（零口型成本）② 长句拆成两次短开口 "
                         "③ 加上对方回嘴追问；⛔ 禁靠拉长文采凑字"
                         "（对话戏节奏律见 shot-economy-and-acting.md §五·七 · "
                         "密度下限见 dialogue-speed-check.md §一·补三）")
        # C27c 开口次数下限（15s ≥6 次，等比折算、下限 3）
        _need_open = max(3, round(_seg_len / 15 * 6))
        if _open_cnt < _need_open:
            warns.append(f"C27c 对话段开口次数不足（{_n}）：{_seg_len:.0f} 秒仅 {_open_cnt} 次开口"
                         f"（下限 {_need_open} 次 ≈15 秒 6 次）——正反打来回不够，"
                         "读起来是「一个人说完另一个人说」的站桩式对话。补法：短句化 + 换嘴切镜 + OS 补位")
        # C27d 同一说话人连续占据 ≥2 个完整镜行开口（站桩式对话）
        #   镜内换嘴行（__MULTI__）不算独占，且打断连排
        _prev_sp, _run = None, 0
        _run_hit = []
        for _sp in _speakers:
            if _sp == "__MULTI__":
                _prev_sp, _run = None, 0
                continue
            if _sp == _prev_sp and _sp != "?":
                _run += 1
                if _run >= 2:
                    _run_hit.append(_sp)
            else:
                _run = 1 if _sp != "?" else 0
            _prev_sp = _sp
        if _run_hit:
            _uniq = sorted(set(_run_hit))
            warns.append(f"C27d 站桩式对话（{_n}）：说话人 " + "、".join(_uniq)
                         + " 连续 ≥2 镜独占开口——切镜点应按「**回合**」切（每切一次换嘴），"
                           "不是按「内容块」切。判据：一次切镜至少换 说话人/景别/角度/主体 之一；"
                           "⛔「只为这句说完了而切、其余变量全不变」= 废切"
                           "（镜内两人对答的一镜已按「已换嘴」豁免，不参与本判据）"
                           "（shot-economy-and-acting.md §五·七·①）")

    # C27x 跳过率元告警（2026-10-13 新增 · 治「保守跳过型检查静默全绿」）
    # 病根：C27（及 C28b）依赖段落类型识别，设计上「分不清就不报」（防误报）；
    #   代价是——**一旦识别失效，检查全绿而其实一条都没跑**。这正是 C7b/C7c 当年
    #   专门要治的病（「检查器静默失效仍报绿灯」），但当年只治了「解析失效」两处，
    #   没治「识别跳过」。故此处补一条**元告警**：跳过率 100% 且段数 ≥2 → 报「检查未生效」。
    _total_dlg_shots = sum(len(_d) for (_n, _b, _l, _blk, _ppl, _s, _d) in seg_zw)
    if (_c27_seen >= 2 and _c27_ran == 0 and _total_dlg_shots >= _c27_seen * 4
            and _feed.count("台词：【") < 4):   # ★审计补丁P1：稿内台词密度已达标时不报（识别器自身失效，不该让用户背锅）
        warns.append("C27x 段落类型识别未生效（元告警）：本次 %d 段**全部**被判为非对话段，"
                     "C27b/c/d 与 C28b 一条都没跑——**本次「无 C27/C28 告警」不等于合规**。"
                     "请检查段落是否缺少类型标记（对话 / 空镜 / 打斗 / 转场）；"
                     "若本稿确实全为非对话段（纯空镜/纯打斗），本告警可忽略。" % _c27_seen)

    # C28 台词机械化探测（2026-10-13 新增 · 增量主码 · 编号不重排 · 只报不改）
    # 由来：用户反馈「台词机械化／不够拟人／缺称呼」。根因审计确认——本包台词规则全在剧本层
    #   （sd-script-engine），且**全是否定式**（不许播音腔 / 不许同口吻），缺"正向供给"；
    #   而下游铁律「台词逐字保留、不得删改」（dialogue-speed-check.md §一·补二）意味着
    #   **剧本层写机械了，P3→P4→成片全链路无人能救**，且此前**没有任何机检会报警**。
    #   本码补的就是这条缺失的反馈回路：**下游只报不改，报出来即触发回上游过站改稿**。
    # 权威：sd-script-engine/references/dialogue-naturalization.md §八（机检口径）
    # 判据：
    #   C28a 台词出现现代书面虚词（§2.2 A 类表，任何题材的口语台词都不这么说）→ WARN
    #   C28b 对话段台词 ≥40 字且语气词数为 0（机械化最典型指纹）→ WARN
    #   C28c 单句 ≥20 字且句内无任何停顿标点（人说话会断）→ WARN
    # ⛔ 本码只报不改——下游禁改台词；修复须回阶段⑤ 过《台词拟人化过站》。
    C28_BOOKISH = ("是否", "因此", "从而", "鉴于", "予以", "加以", "可否", "何以",
                   "颇为", "甚为", "以及", "然而", "由于", "进行")
    C28_PARTICLE = ("啊", "吧", "呢", "嘛", "呗", "啦", "呀", "哦", "咯", "嗯",
                    "唉", "哎", "嘿", "哟", "罢了", "而已")
    C28_PAUSE = ("，", "、", "—", "…", "；", "：", "?", "？", "!", "！")
    _c28_words, _c28_b, _c28_c = set(), [], []
    for (_n, _b, _l, _blk, _ppl, _shots, _dlgs) in seg_zw:
        if not _dlgs:
            continue
        _styp28 = _c27_seg_type(_l)
        _s_chars, _s_part = 0, 0
        for _ln_no, _ln, _pos in _dlgs:
            _seg_txt = _ln[_pos + len("台词："):]
            for _q in re.findall(r"[\"“]([^\"”]*)[\"”]", _seg_txt):
                if not _q.strip():
                    continue
                for _w in C28_BOOKISH:
                    if _w in _q:
                        _c28_words.add(_w)
                _s_chars += len(re.sub(r"[\s，。！？、；：…—\"'（）()《》【】\[\],.!?;:]+", "", _q))
                _s_part += sum(1 for _p in C28_PARTICLE if _p in _q)
                for _sent in re.split(r"[。！？!?]+", _q):
                    _s = _sent.strip()
                    if len(_s) >= 20 and not any(_p in _s for _p in C28_PAUSE):
                        _c28_c.append((_n, _s[:24]))
        if _styp28 == "dialogue" and _s_chars >= 40 and _s_part == 0:
            _c28_b.append((_n, _s_chars))
    if _c28_words:
        warns.append("C28a 台词出现现代书面虚词：" + "、".join(sorted(_c28_words))
                     + " —— 口语台词不这么说（「是否」→「是不是」、「因此」→「所以」、"
                       "「以及」→「还有」、「进行+名词」→ 直接用动词）。"
                       "⛔ 本码只报不改（下游铁律：台词逐字保留）；修复须回阶段⑤ 过"
                       "《台词拟人化过站》（dialogue-naturalization.md §二·2 词汇表 + §三 撒碎屑四法）")
    if _c28_b:
        _seg_s = "、".join(_x for _x, _ in _c28_b[:3])
        warns.append(f"C28b 对话段零语气词（{_seg_s}）：整段对话没有任何「啊/吧/呢/嘛」类句尾助词"
                     "——这是机械化台词最典型的指纹。补法见 dialogue-naturalization.md §三·4"
                     "（⚠️ 宣判段/静场留白段属刻意处理，须在段首显式标注段落意图）")
    if _c28_c:
        _n0, _s0 = _c28_c[0]
        warns.append(f"C28c 长句无停顿（{_n0}）：「{_s0}…」单句 ≥20 字且句内无任何停顿标点"
                     "——人说话会断气。拆法：加逗号/破折号/省略号，或按 §三·1·2 打断掉尾"
                     "（dialogue-naturalization.md §二·4 句式层）")

    # C29 资产状态偏离探测（2026-10-13 新增 · 增量主码 · 编号不重排 · 只报不改）
    # 由来（用户实测）：外卖员资产图**戴着头盔**，提示词让他坐家里、**把头盔夹在怀里** →
    #   成片里**同时出现两个头盔**（头上一个、怀里一个）。同型：长发/剪短、戴眼镜/摘下、穿外套/脱掉。
    # 病根：**参考图锁定的是静态基准，剧情需要动态状态**；二者冲突时若**没有优先级声明**，
    #   模型会【叠加】而不是【替换】（权威：model-adapters.md §5.0.6 资产偏离声明
    #   + asset-spatial-ledger.md §四·B·补 CHAR_STATE）。
    # 判据：镜行出现「脱离动词 + 名词」，且该名词在【核心人物】行中出现（＝属角色锁定项），
    #   而全稿无偏离声明（"偏离 / 以本段为准 / 覆盖角色参考图"）→ WARN。
    # ⛔ 只报不改——修复须回 P4 补偏离标注（或回资产层登记 CHAR_STATE 出脱离态参考图）。
    C29_DETACH = ("摘下", "脱下", "取下", "解开", "夹在", "夹着", "拎着", "拎在",
                  "捧在", "捧起", "抱在怀", "挂在", "别在", "端在")
    C29_DECL = ("偏离", "以本段为准", "覆盖角色参考图", "覆盖参考图")
    _h29 = []
    _c29_segs = _segments_time if _segments_time else [("全文", 1, text)]
    _all_ch29 = "\n".join(m.group(1) for m in re.finditer(r"【核心人物】([\s\S]*?)(?=\n【|$)", text))
    for _sn29, _sb29, _st29 in _c29_segs:
        _m_ch29 = re.search(r"【核心人物】([\s\S]*?)(?=\n【|$)", _st29)
        _ch29 = _m_ch29.group(1) if _m_ch29 else _all_ch29
        _dec29 = any(_d in _st29 for _d in C29_DECL)
        if _ch29 and not _dec29:
            for _line29 in _st29.splitlines():
                _l29 = _line29.strip()
                if not _l29 or _l29.startswith("【"):
                    continue
                # ★审计补丁P1 修：台词里的「摘下来」是人物在说话，不是画面指令 → 先剥台词再判
                _l29 = re.sub(r"台词：.*$", "", _l29)
                if not _l29:
                    continue
                for _dv29 in C29_DETACH:
                    _i29 = _l29.find(_dv29)
                    if _i29 < 0:
                        continue
                    # 名词可能在动词**前**（"把头盔夹在…"）或**后**（"夹着头盔"）→ 前后都扫；
                    # 取「在【核心人物】行中出现过的最长中文串」作为命中词（防碎片误匹配）
                    _ctx29 = _l29[max(0, _i29 - 10):_i29 + len(_dv29) + 10]
                    _best29 = ""
                    for _st_i in range(len(_ctx29)):
                        for _ln29 in (5, 4, 3, 2):
                            _w29 = _ctx29[_st_i:_st_i + _ln29]
                            if len(_w29) == _ln29 and _w29 in _ch29 and len(_w29) > len(_best29):
                                _best29 = _w29
                    if _best29:
                        # ★P6.3 修误报：命中的「名词」若本身是角色名，不算锁定物品—— 
                        #   实测「书包挂在左肩，@沈甜 侧头…」会把「沈甜」当被脱离的物品（假 WARN）。
                        _names29 = set(re.findall(r"@([^\s（(，、）]+)", _ch29))
                        if _best29.lstrip("@") in _names29:
                            continue
                        _h29.append(_dv29 + "·" + _best29)
    if _h29:
        warns.append("C29 疑似资产状态偏离未声明：" + "、".join(sorted(set(_h29))[:4])
                     + " —— 该物品出现在【核心人物】行（属角色锁定项），"
                       "但本段要求它脱离身体、且全稿无偏离声明。"
                       "⚠️ 参考图锁定的是「它长什么样」，不是「它必须在身上」；"
                       "缺替换声明时**模型会【叠加】而非【替换】**（实测表现：头上一个 + 手里一个 的双现）。"
                       "补法：①【核心人物】行尾加偏离标注（须含「以本段提示词为准，覆盖角色参考图」替换语）；"
                       "② 补脱离后本体的物理后果（如「额前头发被压扁」）；③ 禁项兜底。"
                       "（权威：model-adapters.md §5.0.6；跨 2 镜以上改走 CHAR_STATE 出脱离态参考图）")

    # C18m 段缝景别落差（2026-10-11 新增 · 用户实测反馈 · 当日二次确权 · segment-splicing.md §四·补）
    # 病根：段缝换机位铁律只要求「换视角或换景别其一」——于是「末镜拉全景收束 → 下段首镜
    #       切中景」这种反向收紧可合法通过；实测观感是「刚拉开的空间又被糊回脸上」。
    # 底层逻辑（用户口径）：段缝的画面依据不是重绘，而是上一段真实末帧的截图——这张截图会
    #       挂进下段参考组（2.5 首尾帧模式下就是 first_frame）。**尾帧是全景，下段开场就必然
    #       也是全景**，否则参考图对不上画面、挂了等于没挂。所以段缝景别不是"可以换"，
    #       而是"必须同档"。**同档 ≠ 整段同档**——约束只在「上段末帧 ↔ 下段首帧」这一对画面。
    # 判据：相邻两段「前段末镜**终点**景别 → 后段首镜**起点**景别」——
    #       ① 末镜做了收束动作（后拉/拉远/推近…至 {景别}）→ 要求**同档（落差 0）**，反向收紧 ≥1 级即报；
    #       ② 末镜未做收束 → 要求 **≤1 级**（给「过肩中景 → 全景揭示」这类自然放宽留口子），≥2 级即报；
    #       两侧镜行内都有过渡手段（遮挡/甩镜/运动模糊/叠化/黑场）时豁免。
    C18M_LADDER = ("大远景", "远景", "全景", "中全景", "中景", "中近景", "近景", "特写", "大特写")
    _c18m_size_defs = (
        ("大远景", r"大远景|大全景"), ("远景", r"远景"), ("全景", r"全景"),
        ("中全景", r"中全景"), ("中景", r"中景"), ("中近景", r"中近景"),
        ("近景", r"近景"), ("特写", r"特写"), ("大特写", r"大特写|极特写"),
    )
    # 镜行头里的景别（取最早出现者，避免"中全景"被判成"全景"、"中近景"被判成"近景"）
    _c18m_move_end = re.compile(
        r"(?:后拉|拉远|拉开|拉至|拉到|拉出|退至|退到|推至|推到|推近|摇至|移到|移向)"
        r"\s*(?:到|至)?\s*(大远景|大全景|远景|全景|中全景|中景|中近景|近景|特写|大特写|极特写)")
    _c18m_from = re.compile(r"从\s*(大远景|大全景|远景|全景|中全景|中景|中近景|近景|特写|大特写)")
    _c18m_bridge = re.compile(r"遮挡|黑场|黑屏|划变|甩镜|运动模糊|叠化|转场")

    def _c18m_head_size(line):
        head = _shot_head(line)
        if not head:
            return ""
        zone = head[:32]
        best, at = "", 10 ** 6
        for name, pat in _c18m_size_defs:
            m = re.search(pat, zone)
            if m and m.start() < at:
                best, at = name, m.start()
        return best

    def _c18m_norm(name):
        if not name:
            return ""
        if name in ("大全景",):
            return "大远景"
        if name in ("极特写",):
            return "大特写"
        return name

    def _c18m_tail_size(line):
        """末镜终点景别：行内声明了「后拉/拉远…至 {景别}」以该终点为准，否则取镜行头景别。"""
        hits = [m.group(1) for m in _c18m_move_end.finditer(line)]
        if hits:
            return _c18m_norm(hits[-1])
        return _c18m_norm(_c18m_head_size(line))

    def _c18m_open_size(line):
        """首镜起点景别：行内声明了「从 {景别}」以该起点为准，否则取镜行头景别。"""
        m = _c18m_from.search(line)
        if m:
            return _c18m_norm(m.group(1))
        return _c18m_norm(_c18m_head_size(line))

    for (_n1, _b1, _l1, _blk1, _p1, _s1, _d1), (_n2, _b2, _l2, _blk2, _p2, _s2, _d2) \
            in zip(seg_zw, seg_zw[1:]):
        if not _s1 or not _s2:
            continue
        _tail_line = _s1[-1][1]
        _head_line = _s2[0][1]
        _a, _b = _c18m_tail_size(_tail_line), _c18m_open_size(_head_line)
        if _a not in C18M_LADDER or _b not in C18M_LADDER:
            continue
        # 跨场景换场（@SCN- 不同）天然允许景别重立（如上场特写收尾 → 下场新空间全景开场）
        _sc1, _sc2 = _seg_scns(_l1), _seg_scns(_l2)
        if _sc1 and _sc2 and _sc1 != _sc2:
            continue
        # 末镜是否写了"明确落档"的收束动作（后拉/拉远/推近…至 {景别}）；2.0 无首尾帧模式且未做落档收束时不强锁同景别
        # ★审计补丁P1 修：D锁②「切景别 + 换机位硬切」模式下，段缝景别差是**设计要求**而不是跳针，
        #   此时 C18m 的「尾帧咬合」前提不成立（不截尾帧、不留收势窗）。
        if any(w in _tail_line for w in ("硬切", "切景别", "换机位")):
            continue
        _settled = bool(_c18m_move_end.search(_tail_line))
        if not _settled and model == "2.0":
            continue
        _gap = abs(C18M_LADDER.index(_a) - C18M_LADDER.index(_b))
        _limit = 0 if _settled else 1
        if _gap <= _limit:
            continue
        if _c18m_bridge.search(_tail_line) or _c18m_bridge.search(_head_line):
            continue
        _why = (f"末镜做了收束（尾帧落档「{_a}」），下段首镜必须同档起手"
                if _settled else "段缝默认同档（0 级），最多容忍 1 级相邻档")
        warns.append(
            f"C18m 段缝景别落差 {_gap} 级（{_n1}→{_n2}：末镜终点「{_a}」→ 首镜起点「{_b}」）——"
            f"尾帧截图就是下一段的首帧参考图，画面必须逐档咬合：{_why}。"
            "否则参考图对不上画面，观众读作跳切——尤其「末镜拉宽收束后，首镜又反向大幅收紧」"
            "（如全景 → 中景）。改法：① 首镜改为与末镜同档（全景收束 → 全景起手）；"
            "② 确为刻意的景别跳切（爆点/转场）时，在末镜或首镜行内写出可见的过渡手段"
            "（遮挡 / 甩镜 / 运动模糊 / 叠化 / 黑场）；③ 下段段内随后怎么推进都可以——"
            "约束只在首帧那一格。"
            "（segment-splicing.md §四·补 段缝景别承接律）")

    # C18 首镜锚定·景别一致·姿态延续·视线指派（model-adapters §5.0.2）
    # 病根全部来自「重生70」EP01 段1 实拍废镜，四判据见模块 docstring。
    # C18n 人物特写占比（2026-10-13 新增 · 体检修复 · short-drama-camera-system.md §一·4）
    # 病根：规则写了「特写比例区间 25%~40%（仅限人物特写，物件特写不计入）」+ 五类必给特写
    #       场景清单，但全脚本此前**零占比断言** → 硬指标无兜底。实测某项目 72 镜人物特写
    #       仅 19.4%（低于 25% 下限）而机检 PASSED 零告警。
    # 口径（2026-10-13 裁定）：人物特写 = 人物面部/眼睛/身体局部（手、拳、肩背…）→ 计入；
    #       物件特写 = 道具/器物/环境物件（榜文/旗面/街灯/马具…）→ 不计入。
    # 判据（防误报收窄）：镜行头景别命中「特写/大特写」，且镜行内有人物锚点（@人名 / @CHR-）
    #       或人体部位词 → 计为人物特写；两者皆无 → 判物件特写，剔除。镜数 <6 不判。
    _cu_lines = []
    for _seg in seg_zw:
        _cu_lines.extend(_seg[5])
    if len(_cu_lines) >= 6:
        _cu_n = 0
        for _ln_i, _l in _cu_lines:
            _hd = _shot_head(_l)
            if not (_hd and re.search(r"特写", _hd[:32])):
                continue
            if CU_PERSON_ANCHOR_RE.search(_l) or CU_BODY_PART_RE.search(_l):
                _cu_n += 1
        _cu_ratio = _cu_n / len(_cu_lines)
        _cu_min_eff = 0.20 if len(_cu_lines) > 12 else CU_RATIO_MIN
        _cu_max_eff = 0.45 if len(_cu_lines) > 12 else CU_RATIO_MAX
        if _cu_ratio < _cu_min_eff or _cu_ratio > _cu_max_eff:
            _dir = ("低于下限——该给的特写没给，情绪落不了地" if _cu_ratio < CU_RATIO_MIN
                    else "高于上限——特写滥用，人脸廉价化、节奏碎")
            warns.append(
                f"C18n 人物特写占比 {_cu_n}/{len(_cu_lines)} = {_cu_ratio:.1%}（{_dir}）——"
                f"区间 {CU_RATIO_MIN:.0%}~{CU_RATIO_MAX:.0%}；五类必给特写场景自查："
                "情绪拐点 / 关键道具（物件特写不计入配额）/ 眼神记忆点 / 台词重音 / 反应镜头"
                "（short-drama-camera-system.md §一·4 特写使用铁律与场景清单）。"
                "口径：**含人体局部肢体（手/拳/肩背）**，**仅纯物件特写不计入**。")

    # C18p 景别占比越界（2026-10-16 新增 · camera-system §一「景别占比预算表」）
    # ★ 编号说明：本包 C18o 已用于「时段光影基准在段」（2026-10-15），本码取 C18p。
    # 病根（粉丝「森林」2026-10-16 反馈 · 核验属实）：景别维度此前**只有特写一个区间**（C18n），
    #   大远景/远景/全景/中全景/中景/中近景/近景**全无占比预算** → 整段景别分布全凭手感，零兜底。
    # 口径：① 六组归并（远/全/中/中近/近/特）；② **镜数 <10 不判**——占比预算在小样本上无统计意义
    #   （8 镜时 5% 下限只合 0.4 镜，会把合规稿误判越界；这是与 C18n「<6 不判」口径的差别所在）；
    #   ③ 文戏「特」档交 C18n 独管（防双报）；④ 打戏档需 ≥3 个打斗词命中，否则按文戏档判（宁松勿误报）；
    #   ⑤ **期望镜数 <1 的档跳过**（下限 × 总镜数 <1 → 该档在数学上无法达标，属样本量问题而非缺陷）；
    #   ⑥ **偏差 <5 个百分点不报**（防噪声；误报比漏检更伤）。
    _sb_lines = []
    for _seg18p in seg_zw:
        _sb_lines.extend(_seg18p[5])
    if len(_sb_lines) >= 10:
        _sb_hits, _sb_total, _sb_txt = {}, 0, []
        for _ln18p, _l18p in _sb_lines:
            _hd18p = _shot_head(_l18p)
            if not _hd18p:
                continue
            _sb_total += 1
            _sb_txt.append(_l18p)
            for _g18p, _gr18p in SHOT_SIZE_GROUPS:
                if re.search(_gr18p, _hd18p[:32]):
                    _sb_hits[_g18p] = _sb_hits.get(_g18p, 0) + 1
                    break
        if _sb_total >= 10:
            # ★审计补丁P1 修：段落类型识别长期失效 → 文戏被当打戏档套用「远/全档下限」，误报越界。
            #   补一条保守判据：段内≥3 句画内台词 → 判文戏，不套打戏档。
            _dlg18p = sum(1 for _x18p in _sb_txt if "台词：【" in _x18p)
            _is_cbt = len(COMBAT_SEG_RE.findall("".join(_sb_txt))) >= 3 and _dlg18p < 3
            _bad18p = []
            for _g18p, _gr18p in SHOT_SIZE_GROUPS:
                _lo18p, _hi18p = (SHOT_BUDGET[_g18p][2], SHOT_BUDGET[_g18p][3]) if _is_cbt \
                    else (SHOT_BUDGET[_g18p][0], SHOT_BUDGET[_g18p][1])
                if _lo18p is None:
                    continue
                if _lo18p * _sb_total < 1:      # ⑤ 期望镜数 <1 → 样本量问题，不判
                    continue
                _r18p = _sb_hits.get(_g18p, 0) / _sb_total
                if _r18p < _lo18p:
                    if _lo18p - _r18p < 0.05:   # ⑥ 偏差 <5pp 不报
                        continue
                elif _r18p > _hi18p:
                    if _r18p - _hi18p < 0.05:
                        continue
                else:
                    continue
                _bad18p.append(_g18p + "档 " + f"{_r18p:.0%}" +
                               "（区间 " + f"{_lo18p:.0%}~{_hi18p:.0%}" + "）")
            if _bad18p:
                warns.append(
                    "C18p 景别占比越界（" + ("打戏" if _is_cbt else "文戏") + "档 · 共 "
                    + str(_sb_total) + " 镜）：" + "、".join(_bad18p)
                    + "——权威 short-drama-camera-system.md §一「景别占比预算表」"
                      "（起步基准·推演值，可按题材校准；窄幅变体须显式声明理由）。"
                      "低于下限＝该给的镜头没给；高于上限＝该档滥用（如近景堆满＝情绪钝化）。"
                      "⚠️ 本码与 C18n **分维度独立**：C18n 管特写（景别维度专档），本码管其余五档。")

    # C32 画面段最低三要素（2026-10-16 新增 · 治「画面提示词没有背景描述」）
    # ★ 编号说明：本包 C30 已用于「外挂指纹与跨阶段交接探针」（2026-10-14），本码取 C32。
    # 病根（粉丝「森林」2026-10-16 反馈 · 核验属实）：shot-economy-and-acting.md §九 早写了
    #   「画面描述必须包含：人物位置/姿态、光线方向、背景元素、关键细节」，但**全脚本零断言**
    #   → 执行者只写人物动作、背景全空；模型只好自行补背景 → **每镜背景不一致 = 跨镜穿帮**。
    # 判据：镜行「画面段」（`台词：` 之前的部分）须同时含 ② 背景元素 ③ 光线方向
    #   （① 人物位置/姿态由 C18f 景别承载 + C17 摆位必入画管，本码不重复）。
    # 豁免：① 纯空镜（画面段明写「无人物」）② 微距/大特写（只要求材质或光线其一）
    #   ③ 模板骨架行/占位符行。**不设镜数下限**——"画面段缺背景"是逐镜缺陷，
    #   一镜到底的单镜段同样适用（与 C18n/C18p 的"分布类判据需大样本"不同）。
    _c32_lines = []
    for _seg32 in seg_zw:
        _c32_lines.extend(_seg32[5])
    if _c32_lines:
        # ★ ③ 光线方向 的**继承口径**（2026-10-16 修正 · 与 model-adapters §5.0.5b「光影单一基准」对齐）：
        #   段首【场景资产】已立「时段光影」基准时，镜行**只写增量**——若仍逐镜强求光线方向，与该
        #   教义互锁夹杀（照 §5.0.5b 写＝被 C32 逐镜报缺光线；照 C32 写＝违背"只写增量"），
        #   执行者无合规写法。故：**段级有光影基准 → ③ 由基准继承，逐镜只判 ② 背景元素**；
        #   段级无基准 → 才逐镜要求 ②③ 齐备（与原行为一致）。
        #   段级基准判定与 C18o 同正则、同保守口径（段内非镜行文本出现任一处光影信号即算已立）。
        _c32_bad = []
        for _seg32 in seg_zw:
            _hdr32 = "\n".join(_lx for _lx in _seg32[2] if not TIME_RE.search(_lx))
            _base32 = bool(_LIGHT_SIG.search(_hdr32))
            for _ln32, _l32 in _seg32[5]:
                _hd32 = _shot_head(_l32)
                if not _hd32:
                    continue
                _pic32 = _l32.split("台词：")[0] if "台词：" in _l32 else _l32
                if "无人物" in _pic32 or "纯空镜" in _pic32:
                    continue
                if any(_ph in _l32 for _ph in C32_PLACEHOLDER):
                    continue
                _has_bg32 = bool(BG_ELEM_RE.search(_pic32))
                _has_lt32 = bool(LIGHT_DIR_RE.search(_pic32)) or _base32
                if re.search(r"微距|大特写|极特写|紧特写", _hd32[:32]):
                    if not (_has_bg32 or _has_lt32):
                        _c32_bad.append(_ln32)
                elif not (_has_bg32 and _has_lt32):
                    _c32_bad.append(_ln32)
        if _c32_bad:
            warns.append(
                "C32 画面段缺背景/光线（" + str(len(_c32_bad)) + " 镜：第 "
                + "、".join(str(_n32) for _n32 in _c32_bad[:6]) + " 行）——"
                "shot-economy-and-acting.md §九：画面段须含 ① 人物位置/姿态 ② 背景元素"
                "（前景/背景各 ≥1 处**场景真实存在**的物件或环境行为）③ 光线方向。"
                "**③ 由段首【场景资产】「时段光影」基准继承**（model-adapters §5.0.5b：镜行只写增量）"
                "——段内未立基准时才需逐镜写光线方向。"
                "只写人物动作＝主体贴白墙，模型会自补背景 → **每镜背景不一致（跨镜穿帮）**。"
                "豁免：纯空镜（写明「无人物」）/ 微距大特写（材质或光线二者其一即可）。")

    shot_lines = [(ln_i, l) for ln_i, l in enumerate(lines_all, 1) if TIME_RE.search(l)]

    # ---- C7b 镜行解析一致性元检查（2026-10-11 新增 · 防「检查器静默失效 → 假 PASS」）----
    # 病根：镜行头解析此前硬依赖半角 `[镜头N]`，解析为空时下游判据全部以 `if h and …` 跳过，
    # 脚本仍打印 PASSED——**检查器没通电却报绿灯**。本条把"解析没跑起来"本身变成可报错误：
    # 时间轴行存在但无一能解析出镜行头 → 全部镜级判据未生效，此前的 PASS 不可信。
    _n_timeline = len(shot_lines)
    _n_headok = sum(1 for _ln, _l in shot_lines if _shot_head(_l).strip())
    if _n_timeline >= 2 and _n_headok == 0:
        issues.append(
            f"C7b 镜行解析失效：{_n_timeline} 条时间轴行无一能解析出镜行头"
            "（应为 `[镜头N] 景别 · 视角 · 运镜。`）——镜级判据（C18g~l 运镜门 / C13 镜长节奏 / "
            "C11b 末镜定格 / C2 单镜时长）**全部未生效，本次 PASS 不可信**。"
            "请按七段式补镜行头（镜号用 `[镜头N]`，全角 `【镜头N】` 亦可）")
    elif _n_timeline >= 4 and _n_headok < _n_timeline * 0.6:
        warns.append(
            f"C7b 镜行解析率偏低：{_n_timeline} 条时间轴行仅 {_n_headok} 条解析出镜行头"
            "——部分镜级判据可能未生效。核对是否每条镜行都带镜号与「景别 · 视角 · 运镜」三要素"
            "（说明性时间轴行不计）")

    # ---- C7c 站位人物账解析元检查（2026-10-11 新增 · 与 C7b 同族 · 防「检查器静默失效 → 假 PASS」）----
    # 病根：站位人物提取硬依赖 `@人名（…）`；实跑稿写成 `A（…）`（漏 `@`）时解析为空，
    #       于是 C17 摆位必入画 / C17b 关系镜 / C17c 背景锚点 / C17d 跨段站位漂移 /
    #       C19c 首镜主体优先 **五条判据整体静默失效**，脚本照常打印 PASSED。
    #       （2026-10-11 用户实稿复核实测：两份「修表铺」稿站位声明均无 `@`。）
    # 本条与 _zw_people_loose 兜底配套：能兜住就 WARN 提示补 `@`，兜不住直接 FAIL——绝不静默放行。
    for _seg_name, _seg_base, _lines, _zw_block, _zw_people, _shots, _dlgs in seg_zw:
        if not _zw_block or "（" not in _zw_block:
            continue
        if ZW_PERSON_RE.findall(_zw_block):
            continue
        if _zw_people:
            warns.append(
                f"C7c [{_seg_name}] 站位声明未按 `@人名（…）` 规范格式书写"
                f"（本次已宽松兜底解析出：{'、'.join(_zw_people)}）——"
                "漏 `@` 会让 C17d 跨段站位漂移等人物账判据的稳定性下降。"
                "请统一写成 `@A（画面右 · 柜台后 · 朝左 · 立 · 身后是木柜）、@B（画面左 · …）`")
        else:
            issues.append(
                f"C7c [{_seg_name}] 站位人物账解析失效：站位声明里一个人名都解析不出"
                "（应为 `@人名（画面位置 · …）`）——C17 摆位必入画 / C17b 关系镜 / "
                "C17c 背景锚点 / C17d 跨段站位漂移 / C19c 首镜主体优先 **全部未生效，"
                "本次 PASS 不可信**。请按 `@A（画面右 · 柜台后 · 朝左 · 立 · 身后是木柜）` 补写")

    for _seg_name, _seg_base, _lines, _zw_block, _zw_people, _shots, _dlgs in seg_zw:
        _seg_blob = "".join(l for _n, l in _shots)
        # C17b 长对白段关系镜（逐段判 · 治「两人各自念稿」）：
        # 含台词镜 ≥6 的长对白段、摆位 ≥2 人，却全程单人正拍轮切——既无过肩反打、也无同框关系镜。
        # 观众读不出「在对谁说话」，关系戏塌成两段独白。关系镜＝过肩反打 或 两人同框，满足其一即过。
        # 豁免三类（此类场景本就不该有过肩）：单人对镜独白 / 电话·远程对话 / 一方已离场。
        if len(_zw_people) >= 2 and len(_dlgs) >= 6 and not re.search(
                r"电话|通话|听筒|视频通话|对讲机", _seg_blob):
            _has_ots = "过肩" in _seg_blob
            _two_shot = any(sum(1 for p in _zw_people if p in l) >= 2 for _n, l in _shots)
            if not _has_ots and not _two_shot:
                warns.append(
                    f"C17b [{_seg_name}] 长对白段关系镜缺失（含台词镜 {len(_dlgs)} 个 / "
                    f"摆位 {len(_zw_people)} 人）：全段既无过肩反打、也无同框关系镜——"
                    "长对白全程单人正拍轮切，观众读不出『在对谁说话』，关系戏会塌成两段独白。"
                    "段内至少安排 1 个过肩双人反打；双侧摆位 ≥2 人时至少 1 镜两人同框（满足其一即可）。"
                    "豁免：对镜独白 / 电话·远程对话 / 一方已离场")
        # C18a 段首镜人物锚（逐段）：首镜无站位人名且未声明「空镜」→ 模型渲染出空场景
        if _shots and _zw_people:
            _first = _shots[0][1]
            if "空镜" not in _first and not any(p in _first for p in _zw_people):
                warns.append(f"C18a [{_seg_name}] 第{_shots[0][0]}行 段首镜无人物锚："
                             "首镜既未带站位人物名、也未声明「空镜」——首镜无锚，"
                             "模型会渲染出空场景（实测出『只有一张床』）。"
                             "首镜写明主体归属（谁的手/谁的身体局部）或改为带站位人物的中近景"
                             "（model-adapters §5.0.2）")
        # C18b 姿态回退（逐段）：撑起/坐起/起身之后再出现躺/卧/蜷且无跌回交代 → 状态回退
        _propup = False
        for ln_i, l in _shots:
            _pic_l = l.split("台词：")[0]
            if _propup and LIE_RE.search(_pic_l) \
                    and not any(w in _pic_l for w in LIEBACK_EXEMPT):
                warns.append(f"C18b [{_seg_name}] 第{ln_i}行 姿态回退：前镜已撑起/坐起/起身，"
                             "本镜又躺/卧/蜷且无「跌回/躺回」交代——状态回退必穿帮；"
                             "后续镜写「保持撑坐/已坐起」，确需倒下要写明动作过程（model-adapters §5.0.2）")
            if PROPUP_RE.search(_pic_l):
                _propup = True
    # C18c 视线黏道具：说话镜把玩/举向道具却未指派视线 → 模型默认看道具不看人
    for ln_i, line, di in _dlg:
        si = line.find("声音：")
        pic = line[:si] if 0 <= si < di else line[:di]
        if (IDLE_PROP_RE.search(pic) or LIFT_TOWARD_RE.search(pic)) \
                and not GAZE_ANCHOR_RE.search(pic):
            warns.append(f"C18c 第{ln_i}行 视线指派缺失：说话同时把玩/举起道具，却未写目光/视线归属——"
                         "模型默认视线黏在道具上，说话不看人（实测：举玉宣判整段盯着玉）。"
                         "补「目光落在XX脸上/视线不落在道具上」（model-adapters §5.0.2）")
    # C18d 景别冲突：特写承载空间级事件 → 模型只好丢人物保空间
    for ln_i, l in shot_lines:
        si = l.find("声音：")
        pic = l[:si] if si >= 0 else l
        if CU_SHOT_RE.search(pic) and SPACE_EVENT_RE.search(pic):
            warns.append(f"C18d 第{ln_i}行 景别冲突：特写镜头承载空间级事件（房顶/屋子/门口/全景…）——"
                         "特写装不下全屋信息，模型只能丢人物保空间（实测出空床）。"
                         "空间事件改中景以上承载，或近景只保留单一局部主体（model-adapters §5.0.2）")
    # C18e 反光道具光效（拉片反馈；按 §5.0.4 放行正向材质描写）：
    # 镜行出现玉佩/银镯/镜面等反光道具，而既无镜行正向材质描写（哑光/实心/石质原色）、
    # 【强制禁止项】也未声明光效负面 → 模型渲染成自发光半透明魔法道具（实测）
    if GLOW_PROP_RE.search("".join(l for _, l in shot_lines)):
        ban_m = re.search(r"【强制禁止项】[\s\S]*", text)
        neg_declared = bool(ban_m and "发光" in ban_m.group(0))
        pos_declared = bool(re.search(r"哑光|实心|石质|原色|光斑", "".join(l for _, l in shot_lines)))
        if not (neg_declared or pos_declared):
            warns.append("C18e 反光道具光效未声明：镜行出现玉佩/银镯/镜面类反光道具，但既无正向材质描写"
                         "（实心石质/哑光质感，§5.0.4 首选）也未在【强制禁止项】加光效负面声明——"
                         "实测会被渲染成自发光半透明魔法道具；镜行写明材质正描写 + 主光源在关键镜行复述（model-adapters §5.0.3/§5.0.4）")

    # C19 禁令失效三改法（model-adapters §5.0.4）：被禁概念词根污染 / 光路触发器 / 首镜主体优先
    for ln_i, l in shot_lines:
        si = l.find("声音：")
        pic = l[:si] if si >= 0 else l
        neg_hits = BARE_NEG_RE.findall(pic)
        if neg_hits:
            warns.append(f"C19a 第{ln_i}行 裸禁令词污染：镜行内出现「{'、'.join(neg_hits)}」——"
                         "视频模型对否定不敏感、对词根敏感，被禁概念的词根本身会被当画面词渲染"
                         "（实测三条否定式禁令全部被无视）。删掉否定式写法，在镜行内改写为正向"
                         "材质/肌肉/光路描述：道具→「深青色实心哑光石质，玉面呈青玉原色」"
                         "（零光效描写，禁光斑/受光/照射类从句，见 C20d），"
                         "表情→「双唇抿紧、嘴角向下压、下颌绷紧」，"
                         "首帧→「画面主体：<人名>…」单主体开头（禁「X 与 Y 同框」并列主体写法，见 C20a）")
        if LIGHTPATH_RE.search(pic) and GLOW_PROP_RE.search(pic):
            warns.append(f"C19b 第{ln_i}行 光路触发器：反光道具被「举向/对着/冲向灯或光」——"
                         "道具正对光源会诱发模型渲染透光自发光（实测玉佩被画成灯泡）。"
                         "道具不与光源共现：动作上远离灯火，只写材质本色"
                         "（青玉原色/哑光金属本色），不做任何光效描写（见 C20d）")
        if GLOW_PROP_RE.search(pic) and FLAME_MAP_RE.search(pic):
            warns.append(f"C19d 第{ln_i}行 具象光源映射污染：反光道具镜行写「映出/倒映火苗」——"
                         "模型不理解「反射」，会把「映出+光源名词」读成光源出现在道具上"
                         "（玉面画出小火苗/整体泛光）。反光道具零光效描写：删掉全部"
                         "光斑/受光/照射类从句，只写材质本色（如「玉面呈青玉原色」），"
                         "且动作上不靠近光源（model-adapters §5.0.4 / C20d）")
    # C19c 首镜主体优先（逐段）：每段镜1第一个分句须含人物名/身体局部/「画面主体」，
    #       环境前置词诱导空场景开场。
    #       ⚠️2026-10-14 修复（代码体检）：旧实现用 `"[镜头1]" in l` **硬匹配半角镜号**——
    #         而 SHOT_TAG_RE 早已放宽支持全角 `【镜头1】`/无括号 `镜头1`（见 L271 注）。全角稿
    #         下 first_shot 恒为 None → **C19c 整条静默跳过**（放宽镜号时漏改的孤立点）。
    #         → 改用 SHOT_TAG_RE 提取镜号数字，判 `== 1`。无镜号标记的行按**时间码顺序**兜底取首个。
    for _seg_name, _seg_base, _lines, _zw_block, _zw_people, _shots, _dlgs in seg_zw:
        def _shot_no(_l):
            _m = SHOT_TAG_RE.search(_l)
            if not _m:
                return None
            _d = re.search(r"\d+", _m.group(0))
            return int(_d.group(0)) if _d else None
        first_shot = next((l for _n, l in _shots if _shot_no(l) == 1), None)
        if first_shot is None and _shots:
            # 无镜号标记（或镜号非从 1 起）→ 兜底取本段首条镜行
            first_shot = _shots[0][1]
        if first_shot:
            # 先剥掉声音/台词段，只在画面段取首个动作分句（防打戏稿用逗号分隔镜行头时 split("。") 直接跳到「声音：」）
            _fs_pic = first_shot.split("声音：")[0].split("台词：")[0]
            # ★审计补丁P1：镜行里显式写了「画面主体：」= 已经声明首镜主体，判据目标达成。
            #   旧实现会把 _shot_head 过捕获（一直吞到「画面主体：@周砚 站在…」），导致
            #   _fs_after 从人名之后开始、首分句变成「右手扶住雕花立柱」→ 对**合规稿全体误报**
            #   （实测 4 段稿连报 3 条：段1/段3/段4 全中，而三段首镜都写了「画面主体：@人名」）。
            if "画面主体" in _fs_pic:
                continue
            _fs_hd = _shot_head(_fs_pic)
            if _fs_hd and _fs_hd in _fs_pic:
                _fs_after = _fs_pic[_fs_pic.find(_fs_hd) + len(_fs_hd):].lstrip(" 。，,·	")
            else:
                _fs_after = _fs_pic.split("。", 1)[-1] if "。" in _fs_pic else _fs_pic
            first_clause = re.split(r"[，。；]", _fs_after or _fs_pic, maxsplit=1)[0]
            body_local = re.search(r"的手|的脚|的脸|的手背|的肩膀|的侧脸|的眼|画面主体", first_clause)
            # ★群体主语识别（2026-10-12 修复）：打戏/群戏开场惯用「两人同时向前抢步」「双方对峙」
            #   这类**不含具体人名**的群体主语——它本身就在写人物，不是环境前置。
            #   原判据只认 `她/他/其` 与站位人名，导致官方示例 历史示例稿 连报 2 条假告警。
            crowd_subject = re.search(
                r"^[^，。；]{0,8}(?:两人|二人|双方|对阵|对峙|缠斗|交手|对打|互殴|搏斗|群演|人群|众人|士兵们|双方同时|两人同时)",
                first_clause)
            people_in_clause = any(p in first_clause for p in (_zw_people or [])) \
                or bool(re.search(r"她|他|其", first_clause[:4])) \
                or bool(crowd_subject)
            if not (people_in_clause or body_local):
                warns.append(f"C19c [{_seg_name}] 首镜主体优先：镜1第一个分句以环境开头、"
                             "人物名/身体局部出现在其后——环境前置词会诱导模型渲染空场景开场"
                             "（实测两轮出空房间大全景）。改为「画面主体：<人名>…」或以人名/"
                             "身体局部开头（model-adapters §5.0.4）")

    # C19e 禁止项栏目纪律（model-adapters §5.0.4）：
    # ① 正向执行指令混入【强制禁止项】→ 两头不生效（实测等同废纸）；
    # ② 禁止项里写否定式禁令（不发光/面无笑意）→ 被禁词根反被当画面词渲染，同样失效。
    # ⚠️2026-10-14 修复（代码体检）：旧实现 `[\s\S]*` **贪婪吞到全文末尾**——禁止项之后的
    #   全部镜行（含合法的正向描写）都被算进 ban_blob → C19e 误报（把镜行正描写当成"禁止项错位"）。
    #   七段式里【强制禁止项】是**栏位之一**，其边界 = 下一个 `【` 栏位标记 / 围栏 / 文末。
    #   → 改为「非贪婪 + 截止于下一个【栏位标记」，多段稿件逐段取。
    _ban_blocks = []
    for _bm in re.finditer(r"【强制禁止项】([\s\S]*?)(?=\n【|\Z|```)", text):
        _ban_blocks.append(_bm.group(1))
    if not _ban_blocks:
        # 兜底：允许禁止项位于文末、无后续【标记（用非贪婪到文末）
        _bm2 = re.search(r"【强制禁止项】([\s\S]*)", text)
        if _bm2:
            _ban_blocks.append(_bm2.group(1))
    for ban_blob in _ban_blocks:
        for part in re.split(r"[；;]", ban_blob):
            p = part.strip()
            if not p or any(n in p for n in C19E_NEG_WORDS):
                continue
            hit = C19E_POS_RE.search(p)
            if hit:
                warns.append(f"C19e 禁止项栏目错位：正向执行指令「{hit.group(0)}」写进了【强制禁止项】——"
                             "该栏被模型当规避清单读，正向要求放进去既不当禁令也不当指令（实测等同废纸）。"
                             "正向指令回落镜行/【画幅风格】/【站位声明】，禁止项只写负面清单"
                             "（变形/穿模/现代元素/字幕水印/音频约束；model-adapters §5.0.4 栏目纪律）")
                break
        neg_hits2 = sorted(set(BARE_NEG_RE.findall(ban_blob)))
        if neg_hits2:
            warns.append(f"C19e 禁止项裸禁令词：「{'、'.join(neg_hits2)}」——"
                         "否定式禁令在禁止项里同样失效（模型对否定不敏感、对词根敏感，"
                         "被禁概念的词根会被当画面词渲染，实测玉佩仍全片自发光）。"
                         "删掉该声明，改在镜行写正向描写：道具→「哑光金属本色/实心石质+受光处小片光斑」，"
                         "表情→「双唇抿紧、嘴角向下压」（model-adapters §5.0.4）")

    # C20 首镜单主体锚定 + 抽象形容（model-adapters §5.0.2/§5.0.4）：
    # 病灶实测：「重生70」EP01 段1 镜1 出片两张脸——镜行「首帧即这只手与她的脸同框」。
    for ln_i, l in shot_lines:
        si = l.find("声音：")
        pic = l[:si] if si >= 0 else l
        ms = MULTI_SUBJ_RE.search(pic)
        if ms:
            warns.append(f"C20a 第{ln_i}行 并列主体/同框句式：「{ms.group(0)}」——"
                         "模型把「X 与 Y 同框」读成画面里有两个主体（实测同一主体的手与脸被渲染成"
                         "两个头/两张脸）。首镜锚定句只由**一个具名主体**统摄（「画面主体：林清月…」），"
                         "身体部位一律以「她的/其+部位」从属出现；确有两个人物时由【站位声明】"
                         "具名双主体承载，镜行内不写「同框」（model-adapters §5.0.2）")
        dm = DANGLING_DEIXIS_RE.search(pic)
        if dm and not DEIXIS_OWNED_RE.search(pic[:dm.start()]):
            warns.append(f"C20b 第{ln_i}行 悬空指示代词：「{dm.group(0)}」无归属定语——"
                         "指代词没有先行词，模型会自行补全一个主体（实拍多补出一个头/一张脸）。"
                         "改写为「她的一只手」这类带归属写法（model-adapters §5.0.2）")
        shape_hits = sorted(set(ABSTRACT_SHAPE_RE.findall(pic)))
        if shape_hits:
            warns.append(f"C20c 第{ln_i}行 抽象修辞/比喻具象化污染：「{'、'.join(shape_hits)}」——"
                         "视频模型完全不理解文学比喻与虚词修辞，会把比喻词名词直接渲染成画面实体"
                         "（实测拉片：写「端坐如钟」房梁凭空掉下一口大铜钟；写「四道影子钉在殿砖上」地面多生出5个黑影假人）！"
                         "必须彻底删除比喻与修辞，只写纯物理可见动作（model-adapters §5.0.4）")
        # C20f 单人镜头点名画外角色名（实测拉片：写「看向陆沉 / 视线扫过沈青梧、裴岳」导致模型把被看者强行塞入画框甚至左右克隆出两个沈青梧分身！）
        _all_cast_names = [re.sub(r"^@?(?:CHR-)?", "", p) for _, _, _, _, _zwp, _, _ in seg_zw for p in (_zwp or [])]
        _all_cast_names = sorted(set(n for n in _all_cast_names if len(n) >= 2))
        _gaze_other = bool(re.search(r"(?:看向|望向|扫过|瞥向|盯住|盯着|凝视|直视|对视)[^。；]{0,18}?(?:@[A-Za-z\u4e00-\u9fff]|长老|师姐|师弟|师兄)", pic))
        if not _gaze_other and _all_cast_names:
            for _cn in _all_cast_names:
                if re.search(rf"(?:看向|望向|扫过|瞥向|盯住|盯着|凝视|直视|对视)[^。；]{{0,14}}{re.escape(_cn)}", pic):
                    _gaze_other = True
                    break
        if _gaze_other and re.search(r"特写|近景|中近景|中景", _shot_head(pic) or pic[:24]):
            warns.append(
                f"C20f 第{ln_i}行 视线点名画外他角污染：单人/局部镜头内写了「看向/扫过/对视+其他角色名」——"
                "视频模型看到角色名就会把对方强行塞进同一画框，甚至左右镜像克隆出双胞胎分身（实测拉片：写「视线依次扫过沈青梧、裴岳」导致中景里克隆出两个白衣沈青梧）！"
                "修法：单人镜头写「单人入画」，视线方向只写画框方位（如「目光平视画中前方高台 / 视线投向画右前」），绝不点名画外角色！"
            )
        # C20g 单镜多重视线切换过载（实测拉片：2~3秒内写「看向A一瞬，随即转回B」或「依次扫过A、B，最后落回C」导致眼神看镜头或人物分裂）
        if re.search(r"依次扫过|先看[^。；]{1,10}再|看向[^，。；]{1,10}(?:一瞬|片刻)[^。；]{0,6}(?:随即|又)?转回", pic):
            warns.append(
                f"C20g 第{ln_i}行 单镜多重视线切换过载：2~4秒短镜头内包含多次转头/扫视（「依次扫过 / 看向…随即转回」）——"
                "模型在短镜内无法完成多目标视线切换，会导致人物直勾勾看镜头或克隆分身！一镜只准有一个固定视线方向！"
            )
        # C20i 跨狭小窗口递物穿模 + 可开合道具（伞/扇）缺开合状态锁或单镜变形（2026-10-14 实测拉片：「把长柄伞递出车窗，伞尖悬在雨里」→ 模型直接在车窗上画出一把撑开的大伞穿模车门！）
        if re.search(r"(?:递出|伸出|探出|塞出|穿过)[^，。；]{0,6}(?:车窗|窗外|门缝|栏杆)", pic):
            warns.append(
                f"C20i 第{ln_i}行 跨窗口/狭缝递物穿模高危：镜行写了「递出/伸出车窗（或窗外/门缝）」——"
                "视频模型无法计算长柄伞/道具穿过狭小车窗的碰撞体积，会直接将道具（尤其是撑开的伞）穿模焊在车门玻璃上！"
                "修法（从剧本与分镜源头改因果链）：车内人只降下车窗露脸对视，车外人原本就已撑伞站定（或推开车门下车），严禁跨车窗递长物！"
            )
        if re.search(r"长柄伞|雨伞|油纸伞|黑伞|白伞|纸伞|把伞|撑伞|打伞", pic):
            if not re.search(r"已撑开|撑着|打着|收拢|合拢|收起握在|捆紧", pic):
                warns.append(
                    f"C20i 第{ln_i}行 可开合道具（伞）缺形态锁：镜行出现「伞」，却未写明是「已撑开遮在头顶」还是「收拢握在手中」——"
                    "雨景下模型默认把伞画成撑开态，若在车内/室内或递送中必严重穿模！必须前置锁死伞的开合状态，且不在单镜内做开合变形！"
                )
        # C20j 无动作因果链的「悬空局部词」与小说式废词（2026-10-14 实测拉片：「伞尖悬在雨里」「西装领口一丝不乱」「隔着雨看XX」）
        _bad_causal = re.findall(r"伞尖悬在|剑尖悬在|刀尖悬在|枪口悬在|一丝不乱|隔着雨看|隔着雾看|隔着玻璃看|隔着人群看", pic)
        if _bad_causal:
            warns.append(
                f"C20j 第{ln_i}行 缺动作因果链/小说废词污染：「{'、'.join(sorted(set(_bad_causal)))}」——"
                "写「伞尖悬在雨里」缺少「手握何处→道具何种状态→如何位移」的物理动作链，模型会让伞在半空乱伸乱开；"
                "写「一丝不乱 / 隔着雨看XX」属不可执行的小说废词与画外点名！请改为完整物理持握态与画框视线方向！"
            )
        # C20k 镜头收在手部/道具局部时禁排画内开口台词（实测拉片：写「镜头收在他按剑的右手与剑鞘上」同时排画内台词，模型找不到嘴会强行扭曲塞脸！）
        if re.search(r"收在[^。；]{0,12}(?:右手|左手|手背|手指|剑鞘|剑柄|刀柄)", pic):
            if "台词：【" in l and not re.search(r"画外音|OS|旁白|心声", l):
                warns.append(
                    f"C20k 第{ln_i}行 局部手部/道具镜头排画内台词冲突：画面已推进收在「手部/剑鞘局部」（嘴部不在画内），却排了画内开口台词——"
                    "视频模型为了给台词对口型，会强行把人脸扭曲塞进手部特写！修法：要么镜头停在人物半身/近景含脸，要么台词改标「画外音」或删台词！"
                )
        # C20l 单镜「爆发撞击 + 缓缓落定/收剑归鞘」时间悖论（实测拉片：3秒末镜扣1秒定格只剩2秒，同时塞「轰然撞上+爆开+烟尘缓缓落定+收剑归鞘+缓缓熄灭」6个阶段必糊成一团）
        if re.search(r"撞上|轰碎|炸开|爆开", pic) and re.search(r"缓缓落定|缓缓熄灭|收剑归鞘", pic):
            warns.append(
                f"C20l 第{ln_i}行 单镜快慢时间悖论：同一短镜头内既要「撞击爆开」又要「烟尘缓缓落定 / 收剑归鞘 / 缓缓熄灭」——"
                "2~3秒内无法同时演完剧烈爆炸与慢速收招落定，模型会把爆炸与收剑糊在同一帧！请拆分为两个镜头，或将本镜收束在爆炸余波与持剑站定！"
            )
        # C20m 镜行摄影机理论废话污染（实测：往镜行塞「焦平面全程死锁面部无漂移 / 毫米级构图补偿 / 呼吸式微动 / 画面线条笔直构图平整」会稀释动作权重并诱发怪异晃动）
        _cam_fluff = re.findall(r"焦平面全程死锁|毫米级构图补偿|呼吸式微动|画面线条笔直构图平整|柔和色块与微光", pic)
        if _cam_fluff:
            warns.append(
                f"C20m 第{ln_i}行 镜行摄影机说明书废话污染：「{'、'.join(sorted(set(_cam_fluff)))}」——"
                "视频模型听不懂摄影师理论术语，写进镜行会分散人物动作注意力甚至引发画面乱晃！镜行正文只准写人物与道具的纯物理动作！"
            )
        # C2d 2秒极短镜塞「身体位移/行礼 + 完整台词句子」过载（实测拉片：2秒镜写「向前迈步+抱拳躬身45度+抬头+念8字台词」导致人物卡死在半弯腰）
        _tm = re.match(r"\s*(\d{2}):(\d{2})-(\d{2}):(\d{2})", l)
        if _tm:
            _dur = (int(_tm.group(3))*60 + int(_tm.group(4))) - (int(_tm.group(1))*60 + int(_tm.group(2)))
            if _dur <= 2 and re.search(r"迈出一步|上前一步|出列|直起身|起身|转身|躬身|弯腰", pic):
                _dm = re.search(r"台词：【[^】]*?[：:][\x22\u201c]([^\x22\u201d]+)[\x22\u201d]", l)
                if _dm and len(_dm.group(1)) >= 5:
                    warns.append(
                        f"C2d 第{ln_i}行 2秒短镜「全身位移+台词」过载：本镜仅 {_dur} 秒，却同时包含全身位移/行礼动作与 {len(_dm.group(1))} 字台词——"
                        "2秒内模型无法完成「迈步/起身+行礼+念完句子」（实测人物直接卡在半弯腰动弹不得）！请将本镜时长扩至 ≥3 秒，或删掉位移动作只保留定姿说话！"
                    )
        if GLOW_PROP_RE.search(pic):
            lm = PROP_LIGHT_RE.search(pic)
            if lm:
                warns.append(f"C20d 第{ln_i}行 道具光效描写：「{lm.group(0)}」与反光道具共现——"
                             "道具与光/火产生描写关联就会被模型渲染成发光/点火"
                             "（实测「指甲盖大暖黄光斑」出片玉佩像打火机点了一簇火）。"
                             "反光道具零光效描写：删掉光斑/受光/照射类从句，"
                             "只写材质本色（玉面呈青玉原色/哑光金属本色）（model-adapters §5.0.3）")
            nm = LAMP_NEAR_RE.search(pic)
            if nm:
                warns.append(f"C20d 第{ln_i}行 道具贴近光源动作：「{nm.group(0)}」——"
                             "道具靠近灯火的动作本身就是点火触发器（实测「举到油灯旁」"
                             "出片玉佩上冒火苗）。动作改开：道具只把玩/随身佩戴，不与灯火同框共现")
    # C20h 群像站位朝向矛盾与「左1右2」偏沉镜像克隆拦截（实测拉片：主位在中后，台下写「左前沈青梧、右前裴岳、右后陆沉」左1女右2男 → 模型在中轴对称大殿里自动把左边唯一的女角复制成2个填补左后空位！）
    for _sn, _sb, _lines, _zwb, _zwp, _shs, _dls in seg_zw:
        if _zwb and "画面中后" in _zwb and ("面朝左主位" in _zwb or "面朝右主位" in _zwb):
            warns.append(
                f"C20h [{_sn}] 群像站位朝向矛盾：【站位声明】主位在「画面中后」，下属却写「面朝左主位 / 面朝右主位」——"
                "模型会按字面让左边人朝右、右边人朝左横向90度面对面互看，并触发左右镜像克隆出双份角色！"
                "修法：下属统一写「斜背对镜头面朝中后方高台」！"
            )
        if _zwb and "画面中后" in _zwb:
            _has_lf = "左前" in _zwb
            _has_lb = "左后" in _zwb
            _has_rf = "右前" in _zwb
            _has_rb = "右后" in _zwb
            if (_has_lf and not _has_lb and _has_rf and _has_rb) or (_has_lf and _has_lb and _has_rf and not _has_rb):
                warns.append(
                    f"C20h [{_sn}] 中轴对称群像「左1右2」偏沉站位触发克隆：【站位声明】在居中主位下使用了「左前1人 + 右前/右后2人」不对称站位——"
                    "在中轴对称大殿全景中，模型会自动把单人侧的角色（如左前唯一的女角沈青梧）复制出第2个分身填补空缺的左后位（实测拉片开头全景多出一个女性角色）！"
                    "修法：台下3人改为「从左至右单排三槽位：画面左、画面中前、画面右」，一人一槽左右均衡，绝不留单侧空缺槽！"
                )

    # ---- 运镜门 C18g~l（short-drama-camera-system.md §四 · 2026-10-10 新增）----
    # 病根：§四 把运镜约束写得极厚，但**零机检载体**——运镜词此前只出现在已下线专线的剥离词表里
    # （用来把运镜词从画面描述里扣掉），不参与校验。实测「一镜之内同时完成推拉摇移跟升降环绕
    # 变焦八种运镜」「毫无动机地疯狂甩动、无动机变焦」两份病灶稿 → 全部 PASSED。本组补上。
    _cam_heads = [(ln_i, _shot_head(l)) for ln_i, l in shot_lines]
    _cam_fam_by_shot = [(ln_i, _cam_families(h)) for ln_i, h in _cam_heads]
    # C18g 镜行未标注运镜（头三要素缺运镜 → 运镜留给模型自选）
    for ln_i, h in _cam_heads:
        if h and not _cam_families(h):
            warns.append(f"C18g 第{ln_i}行 镜行未标注运镜：镜行头「{h.strip()}」内无任何运镜词——"
                         "§四「每个镜头必须标注运镜方式」（固定/推/拉/摇/移/跟/升降/环绕/手持/定格…）。"
                         "运镜留空即交给模型自选，出片偏静止与套路化；常态用微运镜"
                         "（极缓慢推/极缓慢横移/呼吸感漂移）替代绝对静止"
                         "（short-drama-camera-system.md §四）")
    # C33 镜行未标注焦段（★审计补丁新增 · 补「库严模板松」缺口 · 编号续 C32 之后）
    # 病根：short-drama-camera-system.md §二 写死「每个镜头必须标注焦段」并给了景别→焦段逐级表，
    #   但总控 §5 的镜行范式长期只有「景别·角度·运镜」三项 → 照模板写必然漏焦段，
    #   模型只能自选镜头（实测「特写」被拍成 1:1 微距、「正脸大特写」裁掉半张脸）。
    for ln_i, h in _cam_heads:
        if h and not re.search(r"\d{2,3}\s*mm|微距|鱼眼|变焦", h):
            warns.append(f"C33 第{ln_i}行 镜行未标注焦段：镜行头「{h.strip()}」内无焦段——"
                         "§二「每个镜头必须标注焦段」，并给「景别→焦段逐级对照表」"
                         "（大景别 24~35mm / 中景 35~50mm / 中近景 85mm / 近景 85~100mm / 特写 85~200mm / 微距 1:1）。"
                         "焦段留空 = 把镜头选择权交给模型，出片焦段失控是「运镜乱」的第一成因"
                         "（short-drama-camera-system.md §二）")

    # C18h 一镜多主运镜（一个镜头塞多套运动，模型执行不了）
    for ln_i, fams in _cam_fam_by_shot:
        if len(fams) > CAM_MULTI_MAX:
            warns.append(f"C18h 第{ln_i}行 一镜多主运镜：单镜并列 {len(fams)} 种运镜 "
                         f"{sorted(fams)}（>上限 {CAM_MULTI_MAX}）——模型无法在一个时间轴上"
                         "同时执行多套运动，出片必乱或只留第一种。一镜一主运镜；"
                         "确需复合（如缓慢推 + 轻升）限两层且写明叙事理由"
                         "（§四 运镜变化铁律 / 高光时刻运镜专题）")
    # C18i 无动机运镜（FAIL · §四「烈度必须由情绪买单，禁止无理由晃动」）
    for ln_i, l in shot_lines:
        _hit = [w for w in CAM_MOTIVELESS if w in l]
        if _hit:
            issues.append(f"C18i 第{ln_i}行 无动机运镜：镜行出现 {sorted(set(_hit))}——"
                          "§四 手持三级烈度铁律「烈度必须由情绪买单，禁止无理由晃动」；"
                          "无叙事动机的晃动/甩动/乱切会把画面变成廉价手持。"
                          "删掉无动机运镜，改按情绪强度分档（微晃 4~6 分 / 晃动 6~8 分 / "
                          "剧烈晃动 ≥8 分，且仅限暴烈冲突·惊恐逃窜·精神失稳·灾难瞬间）")
    # C18j 固定镜头过量（全片占比 + 连排两判据）
    # 对话段豁免（2026-10-13 用户裁定「对话段全面豁免」）：**正反打的标准形态就是「固定机位 + 切」**——
    #   摄影机不动、靠切镜换嘴（粉丝稿实测全程固定，靠切换说话人）。若对话段也套
    #   「固定 ≤10% / 禁连排 3」，就会出现「为了让摄影机动起来而在正反打里乱加运镜」，
    #   反而破坏正反打的稳定感。故对话段 **豁免 C18j 两条判据**。
    _n_shots = len(_cam_heads)
    _fix_lns = [ln for ln, fams in _cam_fam_by_shot if fams == {"固定"}]
    _fix_lns_nd = [ln for ln in _fix_lns if not _in_dlg(ln)]
    _n_shots_nd = len([ln for ln, _f in _cam_fam_by_shot if not _in_dlg(ln)])
    # 2026-10-14 用户二次裁定：废除「15s运镜≤2」与「非对话段固定≤10%」双向死配额，动静随剧情自然发生；
    # 仅在打戏模式（_combat_on）执行 10%/连排3 严限，普通剧情段放宽至 >85% 全固定或连排 ≥5 镜才提醒防PPT死片。
    _c18j_ratio_cap = CAM_FIXED_RATIO_MAX if _combat_on(text, combat) else 0.85
    _c18j_run_cap = CAM_FIXED_RUN_MAX if _combat_on(text, combat) else 5
    if _n_shots_nd >= CAM_FIXED_MIN_SHOTS and _fix_lns_nd:
        _r = len(_fix_lns_nd) / _n_shots_nd
        if _r > _c18j_ratio_cap:
            warns.append(f"C18j 固定镜头过量：{len(_fix_lns_nd)}/{_n_shots_nd} 镜为纯固定"
                         f"（占比 {_r:.0%} > 上限 {_c18j_ratio_cap:.0%}）——§四 动静随剧情自然发生："
                         "对白交锋、情绪定格、道具展示可用固定；情绪推进、人物走位、空间揭示宜配"
                         "缓慢推拉（10~15cm 物理限位）/横移/摇跟，避免全片沦为纯静态PPT")
    _run = 0
    for ln_i, fams in _cam_fam_by_shot:
        if fams == {"固定"} and not _in_dlg(ln_i):
            _run += 1
            if _run >= _c18j_run_cap:
                warns.append(f"C18j 第{ln_i}行 连续 {_run} 镜固定——§四 连续过多固定镜头易致画面呆板，"
                             "建议在情绪递进或空间揭示镜加入缓慢推拉（10~15cm 物理限位）/横移/摇跟")
                _run = 0
        else:
            _run = 0
    # C18k 运镜单调（连排同运镜 + 段内覆盖不足；2026-10-14 修订：固定镜头不计入同运镜连排，非打戏不强凑4种运镜）
    _prev, _same = None, 0
    for ln_i, fams in _cam_fam_by_shot:
        _key = tuple(sorted(fams)) if fams else None
        if _key is not None and _key != ("固定",) and _key == _prev and not _in_dlg(ln_i):
            _same += 1
            if _same == CAM_SAME_RUN_MAX:
                warns.append(f"C18k 第{ln_i}行 连续 {_same} 镜同一运镜「{'/'.join(_key)}」——"
                             "§四 运镜变化铁律：相邻镜头动态运镜应产生变化，避免连续 3 镜完全相同运动"
                             "（唯一例外：手持剧烈晃动的爆发顶点短链）")
                _same = 0
        else:
            _same = 1 if (_key is not None and _key != ("固定",)) else 0
        _prev = _key
    _c18k_cover_min = CAM_COVER_MIN if _combat_on(text, combat) else 2
    for _seg_name, _seg_base, _lines, _zw_block, _zw_people, _shots, _dlgs in seg_zw:
        _fams = set()
        for _ln, _l in _shots:
            _fams |= _cam_families(_shot_head(_l))
        # 对话段豁免段内运镜覆盖不足（正反打天然以固定为主，见 C18j 豁免说明）
        if _in_dlg(_seg_base):
            continue
        if len(_shots) >= CAM_COVER_MIN_SHOTS and len(_fams) < _c18k_cover_min:
            warns.append(f"C18k [{_seg_name}] 段内运镜覆盖不足：{len(_shots)} 镜只用 "
                         f"{len(_fams)} 种运镜 {sorted(_fams)}（<{CAM_COVER_MIN} 种）——"
                         "§四：同一场戏内运镜方式至少覆盖 4 种，避免单一手法贯穿全场"
                         "（禁为凑多样性使用无叙事理由的运镜）")
    # C18l 重技法频率上限（§四 表）
    _cam_blob = "".join(h for _ln, h in _cam_heads)
    for _tech, _pat, _lim, _scope in CAM_HEAVY_LIMITS:
        if _scope == "whole":
            _c = len(re.findall(_pat, _cam_blob, re.I))
            if _c > _lim:
                warns.append(f"C18l 重技法名额超限：{_tech} 出现 {_c} 次 > 全片上限 {_lim}——"
                             "重技法用多了廉价化，只用于重锤瞬间（§四 重技法频率上限）")
        else:
            _segs = sum(1 for _s in seg_zw
                        if any(re.search(_pat, _shot_head(_l), re.I) for _ln, _l in _s[5]))
            if _segs > _lim:
                warns.append(f"C18l 重技法名额超限：{_tech} 覆盖 {_segs} 个段 > 上限 {_lim} 段——"
                             "§四 重技法频率上限（用多了廉价化，只用于重锤瞬间）")

    # C21 打戏激烈度硬护栏（combat-intensity-guardrails.md §二）
    # 触发门：只对打戏稿生效（--combat on/off/auto），文戏稿零误报是底线。
    if _combat_on(text, combat):
        _ranges = _combat_ranges(text)
        _total = _union_len([(s, e) for s, e, _, _ in _ranges])

        # C21a 连续区间无身体位移 → 站着发光，不是打斗
        _run = 0
        _a_done = False
        for s, _e, _ln, pic in _ranges:
            if COMBAT_MOVE_RE.search(pic):
                _run = 0
            else:
                _run += 1
                if _run >= COMBAT_SAME_RUN and not _a_done:
                    warns.append(f"C21a 自 {s}s 起连续 {_run} 个时间区间无身体位移——"
                                 "打戏每个区间攻守双方都必须发生位移（冲刺/滑退/翻滚/腾空/被击飞）；"
                                 "只有「站着 + 发光」= 模型把每段理解成了一张静态画"
                                 "（combat-intensity-guardrails.md §二·①）" + COMBAT_EGRESS)
                    _a_done = True

        # C21b 全片零实体接触 → 全程隔空对波
        _spans = [(s, e) for s, e, _, pic in _ranges if COMBAT_CONTACT_RE.search(pic)]
        if _ranges and not _spans:
            warns.append("C21b 全片无任何实体接触——打戏至少要有兵器交击/拳脚着肉/抓握/撞击；"
                         "全程「隔空对波」（双方站立不动、各放能量束在空中相撞）看着燃，"
                         "实则零接触零位移。仅允许用在①高潮大招释放瞬间（1~2s）"
                         "②短暂反制瞬间（≤0.5s 且紧接着必须贴身）"
                         "（combat-intensity-guardrails.md §二·①⑥）" + COMBAT_EGRESS)
        # C21c 贴身对招占比低于下限（粗估：含接触区间的并集时长）
        elif _total > 0:
            _close = _union_len(_spans)
            if _close / _total < COMBAT_CLOSE_RATIO:
                warns.append(f"C21c 贴身对招时长占比 {round(_close / _total * 100)}% < 33% 下限——"
                             f"全片 {round(_total, 1)}s 中仅 {round(_close, 1)}s 有实体接触。"
                             "15s 片贴身缠斗不得少于 5s、30s 片不得少于 10s，「隔空对波」不计入"
                             "（combat-intensity-guardrails.md §二·③）" + COMBAT_EGRESS)

        # C21d 连续区间机位签名完全相同 → 退化成"同一张画反复播"
        def _sig(pic):
            _s, _ang = COMBAT_SIZE_RE.search(pic), COMBAT_ANGLE_RE.search(pic)
            return (_s.group(0) if _s else "", _ang.group(0) if _ang else "")
        _sigs = [_sig(pic) for _, _, _, pic in _ranges]
        _run = 1
        _d_done = False
        for _i in range(1, len(_sigs)):
            if _sigs[_i] == _sigs[_i - 1] and _sigs[_i] != ("", ""):
                _run += 1
                if _run >= COMBAT_SAME_RUN and not _d_done:
                    warns.append(f"C21d 自 {_ranges[_i - _run + 1][0]}s 起连续 {_run} 个区间机位完全相同"
                                 f"（{_sigs[_i][0] or '未标景别'}·{_sigs[_i][1] or '未标角度'}）——"
                                 "相邻区间的机位或双方相对位置必须变化，否则退化成「同一张画反复播」"
                                 "（combat-intensity-guardrails.md §二·②）" + COMBAT_EGRESS)
                    _d_done = True
            else:
                _run = 1

        # ---------- C22 打戏节奏与渲染负载护栏（combat-rhythm-and-load-guardrails.md）----------
        # 补 C21 的方向性缺口：C21 全是下限型（不许躺平），C22 补上「上限型·不许过载」与节奏维度。
        if _ranges:
            # C22a 单镜独立动作单元超上限（★上限型）
            for _s, _e, _ln, pic in _ranges:
                _dur = _e - _s
                _lim = _iau_limit(_dur)
                _n = _combat_iau(pic)
                if _n > _lim:
                    warns.append(
                        f"C22a {_s}-{_e}s（{round(_dur, 1)}s）独立动作单元 {_n} 个 > 上限 {_lim}"
                        f"（按 combat-rhythm-and-load-guardrails.md §1.2）——"
                        f"视频模型在该时长内可靠渲染约 2~3 个动作，超出部分会被丢弃、"
                        f"只留第一个匀速播完，出片必现『贴脸乱动 + 后半段动作消失』= 像小孩打架。"
                        f"解法：拆镜或删动作（铁律0 第1步 一镜一主任务）" + COMBAT_EGRESS)

            # C22b 一镜多任务（动作类型 ≥3 类）
            for _s, _e, _ln, pic in _ranges:
                _tt = _combat_tactic_types(pic)
                if len(_tt) >= 3:
                    warns.append(
                        f"C22b {_s}-{_e}s 一镜覆盖 {len(_tt)} 类动作技术（{'/'.join(_tt)}）≥3——"
                        f"违反铁律0 第1步「一镜一主任务，不贪多」。一镜只能证规模/证力量/证速度/"
                        f"证招式/证招式轨迹/证情绪 之一；多任务并存时模型会平均分配权重，"
                        f"结果每一类都渲染不清（combat-rhythm-and-load-guardrails.md §1.3）" + COMBAT_EGRESS)

            # C22c 镜内速度四拍逐镜缺拍（★逐镜判定，非全片总数——见 §2.2）
            _miss4 = {}
            for _s, _e, _ln, pic in _ranges:
                clean = _strip_struct_annot(pic)
                for beat, rx in COMBAT_BEAT_RE.items():
                    if not rx.search(clean):
                        _miss4.setdefault(beat, []).append(f"{_s}s")
            if _miss4:
                _d = "；".join(f"缺「{b}」于镜起 {','.join(v)}" for b, v in _miss4.items())
                warns.append(
                    f"C22c 镜内速度四拍不完整——{_d}。"
                    "每一镜内部都须具备『起(慢)→爆(快)→顿(停)→收(慢)』；"
                    "其中『顿』最关键：命中瞬间画面定住 2~3 帧，是『打到了』的唯一视觉证据，"
                    "缺顿拍则再多动作也读作『在乱动』（combat-rhythm-and-load-guardrails.md §2.1）" + COMBAT_EGRESS)

            # C22d 全身景别不足 / 贴脸档连续过长
            _sizes = []
            for _s, _e, _ln, pic in _ranges:
                _m = COMBAT_SIZE_RE.search(pic)
                _sizes.append(_m.group(0) if _m else "")
            _full = sum(1 for z in _sizes if z in COMBAT_FULL_SIZE)
            if _full * 2 < len(_sizes):
                warns.append(
                    f"C22d 全身入画景别仅 {_full}/{len(_sizes)} 镜（不足半数）——"
                    "全身档（中全景/中景/全景/大远景）是唯一能同时看见身体重心与双脚位置的景别；"
                    "缺全身档时观众看不到『谁把谁推到哪里』，位移只剩『撞来撞去』的读感"
                    "（combat-rhythm-and-load-guardrails.md §三）" + COMBAT_EGRESS)
            _trun, _tstart = 1, None
            _d2_done = False
            for _i in range(1, len(_sizes) + 1):
                _tight = _i < len(_sizes) and _sizes[_i] in COMBAT_TIGHT_SIZE
                if _tight:
                    if _tstart is None:
                        _tstart = _ranges[_i][0]
                    _trun += 1 if _i > 0 and _sizes[_i - 1] in COMBAT_TIGHT_SIZE else 1
                    if _trun > COMBAT_TIGHT_MAX_RUN and not _d2_done:
                        warns.append(
                            f"C22d 自 {_tstart}s 起连续 {_trun} 镜为贴脸档"
                            f"（{'/'.join(z for z in _sizes if z in COMBAT_TIGHT_SIZE)}）"
                            f"> 上限 {COMBAT_TIGHT_MAX_RUN} 镜——第三镜必须切回全身档，"
                            "否则观众丢失空间参照，动作读作『原地乱动』"
                            "（combat-rhythm-and-load-guardrails.md §三·1）" + COMBAT_EGRESS)
                        _d_done = True
                else:
                    _trun, _tstart = 1, None

    # ---------- C26 锚点继承门（2026-10-12 新增 · 剧本→资产的锚传递 · 粉丝实测反馈）----------
    # 四条 WARN 级机械判定：世界锚缺失 / 年代锚与正文冲突 / 人物年龄锚缺失 / 人物身份外观缺失。
    # 只看「声明层」与「正文层」的年代物证，不判设定对错（那是 P2 语义门）。
    _c26_meta_s = "\n".join(m.group(1) for m in re.finditer(r"【画幅风格】(.*?)(?=【场景资产】|\n【|\Z)", text, re.S))
    _c26_scn_s = "\n".join(m.group(1) for m in re.finditer(r"【场景资产】(.*?)(?=【核心人物】|【站位声明】|【时间轴分镜】|\n【|\Z)", text, re.S))
    _c26_cast_s = "\n".join(m.group(1) for m in re.finditer(r"【核心人物】(.*?)(?=【站位声明】|【时间轴分镜】|\n【|\Z)", text, re.S))
    _c26_body = text
    # C26a 世界锚缺失：画幅风格 + 场景资产两处都没有任何年代锚
    if not (C26_ERA_ANCHOR.search(_c26_meta_s) or C26_ERA_ANCHOR.search(_c26_scn_s)):
        warns.append("C26a 全稿无世界锚（年代/朝代/技术时代）——剧本层的世界观设定没有落进【画幅风格】或"
                     "【场景资产】，模型会回落到自己的默认年代（实测：设定 2035 年出片成 80 年代街景）。"
                     "修法：在【画幅风格】或【场景资产】写明年代锚（年份/朝代 + 技术时代），"
                     "权威见 sd-script-engine《世界锚卡》与 asset-spatial-ledger.md §四·E 年代锚")
    # C26b 年代锚与正文时代元素冲突
    if C26_FUTURE_ANCHOR.search(_c26_meta_s + _c26_scn_s):
        _hit_old = sorted(set([w for w in C26_OLD_ELEMS if w in _c26_body]))
        if _hit_old:
            warns.append(f"C26b 稿面声明未来/现代年代，但正文出现旧时代元素 {_hit_old[:6]}——"
                         "年代锚与画面物证自相矛盾，属「锚点没传下去」的典型病征；"
                         "按声明年代重写物证，或改回实际年代锚（权威见 asset-spatial-ledger.md §四·E）")
    if C26_PAST_ANCHOR.search(_c26_meta_s + _c26_scn_s):
        _hit_mod = sorted(set([w for w in C26_MODERN_ELEMS if w in _c26_body]))
        if _hit_mod:
            warns.append(f"C26b 稿面声明古代/近代年代，但正文出现现代元素 {_hit_mod[:6]}——"
                         "年代锚与画面物证自相矛盾（AI 幻觉现代元素的高发点），按声明年代改写或改锚")
    # C26c / C26d 人物锚：按 `@CHR-xxx：` 逐人切（**只按人切，不按「；」切**——
    # 「；」是同一人内部的分隔符，切了会把年龄锚/身份三件套拆散造成误报）
    _c26_entries = re.findall(
        r"@([A-Za-z\u4e00-\u9fff][\w\-]{0,20})\s*(?:[：:]|[（(])\s*(.*?)(?=@[A-Za-z\u4e00-\u9fff][\w\-]{0,20}\s*(?:[：:]|[（(])|\Z)",
        _c26_cast_s, re.S)
    if not _c26_entries and _c26_cast_s.strip():
        # 无 @ 锚写法（M0 文字锁稿）：整块按单人判
        _c26_entries = [("（未具名人物）", _c26_cast_s.strip())]
    _c26_no_age, _c26_no_look = [], []
    for _name, _pp in _c26_entries:
        _pp = _pp.strip()
        if not _pp:
            continue
        # 2026-10-14 用户裁定：全能参考模式（已绑定参考图N）下，P4【核心人物】只写 @CHR-名（参考图N，声线锁：…），
        # 严禁二次介绍年龄与服装外貌（二次介绍会干扰参考图）；仅无参考图（M0 或文字锁角色）时才查 C26c/C26d。
        if not C26_CAST_REF_ONLY.search(_pp):
            if not C26_AGE_ANCHOR.search(_pp) and _name not in _c26_no_age:
                _c26_no_age.append(_name)
            if not C26_LOOK_ANCHOR.search(_pp) and _name not in _c26_no_look:
                _c26_no_look.append(_name)
        else:
            # C26e：已绑定参考图N，但仍冗余复述大段静态外貌衣着（排除声线锁与本段偏离声明后仍命中外貌词且长度过长）
            _pp_clean = re.sub(r"声线锁[：:][^；;）)]*", "", _pp)
            if "偏离" not in _pp_clean and "覆盖" not in _pp_clean and "同段" not in _pp_clean:
                if C26_AGE_ANCHOR.search(_pp_clean) and C26_LOOK_ANCHOR.search(_pp_clean):
                    warns.append(
                        f"C26e 全能参考冗余二次介绍告警：【核心人物】@{_name} 已绑定参考图，却在后面二次介绍年龄与服装外貌——"
                        "全能参考直接吃参考图，二次文字介绍反而会干扰图片权重！请精简为「@CHR-角色（参考图N，声线锁：…）」"
                    )
    if _c26_no_age:
        warns.append(f"C26c 核心人物缺年龄锚 {_c26_no_age}——【核心人物】须带年龄段（如「28~32岁男性」），"
                     "否则模型自填年龄、跨镜漂移（实测：用户卡不到人物年龄）。"
                     "权威见 asset-spatial-ledger.md §角色锚点 + model-adapters.md §5.0.3 外观锚")
    if _c26_no_look:
        warns.append(f"C26d 核心人物缺身份可渲染外观 {_c26_no_look}——只有姓名/身份词没有可画的外观要素，"
                     "模型会给泛化人像（实测：外卖员出成协警）。按《身份外观三件套》补："
                     "职业标识物 + 制服/服装形制 + 气质体态；权威见 sd-asset-engine 角色资产板")
    # C26e（场景与道具侧）：【场景资产】已绑定参考图N，却在括号内二次长篇介绍建筑陈设或道具外观
    for _scn_m in re.finditer(r"@(SCN|PRP)-([\w\-\u4e00-\u9fff]+)\s*[（(]([^）)]*参考图\s*\d+[^）)]*)[）)]", _c26_scn_s):
        _kind, _aname, _abody = _scn_m.group(1), _scn_m.group(2), _scn_m.group(3)
        _abody_clean = re.sub(r"参考图\s*\d+|[：:，,；;\s]|外观以\S*锁定|关键道具|同源建筑|状态[：:][^；;）)]*", "", _abody)
        if len(_abody_clean) > 18:
            warns.append(
                f"C26e 全能参考冗余二次介绍告警：【场景资产】@{_kind}-{_aname} 已绑定参考图，却在后面二次介绍陈设/材质细节（「{_abody_clean[:18]}…」）——"
                "全能参考直接吃图，请直接精简为「@SCN-场景名（参考图N）；@PRP-道具名（参考图M）」"
            )
    # C26g 双独立道具拼图拦截（如 @PRP-鸩酒金樽与断凤钗）
    for _pm in re.finditer(r"@(?:PRP-|道具-)?([A-Za-z0-9_\u4e00-\u9fff]+(?:与|和|及)[A-Za-z0-9_\u4e00-\u9fff]+)", _c26_scn_s):
        if "场景" not in _pm.group(1):
            warns.append(
                f"C26g 复合双道具拼图告警：「{_pm.group(0)}」将两件独立道具绑在同一张设定图/同一个 @ 标签下——"
                "全能参考按整图提取特征，两件分开使用的道具拼一张图会导致端酒杯时冒出发钗、拿发钗时粘着酒杯！必须遵循「一图一独立道具」拆分为两个独立图号！"
            )
            break
    # C26f（随身核心道具跨段全程 @ 跟随检查）：若某段定义了 @PRP-道具名，而其他段正文提及该道具却未在【场景资产】@挂接
    _all_prp_names = sorted(set(re.findall(r"@PRP-([A-Za-z0-9_\u4e00-\u9fff]+)", _c26_scn_s)))
    if _all_prp_names and len(_segments_time) > 1:
        for _pname in _all_prp_names:
            _p_root = re.sub(r"(?:古剑|宝剑|长剑|佩剑|飞剑|神剑|法宝)$", "", _pname) or _pname
            for _sn, _sb, _st in _segments_time:
                _seg_scn_m = re.search(r"【场景资产】(.*?)(?=【核心人物】|【站位声明】|【时间轴分镜】|\Z)", _st, re.S)
                _seg_scn_txt = _seg_scn_m.group(1) if _seg_scn_m else ""
                if f"@PRP-{_pname}" not in _seg_scn_txt and (_pname in _st or (len(_p_root) >= 2 and _p_root in _st)):
                    warns.append(
                        f"C26f 随身/跨段关键道具漏 @ 告警：{_sn} 正文出现了道具「{_pname}」，但未在本段【场景资产】挂接「@PRP-{_pname}（参考图M）」——"
                        "随身核心道具在主角出场或使用的所有段落均须全程 @ 跟随！"
                    )

    # ---------- 融合规则补载体组：段缝末帧定格 / 背景锚点锁 / 跨项目污染（2026-10-10 并入）----------
    # 三条均为「文档级」判据（不逐镜），权威见 segment-splicing.md §二 与 quality-gate-review.md §一·补。
    # C11b 段缝末镜定格缺失——末镜行内须写「末 1 秒全体人物保持姿态与站位、动作完全静止、画面定格」，
    #   产出可截帧的定格尾帧供下一段作画面依据（空镜结尾豁免）。
    #   ★2026-10-12 用户裁定：末 1 秒为「整秒硬定格」——整秒静止 = 24 帧任选、截帧必然锐利；
    #     该秒在剪辑时整秒剪除（不进成片、不占段长），余下末帧即定格帧；其前 0.5 秒为收束窗。判据本身为
    #     "是否含定格类词"（与秒数无关），故不改正则，只改文案与规范。
    #   ⚠️2026-10-14 修复（代码体检）：旧实现取 `_tlines[-1]` **全文最后一行**——多段稿里
    #     只有**末段末镜**被检查，段1~段N-1 的段缝末镜**全部静默漏检**（实测两段稿 4 镜行只查 1 行）。
    #     真实投喂稿是「提示词组 × N 组」（3 分钟剧 ≈14 段）→ 改为**逐段检查每段末镜**。
    #     注意：段缝末镜的**存在性**只在「非末段」才要求（末段即全片结尾，本身不需给下一段作依据），
    #     但为避免误伤"最后一组也是投喂单元"的写法，统一按逐段要求，末段亦查（与旧行为对齐）。
    _c11b_miss = []
    # ★审计补丁P1：段末定格是**跨段**判据（要知谁接谁）。--by-segment 逐段跑时每段都是独立单元，
    #   无从判断"末段"，旧行为会对每个单元都报「缺定格」（实测 4 段稿连报 2 条假告警）。
    #   故逐段模式下整段跳过，改由 --whole 整份校验时判。
    for (_n, _b, _l, _blk, _ppl, _shots, _dlgs) in ([] if globals().get("_BY_SEG") else seg_zw):
        if not _shots:
            continue
        _last = _shots[-1][1]
        if len(seg_zw) > 1 and _n == seg_zw[-1][0]:
            continue  # ★：多段稿的末段之后没有下一段，不需给下段作依据（单段稿仍查，与自测口径一致）
        if (TAIL_FREEZE_WORDS and not any(w in _last for w in TAIL_FREEZE_WORDS)
                and "空镜" not in _last
                # ★2026-10-18 修：D锁②换机位硬切豁免——末镜写「接口余量 / 硬切」即按②执行，
                # ②法定不写末 1 秒定格，报 WARN 会把合法②稿退回改写①（粉丝实测踩坑）。
                and not any(w in _last for w in SEAM_MARGIN_WORDS)):
            _c11b_miss.append(_n)
    if not seg_zw:
        # 无【画幅风格】分段标记 → 退回整篇单段
        _tlines = [ln for ln in text.splitlines() if TIME_RE.search(ln)]
        if (_tlines and not any(w in _tlines[-1] for w in TAIL_FREEZE_WORDS)
                and "空镜" not in _tlines[-1]
                and not any(w in _tlines[-1] for w in SEAM_MARGIN_WORDS)):
            _c11b_miss.append("全文")
    if _c11b_miss:
        warns.append(f"C11b 段缝末镜缺定格：{_c11b_miss} 的末镜未写定格——段末镜须在行内写"
                     "「末 1 秒全体保持姿态与站位、动作完全静止、画面定格」"
                     "（其前 0.5 秒为收束窗：镜头趋缓、人物停止大幅动作），"
                     "产出可截帧的定格尾帧供下一段作画面依据；"
                     "空镜结尾豁免；**D锁②换机位硬切亦豁免**——该段末镜改写「接口余量 0.5 秒：保留未收死的运动」，"
                     "法定不写末 1 秒定格（segment-splicing.md §四·甲）")
    # C17c 背景锚点锁缺失——站位连续性的命脉是「人物相对背景不动」，不是画面坐标
    # ⚠️2026-10-14 修复（代码体检）：旧实现 `re.search` 只取**全文第一个**【站位声明】——
    #   段2 起的站位块背景锚点**全部漏检**。改为遍历 seg_zw 的**每段**站位块。
    _c17c_miss = []
    for (_n, _b, _lines, _blk, _ppl, _shots, _dlgs) in seg_zw:
        _decl = re.sub(r"^\s*【站位声明】[：:]?\s*", "", _blk or "")
        if not _decl.strip() or any(x in _decl for x in ANCHOR_EXEMPT):
            continue
        _pairs = re.findall(r"@([^\s@（）()【】，、；;：:]+)\s*[（(]([^）)]*)[）)]", _decl)
        _noanchor = [nm for nm, body in _pairs
                     if not any(w in body for w in ANCHOR_WORDS)
                     # ★审计补丁P1：站位括号内已绑【场景锚点】即视为背景锚在位
                     #   （asset-spatial-ledger §四「中文场景锚点坐标系」——锚点名本身即最可辨识背景物）
                     and not re.search(r"【[^】]{2,}】", body)]
        if _noanchor:
            _c17c_miss.append((_n, _noanchor))
    if _c17c_miss:
        _parts = [f"[{_n}] " + "、".join("@" + n for n in _ns) for _n, _ns in _c17c_miss]
        warns.append("C17c 站位声明缺背景锚点：" + "；".join(_parts) +
                     " 未绑定身后/侧后背景物——每名主要人物须绑定身后最可辨识的背景物"
                     "（墙/门/窗/树/柱/家具），跨段不得变位/消失/增生/改比例"
                     "（segment-splicing.md §二 背景锚点锁）")
    # C12b 跨项目污染（占位语 / 样例泄漏 / 调色板默认化——不是「画面长什么样」）
    _cont = sorted({w for w in CONTAMINATION_WORDS if w in _feed})
    if _cont:
        warns.append(f"C12b 跨项目污染：出现 {_cont}——占位语/样例残留/调色板默认词不是"
                     "「画面长什么样」，不得进投喂正文（quality-gate-review.md §一·补 跨项目污染专检）")

    # ---------- C23 画风锁机检（--c23 on|off|auto · style-bible/director-to-prompt-protocol.md §六）----------
    # 触发门：auto = 稿内启用 I 画风锁（段8/9 存在）或 --style-source 登记来源；
    #         未启用的旧稿不追溯（与 C21 文戏稿跳过同理，零误报是底线）。on = 强制全检（缺段即 C23a）。
    if _c23_on(text, c23, style_source):
        _c23_iss, _c23_warns = _c23_check(text, style_source)
        issues.extend(_c23_iss)
        warns.extend(_c23_warns)

    # ---------- C30 外挂指纹与跨阶段交接探针（2026-10-14 新增 · 治「外挂装了却不响」）----------
    # 触发门：--plugin auto|real|xuanhuan|combat|off（默认 auto）
    #   • C30a R3 玄幻打戏指纹：检测「尺度四件套（画框占比/量级/参照物/人物占比）」与「三层复合元素（主体层/边缘层/表面层 等）」
    #   • C30b R1 真武打戏指纹：检测「11 环动力链动词（蹬/拧/转胯/送肩/沉腰…）」与「防守三态+受击物理反馈（格挡/卸力/闪避/凹陷/弓身/滑退…）」
    #   • C30c 角色表演档案 Voice 声线锁交接：显式 --plugin，或 auto 判出 R1/R3 打戏档时，核查【核心人物】是否落了声线/音色描述
    #   • C30d 外挂激活回执头：同上触发门下，核查原稿是否包含「激活外挂 / 已读子库 / 本段调用外挂指纹」回执头
    #     ★2026-10-14 Agent 修复：原触发门只认显式 --plugin（real/xuanhuan/combat），默认 auto 整组不跑
    C30_XUANHUAN_SIG = re.compile(r"剑阵|法阵|法相|万剑|飞剑|仙侠|修仙|修真|灵力|灵气|神魔|元婴|金丹|结印|道法|天雷|阵纹|符箓|剑气化|剑罡")
    # 尺度四件套拆分为 4 个独立子维度（C30_SCALE_4：xuanhuan-combat-director V2.6.0 尺度四件套缺一即废句重写）
    C30_SCALE_FRAME = re.compile(r"占画[面框]|画面[七八九六五四三]成|半幅|满屏|[1-9]/[1-9]|八成天穹|七成天穹")
    C30_SCALE_MACRO = re.compile(r"[十百千万][米丈]|数公里|数百米|上百米|百丈|千丈|万丈|丈许粗|数十米")
    C30_SCALE_REF = re.compile(r"参照|对比|比[^，。；]{1,6}(?:高|大|粗)|牌坊|石柱|山峰|山峦|城池|古松|巨梁|山岳")
    C30_SCALE_TINY = re.compile(r"千分之一|两千分之一|四分之一|十分之一|五分之一|[1-5]%|如蝼蚁|如微尘|如细沙|渺小|仅及画面")
    # 三层复合元素硬核判据（剔除普通「气浪/流光/残影」假阳性词，必须具名三层结构或三混合配比）
    C30_ELEM_3 = re.compile(r"(?:主体层|外层)[\s\S]{1,120}(?:边缘层|中层)[\s\S]{1,120}(?:表面层|内层)|三层(?:复合|剑气|剑罡|刀芒|神雷|火浪|冰晶|水墨)")
    C30_REAL_SIG = re.compile(r"写实格斗|现代搏击|近身搏击|警匪|暗杀|擒拿|MMA|八极|咏春|泰拳|拳击|散打|R1\s*写实")
    C30_KINETIC_11 = re.compile(r"蹬地|蹬步|拧胯|转胯|转腰|拧腰|送肩|沉肩|沉腰|重心|屈膝|旋身|拧身|催肘|抖腕|脊柱")
    C30_DEF_IMPACT = re.compile(r"格挡|卸力|闪避|偏头|潜避|架开|拍开|凹陷|弓身|滑退|闷响|震颤|后仰|踉跄|擦痕|崩裂|崩碎|溢血|血沫|音爆环|深壑")
    C30_VOICE_LOCK = re.compile(r"音色|声线|嗓音|男声|女声|童声|低沉|沙哑|清冷|温润|清脆|磁性|粗粝|醇厚|语速|Hz")
    # V2.6.0 专属禁词与协议判据
    C30_STATIC_HOLD_RE = re.compile(r"双手横架死封|对撞定格|横架姿势被压|持续相持|架刀互推|贴脸对推|脸贴脸对视")
    C30_FAKE_ATK_RE = re.compile(r"轻松闪过|轻易避开|毫发无损|仅划开衣|仅划破衣")
    C30_WEAK_END_RE = re.compile(r"烟尘缓缓落定|缓缓收刀|慢悠悠收|气焰和平消散|残影粒子缓缓熄灭")
    C30_FINISHER_4_RE = re.compile(
        r"斜插[^。；]{0,12}(?:残兵|断刀|折剑|断剑|面具)|"  # 协议 A 遗物定场
        r"(?:轰飞|震飞|砸嵌|撞穿)[^。；]{0,18}(?:百米|千米|远景|岩壁|绝壁|深坑)|"  # 协议 B 物理抛飞隔离
        r"(?:瓦解|解构|化作|溃成|爆散成|溃散)[^。；]{0,18}(?:光粒|粒子|余烬|碎光|烟屑|消失)|"  # 协议 C 光粒湮灭
        r"(?:飞出画框|冲出画框|脱离画面|劈中镜头)[^。；]{0,12}硬切"  # 协议 D 战意永动硬切
    )

    if plugin != "off":
        _shot_blob_all = "\n".join(l for _, l in shot_lines)
        _is_combat_plugin = (plugin == "combat")
        _is_xuanhuan = (plugin == "xuanhuan") or (
            plugin in ("auto", "combat") and _combat_on(text, combat) and bool(C30_XUANHUAN_SIG.search(text))
        )
        _is_real = (plugin == "real") or (
            plugin in ("auto", "combat") and _combat_on(text, combat) and bool(C30_REAL_SIG.search(text))
        )
        if _is_xuanhuan and shot_lines:
            _s_miss = []
            if not C30_SCALE_FRAME.search(_shot_blob_all):
                _s_miss.append("①画框分数占比（如占画面八成/半幅）")
            if not C30_SCALE_MACRO.search(_shot_blob_all):
                _s_miss.append("②宏观尺寸量级（如百米/数十丈/丈许粗）")
            if not C30_SCALE_REF.search(_shot_blob_all):
                _s_miss.append("③五级参照物（如以十丈牌坊/石柱/山峰为参照）")
            if not C30_SCALE_TINY.search(_shot_blob_all):
                _s_miss.append("④人物渺小占比（如人物仅占画面四分之一/千分之一）")
            _has_elem = bool(C30_ELEM_3.search(_shot_blob_all))
            # 当显式开启 --plugin xuanhuan 时要求四件套全齐 AND 三层复合元素在位；auto 模式下要求至少检出大尺度与三层结构
            if (plugin == "xuanhuan" and (_s_miss or not _has_elem)) or (plugin != "xuanhuan" and len(_s_miss) >= 3 and not _has_elem):
                _detail_miss = []
                if _s_miss:
                    _detail_miss.append("尺度四件套缺：" + "、".join(_s_miss))
                if not _has_elem:
                    _detail_miss.append("缺三层复合元素（主体层/边缘层/表面层 或 外层/中层/内层）")
                warns.append(
                    "C30a R3 玄幻外挂（xuanhuan-combat-director V2.6.0）未完整落字："
                    + "；".join(_detail_miss)
                    + "——尺度四件套缺一即废句重写，特效必须写清三层复合材质（grand-scale-domains.md + xuanhuan-elements-vfx.md）"
                )
            # C30e 动词属性铁律（禁长时相持架招）
            _sh_hits = C30_STATIC_HOLD_RE.findall(_shot_blob_all)
            if _sh_hits:
                warns.append(
                    f"C30e 玄幻打戏长时相持状态词违规：「{'、'.join(sorted(set(_sh_hits)))}」——"
                    "模型会将此类状态词解析为双手架刀发呆互推3秒！必须改为瞬态爆发动词（劈中即分/震退即变招/借反弹力暴退）（core-combat-laws.md §五·3）"
                )
            # C30f 严禁假攻击与单向沙包（必须有真实受力回执）
            _fk_hits = C30_FAKE_ATK_RE.findall(_shot_blob_all)
            if _fk_hits:
                warns.append(
                    f"C30f 玄幻打戏「假攻击」违规：「{'、'.join(sorted(set(_fk_hits)))}」——"
                    "对手出招严禁写轻松闪过/毫发无损，必须产生明确受力回执（护罩崩裂/滑退数米/骨骼震颤/护甲碎裂）（core-combat-laws.md §二·2）"
                )
            # C30g 终结收束四大空间闭环协议（A/B/C/D）与禁平缓收尾
            _wk_hits = C30_WEAK_END_RE.findall(_shot_blob_all)
            if _wk_hits:
                warns.append(
                    f"C30g 玄幻打戏平缓收尾违规：「{'、'.join(sorted(set(_wk_hits)))}」——"
                    "严禁慢悠悠收刀、烟尘缓缓落定或气焰和平消散！终局必须采用协议A（天坑斜插残兵）/协议B（抛飞百米嵌远景岩壁）/协议C（肉身化漫天光粒消散）/协议D（背向飞出画框或刀光冲镜硬切）（core-combat-laws.md §一·5 & §三）"
                )
            elif plugin == "xuanhuan" and not C30_FINISHER_4_RE.search(_shot_blob_all):
                warns.append(
                    "C30g 玄幻打戏终结收束未匹配四大协议（A 遗物定场 / B 抛飞百米嵌远景岩壁 / C 肉身瓦解化光粒消散 / D 反向错车出画或刀光冲镜硬切）——"
                    "未按四协议收束极易触发模型在爆心前景凭空刷新跪地败者！（core-combat-laws.md §三 & §六）"
                )
            # C30i 空间感铁律 1：打戏中景/全景严禁 90° 侧面正拍（防横版格斗游戏廉价平面感）
            for _ln_i, _l in shot_lines:
                _hd = _shot_head(_l) or _l[:28]
                if re.search(r"中景|全景|远景", _hd) and re.search(r"90°|90度|正侧", _hd):
                    warns.append(
                        f"C30i 第{_ln_i}行 打戏空间感铁律违规：中景/全景使用了「90°侧面/正侧拍」——"
                        "会产生横版格斗游戏的廉价平面感！中景及以上必须使用 30°~60° 斜侧或低仰/斜俯拍摄（camera-specs-15modes.md §一 铁律1）"
                    )
        # C30b 法武合一：无论 R1 真武、R2 通用打戏（combat）还是 R3 玄幻打戏，只要启用了打戏 plugin，都必须具备 11 环身体动力链 + 物理/环境受击回执！
        if (_is_real or _is_combat_plugin or (_is_xuanhuan and plugin == "xuanhuan")) and shot_lines:
            _has_kin = bool(C30_KINETIC_11.search(_shot_blob_all))
            _has_def = bool(C30_DEF_IMPACT.search(_shot_blob_all))
            if not (_has_kin and _has_def):
                _miss30b = []
                if not _has_kin:
                    _miss30b.append("11环动力链身体发力词（蹬地/拧胯/转腰/脊柱/送肩/沉腰…）")
                if not _has_def:
                    _miss30b.append("防守三态与受击物理回执（格挡/卸力/崩裂/凹陷/滑退/音爆环/深壑…）")
                warns.append(
                    "C30b 打戏「法武合一·11环动力链与受击回执」缺失：缺少 " + "、".join(_miss30b)
                    + " ——严禁站桩放光波或笼统套话，必须先写身体11环发力链再长出实体特效并给出受力回执"
                      "（权威：arsenal-moves-library.md §零 + core-combat-laws.md §四 + kinetic-chain-11.md）"
                )
        # 当 --plugin combat 或 _is_real 开启时，同样启用 C30e/f/g/i 通用打戏铁律（铁律47/48 与 camera-action-specs.md 铁律1）
        if (_is_real or _is_combat_plugin) and not _is_xuanhuan and shot_lines:
            _sh_hits2 = C30_STATIC_HOLD_RE.findall(_shot_blob_all)
            if _sh_hits2:
                warns.append(
                    f"C30e 打戏长时相持状态词违规：「{'、'.join(sorted(set(_sh_hits2)))}」——"
                    "模型会将此类状态词解析为双手架刀/架拳发呆互推3秒！必须改为瞬态爆发动词（combat-iron-laws.md 铁律47③）"
                )
            _fk_hits2 = C30_FAKE_ATK_RE.findall(_shot_blob_all)
            if _fk_hits2:
                warns.append(
                    f"C30f 打戏「假攻击」违规：「{'、'.join(sorted(set(_fk_hits2)))}」——"
                    "对手出招严禁写轻松闪过/毫发无损，必须产生明确受力或环境破坏回执（defense-evasion-rules.md）"
                )
            for _ln_i, _l in shot_lines:
                _hd = _shot_head(_l) or _l[:28]
                if re.search(r"中景|全景|远景", _hd) and re.search(r"90°|90度|正侧", _hd):
                    warns.append(
                        f"C30i 第{_ln_i}行 打戏空间感铁律违规：中景/全景使用了「90°侧面/正侧拍」——"
                        "会产生横版格斗游戏的廉价平面感！中景及以上必须使用 30°~60° 斜侧或低仰/斜俯拍摄（camera-action-specs.md §二）"
                    )
        # C30j & C30k：sd-real-engine（R1 真人写实档）专属硬护栏通电（禁玄幻特效污染 + 禁悬停/超360度旋转）
        if _is_real and not _is_xuanhuan and shot_lines:
            _r1_vfx_bad = re.findall(r"剑气|剑罡|法阵|法相|万剑|飞剑|灵力|真元|神雷|光波对轰|双色粒子对冲|化作流光|法宝", _shot_blob_all)
            if _r1_vfx_bad:
                warns.append(
                    f"C30j R1 真人写实打斗特效越界污染：「{'、'.join(sorted(set(_r1_vfx_bad)))}」——"
                    "R1 写实克制档严禁出现仙侠剑气/法阵/光波对轰等超自然特效词，必须全部改为真实物理受力与环境破坏（sd-real-engine/SKILL.md §一 + r1-combat-core.md §一）"
                )
            _r1_fly_bad = re.findall(r"空中不落地|凌空悬浮|悬停半空|浮空而立|御空|旋转720|连转数圈|多周旋转", _shot_blob_all)
            if _r1_fly_bad:
                warns.append(
                    f"C30k R1 真人写实打斗腾空/旋转超限：「{'、'.join(sorted(set(_r1_fly_bad)))}」——"
                    "违反 r1-combat-core.md §八 腾空口径（跳踢离地≤1.2m、单次≤0.6s落地即卸力，严禁空中不落地/悬停帧，单次旋身≤360°）"
                )
        # C30l：打戏多人同场（multi-opponent-rules.md 1v2/1v3/2v2）三拍轮转「禁站等」与「特写禁 ≥3 人」通电
        if (_combat_on(text, combat) or _is_real or _is_xuanhuan or _is_combat_plugin) and shot_lines:
            _wait_hits = re.findall(r"原地等待|站立旁观|在旁观看|原地举刀看|在一旁等待|站着不动|旁观等待", _shot_blob_all)
            if _wait_hits:
                warns.append(
                    f"C30l 多人打戏「站等（P0阻断）」违规：「{'、'.join(sorted(set(_wait_hits)))}」——"
                    "违反 multi-opponent-rules.md §四 三拍轮转制！未与主角接触的其余敌人必须处于「压上/被击退/绕位」三种可见动态之一，严禁原地站等旁观！"
                )
            for _ln_i, _l in shot_lines:
                _si = _l.find("声音：")
                _pic_l = _l[:_si] if _si >= 0 else _l
                _hd = _shot_head(_pic_l) or _pic_l[:24]
                if CU_SHOT_RE.search(_hd):
                    _chr_mentions = set(re.findall(r"@(?:CHR-)?([A-Za-z一-鿿]{1,10})", _pic_l))
                    if len(_chr_mentions) >= 3:
                        warns.append(
                            f"C30l 第{_ln_i}行 多人打戏特写人数超限：特写/大特写镜内同时点名了 {len(_chr_mentions)} 名角色（{sorted(_chr_mentions)}）——"
                            "违反 multi-opponent-rules.md §一 & §六「特写禁 ≥3 人（必触发脸崩与分身）」！特写焦平面最多 1~2 人！"
                        )
        # ★2026-10-14 Agent 修复：回执头核验门原为 `plugin in ("real","xuanhuan","combat")`，
        #   默认 `--plugin auto`（绝大多数调用）下**整组 C30c/C30d 根本不跑**，
        #   而总控 SKILL.md 把「P3/P4 产出顶部必写回执头」「声线锁贴入 P4【核心人物】」写成硬规——
        #   形成「规则是硬门、机检默认不核」的空档（实测 S01 稿无回执头、默认参数零告警）。
        #   修法：auto 下只要已按稿内信号判出 R1 真武 / R3 玄幻打戏档，即一并核验。
        if plugin in ("real", "xuanhuan", "combat") or _is_xuanhuan or _is_real:
            # 检查原始文本（未剥离 > 引用块前）是否带【外挂激活回执头】
            if not ("激活外挂" in _raw_text_for_c30 and "已读子库" in _raw_text_for_c30 and "外挂指纹" in _raw_text_for_c30):
                warns.append(
                    "C30d 外挂激活回执头缺失：未在文档顶部检出完整的三行【外挂激活回执头】"
                    "（`> 激活外挂：…` / `> 已读子库：…` / `> 本段调用外挂指纹：…`）——"
                    "请按总控 SKILL.md ★强制读取清单自检规范补齐，证明子技能规则库已实际读取"
                    "（本项在 `--plugin auto` 下判出 R1/R3 打戏档时同样核验）"
                )
            if _c27_ran > 0 and _c26_cast_s.strip() and not C30_VOICE_LOCK.search(_c26_cast_s):
                warns.append(
                    "C30c 角色表演档案声线锁未交接：对话段【核心人物】未检出 Voice 声线/音色描述"
                    "（如「低沉沙哑男声·语速偏慢」）——P3《角色表演档案》的声线锁须贴入 P4【核心人物】行尾"
                    "（权威：references/acting-direction.md §十 Voice 声线锁）"
                )

    # ---------- STATE 跨阶段状态台账对账（--state <project_state.json> · 2026-10-14 新增）----------
    if state_data is not None:
        try:
            import sys as _sys, os as _os
            _sdir = _os.path.dirname(_os.path.abspath(__file__))
            if _sdir not in _sys.path:
                _sys.path.insert(0, _sdir)
            import sd_core as _sdc
            _st_iss, _st_wrn = _sdc.verify_feed_against_state(_raw_text_for_c30, state_data)
            issues.extend(_st_iss)
            warns.extend(_st_wrn)
        except Exception as _e:
            warns.append(f"STATE 台账对账异常：{_e}")

    return issues, warns, {"duration_s": dur, "shots": len(tr), "chars": len(text)}


def _self_test():
    ok = 1
    # 1) 合规 2.5 样例
