    # ---- 72) C23d1 Markdown 元数据剔除（2026-10-11 · 治官方示例假 FAIL）----
    _md = "# 成稿示例 · 王家卫 15 秒\n> 风格来源：F 锁 · 徐克\n| 表头 | 徐克 |\n正文无三方名。\n"
