    # 72f) C32 背景词表扩词（2026-10-16 · 治「明确的背景环境行为被漏判」）
    #   "脚下泥土犁出两道浅沟，竹叶被气浪掀飞" —— 泥土/竹/叶 原表全不在册 → 假 WARN。
