    # 75b2) ★P6 短镜豁免：单镜 5s（SD 2.5 常规镜长）里出现连续路径 → 不报 C36
    _t_c36_short = (_p5_head +
                    "- 00:00-00:05 [镜头1] 中景 · 平视 · 固定：画面主体：@男主 从门框一路摸到窗沿，"
                    "指尖沿墙面滑过去。声音：无。台词：无。\n" + _p5_tail)
    _i_c36_s, _w_c36_s = _fc(_t_c36_short)
